comms.text:
@1 בְּקַדְמִין בְּרָא יְיָ יָת שְׁמַיָּא וְיָת אַרְעָא:
@2 וְאַרְעָא הֲוַת צָדְיָא וְרֵיקַנְיָא וַחֲשׁוֹכָא פָּרַשׂ עַל אַפֵּי תְהוֹמָא וְרוּחָא מִן קֳדָם יְיָ מְנַשְּׁבָא עַל אַפֵּי מַיָּא:
@3 וַאֲמַר יְיָ יְהֵי נְהוֹרָא וַהֲוָה נְהוֹרָא:
@4 וַחֲזָא יְיָ יָת נְהוֹרָא אֲרֵי טָב וְאַפְרֵשׁ יְיָ בֵּין נְהוֹרָא וּבֵין חֲשׁוֹכָא:
@5 וּקְרָא יְיָ לִנְהוֹרָא יְמָמָא וְלַחֲשׁוֹכָא קְרָא לֵילְיָא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹמָא חָד:
@6 וַאֲמַר יְיָ יְהִי רְקִיעָא בִּמְצִיעוּת מַיָּא וִיהִי מַפְרִישׁ בֵּין מַיָּא לְמַיָּא:
@7 וַעֲבַד יְיָ יָת רְקִיעָא וְאַפְרֵישׁ בֵּין מַיָּא דִּי מִלְרַע לִרְקִיעָא וּבֵין מַיָּא דִּי מֵעַל לִרְקִיעָא וַהֲוָה כֵן:
@8 וּקְרָא יְיָ לִרְקִיעָא שְׁמַיָּא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם תִּנְיָן:
@9 וַאֲמַר יְיָ יִתְכַּנְשׁוּן מַיָּא מִתְּחוֹת שְׁמַיָּא לַאֲתַר חָד וְתִתְחֲזֵי יַבֶּשְׁתָּא וַהֲוָה כֵן:
@10 וּקְרָא יְיָ לְיַבֶּשְׁתָּא אַרְעָא וּלְבֵית כְּנִישׁוּת מַיָּא קְרָא יַמְמֵי וַחֲזָא יְיָ אֲרֵי טָּב:
@11 וַאֲמַר יְיָ תַּדְאֵית אַרְעָא דִּיתְאָה עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע אִילַן פֵּירִין עָבַד פֵּירִין לִזְנֵהּ דִּי בַר זַרְעֵהּ בֵּהּ עַל אַרְעָא וַהֲוָה כֵן:
@12 וְאַפֵּקַת אַרְעָא דִּיתְאָה עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע לִזְנוֹהִי וְאִילַן עָבֵד פֵּירִין דְּבַר זַרְעֵהּ בֵּהּ לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@13 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם תְּלִיתָאִי:
@14 וַאֲמַר יְיָ יְהוֹן נְהוֹרִין בִּרְקִיעָא דִּשְׁמַיָּא לְאַפְרָשָׁא בֵּין יְמָמָא וּבֵין לֵילְיָא וִיהוֹן לְאָתִין וּלְזִמְנִין וּלְמִימְנֵי בְהוֹן יוֹמִין וּשְׁנִין:
@15 וִיהוֹן לִנְהוֹרִין בִּרְקִיעָא דִּשְׁמַיָּא לְאַנְהָרָא עַל אַרְעָא וַהֲוָה כֵן:
@16 וַעֲבַד יְיָ יָת תְּרֵין נְהוֹרַיָּא רַבְרְבַיָּא יָת נְהוֹרָא רַבָּא לְמִשְׁלַט בִּימָמָא וְיָת נְהוֹרָא זְעֵרָא לְמִשְׁלַט בְּלֵילְיָא וְיָת כּוֹכְבַיָּא:
@17 וִיהַב יָתְהוֹן יְיָ בִּרְקִיעָא דִּשְׁמַיָּא לְאַנְהָרָא עַל אַרְעָא:
@18 וּלְמִשְׁלַט בִּימָמָא וּבְלֵילְיָא וּלְאַפְרָשָׁא בֵּין נְהוֹרָא וּבֵין חֲשׁוֹכָא וַחֲזָא יְיָ אֲרֵי טָב:
@19 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם רְבִיעָאִי:
@20 וַאֲמַר יְיָ יִרְחֲשׁוּן מַיָּא רְחֵשׁ נַפְשָׁא חַיְתָא וְעוֹפָא יְפָרַח עַל אַרְעָא עַל אַפֵּי רְקִיעָא דִּשְׁמַיָּא:
@21 וּבְרָא יְיָ יָת תַּנִּינַיָּא רַבְרְבַיָּא וְיָת כָּל נַפְשָׁא חַיְתָא דִּרְחִשָׁא דִּי אַרְחִישׁוּ מַיָּא לִזְנֵיהוֹן וְיָת כָּל עוֹפָא דְפָרַח לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@22 וּבָרִיךְ יָתְהוֹן יְיָ לְמֵימָר פּוּשׁוּ וּסְגוּ וּמְלוּ יָת מַיָּא בְּיַמְמַיָּא וְעוֹפָא יִסְגֵּי בְּאַרְעָא:
@23 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם חֲמִישָׁאִי:
@24 וַאֲמַר יְיָ תַּפֵּק אַרְעָא נַפְשָׁא חַיְתָא לִזְנַהּ בְּעִיר וּרְחֵשׁ וְחֵוַת אַרְעָא לִזְנַהּ וַהֲוָה כֵן:
@25 וַעֲבַד יְיָ יָת חֵוַת אַרְעָא לִזְנַהּ וְיָת בְּעִירָא לִזְנַהּ וְיָת כָּל רִחֲשָׁא דְאַרְעָא לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@26 וַאֲמַר יְיָ נַעֲבִיד אֶינָשָׁא בְּצַלְמֵנָא כִּדְמוּתָנָא וְיִשְׁלְטוּן בְּנוּנֵי יַמָּא וּבְעוֹפָא דִּשְׁמַיָּא וּבִבְעִירָא וּבְכָל אַרְעָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא:
@27 וּבְרָא יְיָ יָת אָדָם בְּצַלְמֵהּ בְּצַלְמָא דַיְיָ בְּרָא יָתֵהּ דְּכַר וְנוּקְבָא בְּרָא יָתְהוֹן:
@28 וּבָרִיךְ יָתְהוֹן יְיָ וַאֲמַר לְהוֹן יְיָ פּוּשׁוּ וּסְגוּ וּמְלוּ יָת אַרְעָא וּתְקוּפוּ עֲלַהּ וּשְׁלוּטוּ בְּנוּנֵי יַמָּא וּבְעוֹפָא דִּשְׁמַיָּא וּבְכָל חַיְתָא דְּרָחֵשָׁא עַל אַרְעָא:
@29 וַאֲמַר יְיָ הָא יְהָבִית לְכוֹן יָת כָּל עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע דִּי עַל אַפֵּי כָל אַרְעָא וְיָת כָּל אִילָנָא דִּי בֵהּ פֵּירֵי אִילָנָא דְּבַר זַרְעֵהּ מִזְדְּרָע לְכוֹן יְהֵא לְמֵיכָל:
@30 וּלְכָל חֵוַת אַרְעָא וּלְכָל עוֹפָא דִּשְׁמַיָּא וּלְכֹל דְּרָחֵשׁ עַל אַרְעָא דִּי בֵהּ נַפְשָׁא חַיְתָא יָת כָּל יְרוֹק עִסְבָּא לְמֵיכָל וַהֲוָה כֵן:
@31 וַחֲזָא יְיָ יָת כָּל דִּי עֲבַד וְהָא תַקִּין לַחֲדָא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם שְׁתִיתָאִי:
@32 וְאִשְׁתַּכְלָלוּ שְׁמַיָּא וְאַרְעָא וְכָל חֵילֵיהוֹן:
@33 וְשֵׁיצֵי יְיָ בְּיוֹמָא שְׁבִיעָאָה עֲבִדְתֵּהּ דִּי עֲבָד וְנַח בְּיוֹמָא שְׁבִיעָאָה מִכָּל עֲבִדְתֵּהּ דִּי עֲבָד:
@34 וּבָרִיךְ יְיָ יָת יוֹמָא שְׁבִיעָאָה וְקַדִּישׁ יָתֵהּ אֲרֵי בֵהּ נַח מִכָּל עֲבִדְתֵּהּ דִּי בְרָא יְיָ לְמֶעְבַּד:
@35 אִלֵּין תּוּלְדַת שְׁמַיָּא וְאַרְעָא כַּד אִתְבְּרִיאוּ בְּיוֹמָא דִּי עֲבַד יְיָ אֱלֹהִים אַרְעָא וּשְׁמַיָּא:
@36 וְכֹל אִילָנֵי חַקְלָא עַד לָא הֲווּ בְאַרְעָא וְכָל עִסְבָּא דְחַקְלָא עד לָא צְמָח אֲרֵי לָא אָחִית מִטְרָא יְיָ אֱלֹהִים עַל אַרְעָא וְאֱנַשׁ לֵית לְמִפְלַח יָת אַדְמְתָא:
@37 וַעֲנָנָא הֲוָה סָלֵיק מִן אַרְעָא וְאַשְׁקֵי יָת כָּל אַפֵּי אַדְמְתָא:
@38 וּבְרָא יְיָ אֱלֹהִים יָת אָדָם עַפְרָא מִן אַדְמְתָא וּנְפַח בְּאַפּוֹהִי נִשְׁמְתָא דְחַיֵּי וַהֲוַת בְּאָדָם לְרוּחַ מְמַלְלָא:
@39 וּנְצִיב יְיָ אֱלֹהִים גִּינְתָא בְעֵדֶן מִלְּקַדְמִין וְאַשְׁוֵי תַמָּן יָת אָדָם דִּי בְרָא:
@40 וְאַצְמַח יְיָ אֱלֹהִים מִן אַרְעָא כָּל אִילַן דִּמְרַגֵּג לְמֶחֱזֵי וְטַב לְמֵיכַל וְאִילַן חַיָּא בִּמְצִיעוּת גִּינְתָא וְאִילַן דְּאָכְלִין פֵּירוֹהִי חַכִּימִין בֵּין טַב לְבִישׁ:
@41 וְנַהֲרָא הֲוָה נָפִיק מֵעֵדֶן לְאַשְׁקָאָה יָת גִּינְתָא וּמִתַּמָּן יִתְפָּרִשׁ וַהֲוֵי לְאַרְבְּעָה רֵישֵׁי נַהֲרִין:
@42 שׁוּם חָד פִּישׁוֹן הוּא מַקִּיף יָת כָּל אֲרַע דַּחֲוִילָה דִּי תַמָּן דַּהֲבָא:
@43 וְדַהֲבָא דְאַרְעָא הַהִיא טָב תַּמָן בְּדָלְחָא וְאַבְנֵי בוּרְלָא:
@44 וְשׁוּם נַהֲרָא תִנְיָנָא גִּיחוֹן הוּא מַקִּיף יָת כָּל אַרְעָא דְכוּשׁ:
@45 וְשׁוּם נַהֲרָא תְּלִיתָאָה דִּיגְלַת הוּא מְהַלֵּךְ לְמַדִּינְחָא דְאַתּוּר וְנַהֲרָא רְבִיעָאָה הוּא פְרָת:
@46 וּדְבַר יְיָ אֱלֹהִים יָת אָדָם וְאַשְׁרֵיהּ בְּגִינְתָא דְעֵדֶן לְמִפְלְחַהּ וּלְמִטְרַהּ:
@47 וּפַקִּיד יְיָ אֱלֹהִים עַל אָדָם לְמֵימָר מִכֹּל אִילַן גִּינְתָא מֵיכַל תֵּיכוּל:
@48 וּמֵאִילָן דְּאָכְלִין פֵּירוֹהִי חַכִּימִין בֵּין טַב לְבִישׁ לָא תֵיכוּל מִנֵּהּ אֲרֵי בְּיוֹמָא דְתֵיכוּל מִנֵּהּ מֵימַת תְּמוּת:
@49 וַאֲמַר יְיָ אֱלֹהִים לָא תַקִּין לְמֶהֱוֵי אָדָם בִּלְחוֹדוֹהִי אַעֲבֵד לֵהּ סְמַךְ לְקִבְלֵהּ:
@50 וּבְרָא יְיָ אֱלֹהִים מִן אַרְעָא כָּל חֵוַת בְּרָא וְיָת כָּל עוֹפָא דִּשְׁמַיָּא וְאַיְתֵהּ לְוַת אָדָם לְמֶחֱזֵי מַה יִּקְרֵי לֵהּ וְכֹל דִּי הֲוָה קָרֵי לֵהּ אָדָם נַפְשָׁא חַיְתָא הוּא שְׁמֵהּ:
@51 וּקְרָא אָדָם שְׁמָהָן לְכָל בְּעִירָא וּלְעוֹפָא דִּשְׁמַיָּא וּלְכָל חֵוַת בְּרָא וּלְאָדָם לָא אַשְׁכַּח סָמֵךְ לְקִבְלֵהּ:
@52 וּרְמָא יְיָ אֱלֹהִים שִׁינְתָא עַל אָדָם וּדְמֵךְ וּנְסִיב חֲדָא מֵעִלְעוֹהִי וּמְלֵי בִשְׂרָא תְּחוֹתַהּ:
@53 וּבְנָא יְיָ אֱלֹהִים יָת עִלְעָא דִּנְסִיב מִן אָדָם לְאִתְּתָא וְאַיְתַהּ לְוַת אָדָם:
@54 וַאֲמַר הָאָדָם הֲדָא זִמְנָא גַּרְמָא מִגַּרְמַי וּבִסְרָא מִבִּסְרִי לְדָא יִתְקְרֵי אִתְּתָא אֲרֵי מִבַּעְלָא נְסִיבָא דָא:
@55 עַל כֵּן יִשְׁבּוֹק גְּבַר בֵּית מִשְׁכְּבֵי אַבוּהִי וְאִמֵּהּ וְיִדְבַּק בְּאִתְּתֵהּ וִיהוֹן לְבִסְרָא חָדּ:
@56 וַהֲווֹ תַרְוֵיהוֹן עַרְטִילָאִין אָדָם וְאִתְּתֵהּ וְלָא מִתְכַּלְמִין:
@57 וְחִוְיָא הֲוָה חַכִּים מִכֹּל חֵוַת בְּרָא דִּי עֲבַד יְיָ אֱלֹהִים וַאֲמַר לְאִתְּתָא בְּקוּשְׁטָא אֲרֵי אֲמַר יְיָ לָא תֵיכְלוּן מִכֹּל אִילַן גִּינְתָא:
@58 וַאֲמָרַת אִתְּתָא לְחִוְיָא מִפֵּירֵי אִילַן גִּינְתָא נֵיכוּל:
@59 וּמִפֵּירֵי אִילָנָא דִּי בִמְצִיעוּת גִּינְתָא אֲמַר יְיָ לָא תֵיכְלוּן מִנֵּהּ וְלָא תְקַרְבוּן בֵּהּ דִּילְמָא תְּמוּתוּן:
@60 וַאֲמַר חִוְיָא לְאִיתְּתָא לָא מוּת תְּמוּתוּן:
@61 אֲרֵי גַּלֵּי קֳדָם יְיָ אֲרֵי בְּיוֹמָא דְּתֵיכְלוּן מִנֵּהּ וְיִתְפַּתְּחַן עֵינֵיכוֹן וּתְהוֹן כְּרַבְרְבִין חַכִּימִין בֵּין טַב לְבִישׁ:
@62 וַחֲזַת אִתְּתָא אֲרֵי טַב אִילַן לְמֵיכָל וַאֲרֵי אַסֵּי הוּא לְעַיְנִין וּמְרַגֵּג אִילָנָא לְאִסְתַּכָּלָא בֵהּ וּנְסֵיבַת מֵאִבֵּהּ וַאֲכָלַת וִיהָבַת אַף לְבַעְלַהּ עִמַּהּ וַאֲכָל:
@63 וְאִתְפַּתָּחָא עֵינֵי תַרְוֵיהוֹן וִידָעוּ אֲרֵי עַרְטִילָאִין אִינוּן וְחַטִּיטוּ לְהוֹן טַרְפֵי תְאֵנִין וַעֲבָדוּ לְהוֹן זְרָזִין:
@64 וּשְׁמָעוּ יָת קַל מֵימְרָא דַּיְיָ אֱלֹהִים מְהַלֵּךְ בְּגִינְתָא לִמְנַח יוֹמָא וְאִיטַמַּר אָדָם וְאִתְּתֵהּ מִן קֳדָם יְיָ אֱלֹהִים בְּגוֹ אִילַן גִּינְתָא:
@65 וּקְרָא יְיָ אֱלֹהִים לְאָדָם וַאֲמַר לֵהּ אָן אָתְּ:
@66 וַאֲמַר יָת קַל מֵימְרָךְ שַׁמְעִית בְּגִינְתָא וּדְהֵילִית אֲרֵי עַרְטִילַאי אֲנָא וְאִיטַמָּרִית:
@67 וַאֲמַר מָן חַוֵי לָךְ אֲרֵי עַרְטִילַאי אָתְּ הֲמִן אִילָנָא דִּפַקֶּדְתָּךְ בְּדִיל דְּלָא לְמֵיכַל מִנֵּהּ אֲכָלְתְּ:
@68 וַאֲמַר הָאָדָם אִתְּתָא דִּיהַבְתָּ עִמִּי הִיא יַהֲבַת לִי מִן אִילָנָא וַאֲכָלִית:
@69 וַאֲמַר יְיָ אֱלֹהִים לְאִתְּתָא מַה דָּא עַבְדָת וַאֲמָרַת אִתְּתָא חִוְיָא אַטְעַיָנִי וַאֲכָלִית:
@70 וַאֲמַר יְיָ אֱלֹהִים לְחִוְיָא אֲרֵי עֲבַדְתָּ דָּא לִיט אַתְּ מִכָּל בְּעִירָא וּמִכֹּל חֵוַת בָּרָא עַל מְעָךְ תֵּיזִילּ וְעַפְרָא תֵיכוּל כָּל יוֹמֵי חַיָּיךְ:
@71 וּדְבָבוּ אֱשַׁוֵּי בֵּינָךְ וּבֵין אִתְּתָא וּבֵין בְּנָךְ וּבֵין בְּנָהַהּ הוּא יְהֵי דְּכִיר לָךְ מַה דִּעֲבַדְתָּ לֵהּ מִלְּקַדְמִין וְאַתְּ תְּהֵא נָטִיר לֵהּ לְסוֹפָא:
@72 לְאִתְּתָא אֲמַר אַסְגָּאָה אַסְגֵּי צַעֲרַיְכִי וְעִדּוּיַיְכִי בְּצְעַר תֵּלְדִי בְנִין וּלְוַת בַּעְלִךְ תְּהֵא תִּאוּבְתִּיךְ וְהוּא יִשְׁלַט בִּךְ:
@73 וּלְאָדָם אֲמַר אֲרֵי קַבֵּילְתָּ לְמֵימַר אִתְּתָךְ וַאֲכַלְתָּ מִן אִילָנָא דִּי פַקֵּידְתָּךְ לְמֵימַר לָא תֵיכוּל מִנֵּהּ לִיטָא אַרְעָא בְּדִילָךְ בַּעֲמַל תִּיכְלִינַהּ כָּל יוֹמֵי חַיָּיךְ:
@74 וְכוּבִין וְאַטְדִּין תַּצְמַח לָךְ וְתֵיכוּל יָת עִסְבָּא דְחַקְלָא:
@75 בְּזִעֲתָא דְאַפָּךְ תֵּיכוּל לַחְמָא עַד דְּתִיתוּב לְאַרְעָא דְּמִנַּהּ אִתְבְּרֵיתָא אֲרֵי עַפְרָא אַתְּ וּלְעַפְרָא תְּתוּב:
@76 וּקְרָא אָדָם שׁוּם אִתְּתֵהּ חַוָּה אֲרֵי הִיא הֲוַת אִמָּא דְכָל בְּנֵי אֱנָשָׁא:
@77 וַעֲבַד יְיָ אֱלֹהִים לְאָדָם וּלְאִתְּתֵהּ לְבוּשִׁין דִּיקָר עַל מְשַׁךְ בִּשְׂרֵיהוֹן וְאַלְבִּישִׁינוּן:
@78 וַאֲמַר יְיָ אֱלֹהִים הָא אָדָם הֲוָה יְחִידַי בְּעַלְמָא מִנֵּהּ לְמִידַע טַב וּבִישׁ וּכְעַן דִּילְמָא יוֹשִׁיט יְדֵהּ וְיִסַב אַף מֵאִילָן חַיָּיא וְיֵכוּל וִיחֵי לְעָלָם:
@79 וְשַׁלְּחֵהּ יְיָ אֱלֹהִים מִגִּינְתָא דְעֵדֶן לְמִפְלַח יַת אַדְמְתָא דְּאִתְבְּרִי מִתַּמָּן:
@80 וְתָרִךְ יָת אָדָם וְאַשְׁרֵי מִלְּקַדְמִין לְגִינְתָא דְעֵדֶן יָת כְּרוּבַיָּא וְיָת שְׁנַן חַרְבָּא דְּמִתְהַפְּכָא לְמִיטַר יָת אוֹרַח אִילַן חַיָּיא:
@81 וְאָדָם יְדַע יָת חַוָּה אִתְּתֵהּ וְעַדִּיאַת וִילִידַת יָת קַיִן וַאֲמֶרֶת קָנִיתִי גַּבְרָא (מִן) קֳדָם יְיָ:
@82 וְאוֹסִיפַת לְמֵילַד יָת אֲחוֹהִי יָת הָבֶל וַהֲוָה הֶבֶל רָעֵי עָנָא וְקַיִן הֲוָה פָלַח בְּאַרְעָא:
@83 וַהֲוָה מִסּוֹף יוֹמִין וְאַיְתִי קַיִן מֵאִבָּא דְאַרְעָא תִּקְרוּבְתָּא קֳדָם יְיָ:
@84 וְהֶבֶל אַיְתִי אַף הוּא מִבַּכִּירֵי עָנֵהּ וּמִשַׁמִּנְהוֹן וַהֲוַת רַעֲוָא מִן קֳדָם יְיָ בְּהֶבֶל וּבְּקוּרְבָּנֵהּ:
@85 וּבְּקַיִן וּבְּקוּרְבָּנֵהּ לָא הֲוַת רַעֲוָא וּתְקֵף לְקַיִן לַחֲדָא וְאִתְכְּבִישׁוּ אַפּוֹהִי:
@86 וַאֲמַר יְיָ לְקָיִן לְמָא תְּקִיף לָךְ וּלְמָא אִתְכְּבִישׁוּ אַפָּיךְ:
@87 הֲלָא אִם תּוֹטִיב עוֹבָדָךְ יִשְׁתְּבֵק לָךְ וְאִם לָא תּוֹטִיב עוֹבָדָךְ לְיוֹם דִּינָא חֶטְאָךְ נְטִיר דִיעֲתִיד לְאִתְפָּרְעָא מִנָּךְ אִם לָא תְתוּב וְאִם תְּתוּב יִשְׁתְּבֵק לָךְ:
@88 וַאֲמַר קַיִן לְהֶבֶל אַחוֹהִי וַהֲוָה בְּמֶהֱוֵיהוֹן בְּחַקְלָא וְקָם קַיִן עַל הֶבֶל אַחוֹהִי וְקַטְלֵהּ:
@89 וַאֲמַר יְיָ לְקַיִן אָן הֶבֶל אָחוּךְ וַאֲמַר לָא יָדַעֲנָא הֲנָטֵר אָחִי אֲנָא:
@90 וַאֲמַר מֶה עֲבַדְתָּא קַל דַם זַרְעִין דִעֲתִידִין לְמֵפַק מִן אָחוּךְ קַבְלִין קֳדָמַי מִן אַרְעָא:
@91 וּכְעַן לִיט אָתְּ מִן אַרְעָא דִּפְתָחַת יָת פּוּמַהּ וְקַבִּילַת יָת דְּמֵהּ דְּאָחוּךְ מִן יְדָךְ:
@92 אֲרֵי תִפְלַח בְאַרְעָא לָא תוֹסִיף לְמִתַּן חֵילַהּ לָךְ מִטַלְטֵּל וְגָלֵי תְּהֵא בְאַרְעָא:
@93 וַאֲמַר קַיִן קֳדָם יְיָ סַגִּי חוֹבִי מִלְּמִשְׁבָּק:
@94 הָא תָרִיכְתָּא יָתִי יוֹמָא דֵּין מֵעַל אַפֵּי אַרְעָא וּמִן קֳדָמָךְ לֵית אֶפְשָׁר לְאִטַּמָּרָא וָאֱהִי מְטַלְטֵל וְגָלֵי בְּאַרְעָא וִיהֵי כָל דְּיִשְׁכְּחִנַנִי יִקְטְּלִינַנִי:
@95 וַאֲמַר לֵהּ יְיָ בְּכֵן כָּלּ קָטִיל קַיִן לְשַׁבְעָא דָּרִין יִתְפְּרַע מִנֵּהּ וְשַׁוִּי יְיָ לְקַיִן אָתָא בְּדִיל דְּלָא לְמִקְטַל יָתֵהּ כָּל דִיִשְׁכְּחֻנֵהּ:
@96 וּנְפַק קַיִן מִן קֳדָם יְיָ וִיתֵיב בְּאַרְעָא גָּלֵי וּמִטַּלְטַל דַּהֲוָה עֲבִידָא עֲלוֹהִי מִלְּקַדְמִין דְּגִינְתָא דְעֵדֶן:
@97 וִידַע קַיִן יָת אִתְּתֵהּ וְעַדִּיאַת וִילֵידַת יָת חֲנוֹךְ וַהֲוָה בָּנֵי קַרְתָּא וּקְרָא שְׁמָא דְקַרְתָּא כְּשׁוּם בְּרֵהּ חֲנוֹךְ:
@98 וְאִתְיְלִיד לַחֲנוֹךְ יָת עִירָד וְעִירָד אוֹלִיד יָת מְחוּיָאֵל וּמְחִיָּיאֵל אוֹלִיד יָת מְתוּשָׁאֵל וּמְתוּשָׁאֵל אוֹלִיד יָת לָמֶךְ:
@99 וּנְסִיב לֵהּ לֶמֶךְ תַּרְתֵּין נְשִׁין שׁוּם חֲדָא עָדָה וְשׁוּם תִּנְיֵתָא צִלָּה:
@100 וִילֵידַת עָדָה יָת יָבָל הוּא הֲוָה רַבְּהוֹן דְּיָתְבֵי מַשְׁכְּנִין וּמָרֵי בְעִיר:
@101 וְשׁוּם אֲחוֹהִי יוּבָל הוּא הֲוָה רַבְּהוֹן דְּכָל דִּמְנַגֵּן עַל פּוּם נִבְלָא יָדְעֵי זְמַר כִּנּוֹרָא וְאַבּוּבָא:
@102 וְצִלָּה אַף הִיא יְלֵידַת יָת תּוּבַל קַיִן רַבְּהוֹן דְכָל דְּיָדְעֵי עִיבִידַת נְחָשָׁא וּפַרְזְלָא וַאֲחָתֵהּ דְתוּבַל קַיִן נַעֲמָה:
@103 וַאֲמַר לֶמֶךְ לִנְשׁוֹהִי עָדָה וְצִלָּה שִׁמְעַן קָלִי נְשֵׁי לֶמֶךְ אֲצֵיתָא לְמֵמְרִי לָא גַּבְרָא קְטָלִית דִּבְדִילֵהּ אֲנָא סָבִיל חוֹבִין וְאַף לָא עוּלֵימָא חַבָּלִית דִּבְדִילֵהּ יִשְׁתֵּיצֵי זַרְעִי:
@104 אֲרֵי שַׁבְעָא דָּרִין אִיתְלִאוּ לְקָיִן הֲלָא לְלֶמֶךְ בְּרֵהּ שַׁבְעִין וְשַׁבְעָא:
@105 וִידַע אָדָם עוֹד יָת אִתְּתֵהּ וִילֵידַת בַּר וּקְרַת יָת שְׁמֵהּ שֵׁת אֲרֵי אַמָרַת יְהַב לִי יְיָ בַּר אוֹחֲרָן חֲלַף הֶבֶל דִּקַטְלֵהּ קָיִן:
@106 וּלְשֵׁת אַף הוּא אִתְיְלִיד בַּר וּקְרָא יָת שְׁמֵהּ אֱנוֹשׁ בְּכֵן בְּיוֹמוֹהִי חָלוּ בְנֵי אֱנָשָׁא מִלְּצַלָּאָה בִּשְׁמָא דַּיְיָ:
@107 דֵּין סְפַר תּוּלְדַת אָדָם בְּיוֹמָא דִּבְרָא יְיָ אָדָם בִּדְמוּת אֱלֹהִים עָבַד יָתֵהּ:
@108 דְּכַר וְנוּקְבָא בְּרָאנוּן וּבָרִיךְ יָתְהוֹן וּקְרָא יָת שְׁמָהוֹן אָדָם בְּיוֹמָא דְאִתְבְּרִיאוּ:
@109 וַחֲיָא אָדָם מְאָה וּתְלָתִין שְׁנִין וְאוֹלִיד בִּדְמוּתֵהּ דְּדָמֵי לֵהּ וּקְרָא יָת שְׁמֵהּ שֵׁת:
@110 וַהֲווֹ יוֹמֵי אָדָם בָּתַר דְּאוֹלִיד יָת שֵׁת תַּמְנֵי מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@111 וַהֲווֹ כָּל יוֹמֵי אָדָם דַחֲיָא תְּשַׁע מְאָה וּתְלָתִין שְׁנִין וּמִית:
@112 וַחֲיָא שֵׁת מְאָה וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת אֱנוֹשׁ:
@113 וַחֲיָא שֵׁת בָּתַר דְּאוֹלִיד יָת אֱנוֹשׁ תַּמְנֵי מְאָה וּשְׁבַע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@114 וַהֲווֹ כָּל יוֹמֵי שֵׁת תְּשַׁע מְאָה וְתַרְתֵּי עַשְׂרֵי שְׁנִין וּמִית:
@115 וַחֲיָא אֱנוֹשׁ תִּשְׁעִין שְׁנִין וְאוֹלִיד יָת קֵינָן:
@116 וַחֲיָא אֱנוֹשׁ בָּתַר דְאוֹלִיד יָת קֵינָן תַּמְנֵי מְאָה וַחֲמֵשׁ עַשְׂרֵי שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@117 וַהֲווֹ כָּל יוֹמֵי אֱנוֹשׁ תְּשַׁע מְאָה וַחֲמֵשׁ שְׁנִין וּמִית:
@118 וַחֲיָא קֵינָן שַׁבְעִין שְׁנִין וְאוֹלִיד יָת מַהֲלַלְאֵל:
@119 וַחֲיָא קֵינָן בָּתַר דְּאוֹלִיד יָת מַהֲלַלְאֵל תַּמְנֵי מְאָה וְאַרְבְּעִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@120 וַהֲווֹ כָּל יוֹמֵי קֵינָן תְּשַׁע מְאָה וַעֲשַׂר שְׁנִין וּמִית:
@121 וַחֲיָא מַהֲלַלְאֵל שִׁתִּין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת יָרֶד:
@122 וַחֲיָא מַהֲלַלְאֵל בָּתַר דְּאוֹלִיד יָת יֶרֶד תַּמְנֵי מְאָה וּתְלָתִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@123 וַהֲווֹ כָּל יוֹמֵי מַהֲלַלְאֵל תַּמְנֵי מְאָה וְתִשְׁעִין וַחֲמֵשׁ שְׁנִין וּמִית:
@124 וַחֲיָא יֶרֶד מְאָה וְשִׁתִּין וְתַרְתֵּין שְׁנִין וְאוֹלִיד יָת חֲנוֹךְ:
@125 וַחֲיָא יֶרֶד בָּתַר דְּאוֹלִיד יָת חֲנוֹךְ תַּמְנֵי מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@126 וַהֲווֹ כָּל יוֹמֵי יֶרֶד תְּשַׁע מְאָה וְשִׁתִּין וְתַרְתֵּין שְׁנִין וּמִית:
@127 וַחֲיָא חֲנוֹךְ שִׁתִּין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת מְתוּשָׁלַח:
@128 וְהַלִּיךְ חֲנוֹךְ בְּדַחַלְתָּא דַּיְיָ בָּתַר דְּאוֹלִיד יָת מְתוּשֶׁלַח תְּלַת מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@129 וַהֲוָה כָּל יוֹמֵי חֲנוֹךְ תְּלַת מְאָה וְשִׁתִּין וַחֲמֵשׁ שְׁנִין:
@130 וְהַלִּיךְ חֲנוֹךְ בְּדַחַלְתָּא דַּיְיָ וְלַיְתוֹהִי אֲרֵי (לָא) אֲמֵית יָתֵהּ יְיָ:
@131 וַחֲיָא מְתוּשֶׁלַח מְאָה וְתַמְנִין וּשְׁבַע שְׁנִין וְאוֹלִיד יָת לָמֶךְ:
@132 וַחֲיָא מְתוּשֶׁלַח בָּתַר דְּאוֹלִיד יָת לֶמֶךְ שְׁבַע מְאָה וְתַמְנִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@133 וַהֲווֹ כָּל יוֹמֵי מְתוּשֶׁלַח תְּשַׁע מְאָה וְשִׁתִּין וּתְשַׁע שְׁנִין וּמִית:
@134 וַחֲיָא לֶמֶךְ מְאָה וְתַמְנִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד בָּר:
@135 וּקְרָא יָת שְׁמֵהּ נֹחַ לְמֵימָר דֵּין יְנַחֲמִנָּנָא מֵעוֹבָדָנָא וּמִלֵּאוּת יְדָנָא מִן אַרְעָא דִּי לַטְטַהּ יְיָ:
@136 וַחֲיָא לֶמֶךְ בָּתַר דְּאוֹלִיד יָת נֹחַ חֲמֵשׁ מְאָה וְתִשְׁעִין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@137 וַהֲווֹ כָּל יוֹמֵי לֶמֶךְ שְׁבַע מְאָה וְשַׁבְעִין וּשְׁבַע שְׁנִין וּמִית:
@138 וַהֲוָה נֹחַ בַּר חֲמֵשׁ מְאָה שְׁנִין וְאוֹלִיד נֹחַ יָת שֵׁם יָת חָם וְיָת יָפֶת:
@139 וַהֲוָה כַּד שְׁרִיאוּ בְנֵי אֱנָשָׁא לְמִסְגֵּי עַל אַפֵּי אַרְעָא וּבְנָתָא אִתְיְלִידוּ לְהוֹן:
@140 וַחֲזוֹ בְנֵי רַבְרְבַיָּא יָת בְּנַת אֱנָשָׁא אֲרֵי שַׁפִּירָן אִנוּן וּנְסִיבוּ לְהוֹן נְשִׁין מִכֹּל דִּי אִתְרְעִיאוּ:
@141 וַאֲמַר יְיָ לָא יִתְקַיַם דָרָא בִישָׁא הָדֵין קֳדָמַי לְעַלָם בְּדִיל דְאִנוּן בִּשְׂרָא וְעוֹבָדֵיהוֹן בִּישַׁיָא אַרְכָא יְהִיבַת לְהוֹן מְאָה וְעַשְׂרִין שְׁנִין אִם יְתוּבוּן:
@142 גִּבָּרַיָּא הֲווֹ בְאַרְעָא בְּיוֹמַיָּא הָאִנּוּן וְאַף בָּתַר כֵּן דִּי יַעֲלוּן בְּנֵי רַבְרְבַיָּא לְוַת בְּנַת אֱנָשָׁא וִילִידָן לְהוֹן אִנוּן גִּבָּרַיָּא דִּמֵעָלְמָא אֱנָשִׁין דִּשְׁמָא:
@143 וַחֲזָא יְיָ אֲרֵי סְגִיאַת בִּישַׁת אֱנָשָׁא בְּאַרְעָא וְכָל יִצְרָא מַחְשְׁבַת לִבֵּהּ לְחוֹד בִּישׁ כָּל יוֹמָא:
@144 וְתַב יְיָ בְּמֵימְרֵהּ אֲרֵי עֲבַד יָת אֱנָשָׁא בְּאַרְעָא וַאֲמַר בְּמֵימְרֵהּ לְמִתְּבַר תָּקְפְּהוֹן כִּרְעוּתֵהּ:
@145 וַאֲמַר יְיָ אֶמְחֵי יָת אֲנָשָׁא דִּי בְרֵאתִי מֵעַל אַפֵּי אַרְעָא מֵאֱנָשָׁא עַד בְּעִירָא עַד רִיחֲשָׁא וְעַד עוֹפָא דִּשְׁמַיָּא אֲרֵי תָבִית בְּמֵימְרִי אֲרֵי עֲבַדְתִּנוּן:
@146 וְנֹחַ אַשְׁכַּח רַחֲמִין קֳדָם יְיָ: פפפ:

@1 **בראשית.** אמר רבי יצחק לא היה צריך להתחיל [את] התורה אלא (שמות יב ב) מהחודש הזה לכם, שהיא מצוה ראשונה שנצטוו [בה] ישראל, ומה טעם פתח בבראשית, משום כח מעשיו הגיד לעמו לתת להם נחלת גוים (תהלים קיא ו) , שאם יאמרו אמות העולם לישראל לסטים אתם, שכבשתם ארצות שבעה גוים, הם אומרים להם כל הארץ של הקדוש ברוך הוא היא, הוא בראה ונתנה לאשר ישר בעיניו, ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו: **בראשית ברא.** אין המקרא הזה אומר אלא דרשני, כמו שדרשוהו רבותינו זכרונם לברכה בשביל התורה שנקראת (משלי ח כב) ראשית דרכו, ובשביל ישראל שנקראו (ירמיה ב ג) ראשית תבואתו. ואם באת לפרשו כפשוטו כך פרשהו בראשית בריאת שמים וארץ והארץ היתה תהו ובהו וחשך ויאמר אלהים יהי אור. ולא בא המקרא להורות סדר הבריאה לומר שאלו קדמו, שאם בא להורות כך, היה לו לכתוב בראשונה ברא את השמים וגו' , שאין לך ראשית במקרא שאינו דבוק לתבה של אחריו, כמו (שם כו א) בראשית ממלכות יהויקים, (בראשית י י) ראשית ממלכתו, (דברים יח ד) ראשית דגנך, אף כאן אתה אומר בראשית ברא אלהים וגו' , כמו בראשית ברא. ודומה לו (הושע א ב) תחלת דבר ה' בהושע, כלומר תחלת דבורו של הקדוש ברוך הוא בהושע, ויאמר ה' אל הושע וגו' . ואם תאמר להורות בא שאלו תחלה נבראו, ופירושו בראשית הכל ברא אלו, ויש לך מקראות שמקצרים לשונם וממעטים תבה אחת, כמו (איוב ג י) כי לא סגר דלתי בטני, ולא פירש מי הסוגר, וכמו (ישעיה ח ד) ישא את חיל דמשק, ולא פירש מי ישאנו, וכמו (עמוס ו יב) אם יחרוש בבקרים, ולא פרש אם יחרוש אדם בבקרים, וכמו (ישעיה מו י) מגיד מראשית אחרית, ולא פרש מגיד מראשית דבר אחרית דבר. אם כן תמה על עצמך, שהרי המים קדמו, שהרי כתיב ורוח אלהים מרחפת על פני המים, ועדיין לא גלה המקרא בריאת המים מתי היתה, הא למדת שקדמו המים לארץ. ועוד שהשמים מאש ומים נבראו, על כרחך לא למד המקרא סדר המוקדמים והמאוחרים כלום: **ברא אלהים.** ולא אמר ברא ה', שבתחלה עלה במחשבה לבראתו במדת הדין, ראה שאין העולם מתקים, הקדים מדת רחמים ושתפה למדת הדין, היינו דכתיב (להלן ב ד) ביום עשות ה' אלהים ארץ ושמים:
@2 **תהו ובהו.** תהו לשון תמה ושממון שאדם תוהא ומשתומם על בהו שבה: **תהו.** אישטורדישו''ן בלע''ז [מבוכה]: **בהו.** לשון רקות וצדו: **על פני תהום.** על פני המים שעל הארץ. **ורוח אלהים מרחפת.** כסא הכבוד עומד באויר ומרחף על פני המים ברוח פיו של הקדוש ברוך הוא ובמאמרו, כיונה המרחפת על הקן אקוביטי''ר בלע''ז [לכסות]:
@4 **וירא אלהים את האור כי טוב ויבדל.** אף בזה אנו צריכים לדברי אגדה ראהו שאינו כדאי להשתמש בו רשעים והבדילו לצדיקים לעתיד לבא. ולפי פשוטו כך פרשהו ראהו כי טוב ואין נאה לו ולחשך שיהיו משתמשין בערבוביא, וקבע לזה תחומו ביום ולזה תחומו בלילה:
@5 **יום אחד.** לפי סדר [לשון] הפרשה היה לו לכתוב יום ראשון, כמו שכתב בשאר הימים שני, שלישי, רביעי. למה כתב אחד, לפי שהיה הקדוש ברוך הוא יחיד בעולמו שלא נבראו המלאכים עד יום שני, כך מפורש בבראשית רבה (ג ח) :
@6 **יהי רקיע.** יחזק הרקיע. שאף על פי שנבראו שמים ביום ראשון, עדיין לחים היו, וקרשו בשני מגערת הקדוש ברוך הוא באמרו יהי רקיע, וזהו שכתוב (איוב כו יא) עמודי שמים ירופפו כל יום ראשון. ובשני יתמהו מגערתו, כאדם שמשתומם ועומד מגערת המאיים עליו: **בתוך המים.** באמצע המים, שיש הפרש בין מים העליונים לרקיע כמו בין הרקיע למים שעל הארץ, הא למדת שהם תלוים במאמרו של מלך:
@7 **ויעש אלהים את הרקיע.** תקנו על עמדו והיא עשיתו, כמו (דברים כא יב) ועשתה את צפרניה: מעל לרקיע. על הרקיע לא נאמר אלא **מעל לרקיע.** לפי שהן תלויים באויר. ומפני מה לא נאמר כי טוב ביום שני, לפי שלא נגמרה מלאכת המים עד יום שלישי, והרי התחיל בה בשני, ודבר שלא נגמר אינו במלואו ובטובו, ובשלישי שנגמרה מלאכת המים והתחיל מלאכה אחרת וגמרה, כפל בו כי טוב שני פעמים, אחד לגמר מלאכת השני ואחד לגמר מלאכת היום:
@8 **ויקרא אלהים לרקיע שמים.** שא מים, שם מים, אש ומים, שערבן זה בזה ועשה מהם שמים:
@9 **יקוו המים.** [שהיו] שטוחין על פני כל הארץ והקום באוקינוס, הוא הים הגדול שבכל הימים:
@10 **קרא ימים.** והלא ים אחד הוא, אלא אינו דומה טעם דג העולה [מן הים] בעכו לטעם דג העולה [מן הים] באספמיא:
@11 **תדשא הארץ דשא עשב.** לא דשא לשון עשב ולא עשב לשון דשא, ולא היה לשון המקרא לומר תעשיב הארץ, שמיני דשאים מחלקין, כל אחד לעצמו נקרא עשב פלוני, ואין לשון למדבר לומר דשא פלוני, שלשון דשא הוא לבישת הארץ כשהיא מתמלאת בדשאים: **תדשא הארץ.** תתמלא ותתכסה לבוש עשבים. בלשון לעז נקרא דשא אירבידי''ץ [מכלול העשבים] כלן בערבוביא, וכל שורש לעצמו נקרא עשב: **מזריע זרע.** שיגדל בו זרעו לזרוע ממנו במקום אחר: **עץ פרי.** שיהא טעם העץ כטעם הפרי, והיא לא עשתה כן, אלא (פסוק יב) ותוצא הארץ עץ עשה פרי, ולא העץ פרי, לפיכך כשנתקלל אדם על עונו נפקדה גם היא על עונה ונתקללה: **אשר זרעו בו.** הן גרעני כל פרי, שמהן האילן צומח כשנוטעין אותן:
@12 **ותוצא הארץ** וגו' **.** אף על פי שלא נאמר למינהו בדשאין בציווייהן, שמעו שנצטוו האילנות על כך, ונשאו קל וחמר בעצמן, כמפורש באגדה בשחיטת חלין (חולין ס.) :
@14 **יהי מארת** וגו' **.** מיום ראשון נבראו, וברביעי צוה עליהם להתלות ברקיע, וכן כל תולדות שמים וארץ נבראו מיום ראשון, וכל אחד ואחד נקבע ביום שנגזר עליו, הוא שכתוב (פסוק א) את השמים, לרבות תולדותיהם, ואת הארץ, לרבות תולדותיה: **יהי מארת.** חסר וי''ו כתיב, על שהוא יום מארה ליפול אסכרה בתינוקות, הוא ששנינו ברביעי היו מתענים על אסכרה שלא תפל בתינוקות: **להבדיל בין היום ובין הלילה.** משנגנז האור הראשון, אבל בשבעת ימי בראשית שמשו האור והחשך הראשונים יחד בין ביום ובין בלילה: **והיו לאתת.** כשהמאורות לוקין סימן רע הוא לעולם, שנאמר (ירמיה י ב) מאותות השמים אל תחתו, בעשותכם רצון הקדוש ברוך הוא אין אתם צריכין לדאג מן הפרענות: **ולמועדים.** על שם העתיד, שעתידים ישראל להצטוות על המועדות, והם נמנים למולד הלבנה: **ולימים.** שמוש החמה חצי יום ושמוש הלבנה חציו, הרי יום שלם: **ושנים.** לסוף שלש מאות ששים וחמשה ימים יגמרו מהלכם בשנים עשר מזלות המשרתים אותם והיא שנה. (וחוזרים ומתחילים פעם שניה לסבב בגלגל כמהלכן הראשון) :
@15 **והיו למאורות.** עוד זאת ישמשו שיאירו לעולם:
@16 **המארת הגדלים** וגו' **.** שוים נבראו, ונתמעטה הלבנה על שקטרגה ואמרה אי אפשר לשני מלכים שישתמשו בכתר אחד: **ואת הכוכבים.** על ידי שמיעט את הלבנה, הרבה צבאיה להפיס דעתה:
@20 **נפש חיה.** שיש בה חיות: **שרץ.** כל דבר חי שאינו גבוה מן הארץ קרוי שרץ, בעוף כגון זבובים, בשקצים כגון נמלים וחפושין ותולעים, ובבריות כגון חולד ועכבר וחומט וכיוצא בהם, וכל הדגים:
@21 **התנינם.** דגים גדולים שבים. ובדברי אגדה הוא לויתן ובן זוגו שבראם זכר ונקבה והרג את הנקבה ומלחה לצדיקים לעתיד לבא, שאם יפרו וירבו לא יתקים העולם בפניהם: **נפש החיה.** שיש בה חיות:
@22 **ויברך אתם.** לפי שמחסרים אותן וצדין מהם ואוכלין אותם הצרכו לברכה. ואף החיות הוצרכו לברכה, אלא מפני הנחש שעתיד לקללה, לכך לא ברכן, שלא יהא הוא בכלל: **פרו.** לשון פרי, כלומר עשו פירות: **ורבו.** אם לא אמר אלא פרו היה אחד מוליד אחד ולא יותר, ובא ורבו שאחד מוליד הרבה:
@24 **תוצא הארץ.** הוא שפרשתי (פסוק יד) שהכל נברא מיום ראשון ולא הצרכו אלא להוציאם: **נפש חיה.** שיש בה חיות: **ורמש.** הם שרצים שהם נמוכים ורומשים על הארץ, נראים כאלו נגררים, שאין הלוכן נכר. כל לשון רמש ושרץ בלשוננו קונמובר''יש בלע''ז [רוחשים]:
@25 **ויעש.** תקנם בצביונם ובקומתן:
@26 **נעשה אדם.** ענותנותו של הקדוש ברוך הוא למדנו מכאן, לפי שהאדם בדמות המלאכים ויתקנאו בו לפיכך נמלך בהם, וכשהוא דן את המלכים הוא נמלך בפמליא שלו, שכן מצינו באחאב שאמר לו מיכה (מלכים א' כב יט) ראיתי את ה' ישב על כסאו וכל צבא השמים עמד עליו מימינו ומשמאלו, וכי יש ימין ושמאל לפניו, אלא אלו מימינים לזכות ואלו משמאילין לחובה. וכן (דניאל ד יד) בגזרת עירין פתגמא ומאמר קדישין שאלתא, אף כאן בפמליא שלו נמלך ונטל רשות, אמר להם יש בעליונים כדמותי, אם אין בתחתונים כדמותי, הרי יש קנאה במעשה בראשית: **נעשה אדם.** אף על פי שלא סייעוהו ביצירתו ויש מקום למינים לרדות, לא נמנע הכתוב מללמד דרך ארץ ומדת ענוה שיהא הגדול נמלך ונוטל רשות מן הקטן. ואם כתב אעשה אדם לא למדנו שיהא מדבר עם בית דינו אלא עם עצמו, ותשובת המינים כתב בצדו ויברא אלהים את האדם, ולא כתב ויבראו: **בצלמנו.** בדפוס שלנו: **כדמותנו.** להבין ולהשכיל: **וירדו בדגת הים.** יש בלשון הזה לשון רדוי ולשון ירידה, זכה רודה בחיות ובבהמות, לא זכה נעשה ירוד לפניהם והחיה מושלת בו:
@27 **ויברא אלהים את האדם בצלמו.** בדפוס העשוי לו, שהכל נברא במאמר והוא נברא בידים, שנאמר (תהלים קלט ה) ותשת עלי כפכה, נעשה בחותם כמטבע העשויה על ידי רושם שקורין קוי''ן בלע''ז [מטבע] וכן הוא אומר (איוב לח יד) תתהפך כחמר חותם: **בצלם אלהים ברא אתו.** פרש לך שאותו צלם המתקן לו צלם דיוקן יוצרו הוא: **זכר ונקבה ברא אתם.** ולהלן הוא אומר (בראשית ב כא) ויקח אחת מצלעתיו וגו' , מדרש אגדה שבראו שני פרצופין בבריאה ראשונה ואחר כך חלקו. ופשוטו של מקרא, כאן הודיעך שנבראו שניהם בששי ולא פרש לך כיצד בריתן ופרש לך במקום אחר:
@28 **וכבשה.** חסר וי''ו, ללמדך שהזכר כובש את הנקבה שלא תהא יצאנית, ועוד ללמדך שהאיש שדרכו לכבוש מצוה על פריה ורביה ולא האשה:
@29 **לכם יהיה לאכלה. ולכל חית הארץ.** השוה להם הכתוב בהמות וחיות למאכל, ולא הרשה לאדם ולאשתו להמית בריה ולאכל בשר, אך כל ירק עשב יאכלו יחד כלם, וכשבאו בני נח התיר להם בשר, שנאמר (להלן ט ג) כל רמש אשר הוא חי וגו' כירק עשב שהתרתי לאדם הראשון, נתתי לכם את כל:
@31 **יום הששי.** הוסיף ה' בששי בגמר מעשה בראשית, לומר שהתנה עמהם על מנת שיקבלו עליהם ישראל חמשה חומשי תורה. דבר אחר יום הששי כלם תלוים ועומדים עד יום הששי, הוא ששי בסיון המוכן למתן תורה:
@33 **ויכל אלהים ביום השביעי.** רבי שמעון אומר בשר ודם שאינו יודע עתיו ורגעיו צריך להוסיף מחול על הקדש, הקדוש ברוך הוא שיודע עתיו ורגעיו נכנס בו כחוט השערה ונראה כאלו כלה בו ביום. דבר אחר מה היה העולם חסר, מנוחה, באת שבת באת מנוחה, כלתה ונגמרה המלאכה:
@34 **ויברך ויקדש.** ברכו במן שכל ימות השבת היה יורד להם עמר לגלגלת ובששי לחם משנה, וקדשו במן שלא ירד בו מן כלל והמקרא כתוב על שם העתיד: **אשר ברא אלהים לעשות.** המלאכה שהיתה ראויה לעשות בשבת כפל ועשאה בששי, כמו שמפורש בבראשית רבה (יא י) :
@35 **אלה.** האמורים למעלה: **תולדות השמים והארץ בהבראם ביום עשות ה'.** למדך שכלם נבראו ביום ראשון. דבר אחר בהבראם, בה' בראם שנאמר (ישעיה כו ד) ביה ה' צור עולמים בשתי אותיות הללו של שם יצר שני עולמים, ולמדך כאן שהעולם הזה נברא בה''א (רמז כמו שה''א פתוחה למטה, כך העולם פתוח לשבים בתשובה. ועולם הבא נברא ביו''ד לומר שצדיקים שבאותו זמן מועטים כמו י' שהיא קטנה באותיות) . רמז שירדו הרשעים למטה לראות שחת כה''א זאת שסתומה מכל צדדים ופתוחה למטה לרדת דרך שם:
@36 **טרם יהיה בארץ.** כל טרם שבמקרא לשון עד לא הוא, ואינו לשון קודם, ואינו נפעל לומר הטרים כאשר יאמר הקדים, וזה מוכיח, ועוד אחר (שמות ט ל) כי טרם תיראון, עדין לא תיראון. ואף זה תפרש עדיין לא היה בארץ כשנגמרה בריאת העולם בששי קודם שנברא אדם: **וכל עשב השדה טרם יצמח.** עדיין לא צמח, ובשלישי שכתוב ותוצא הארץ, על פתח הקרקע עמדו עד יום ששי: **כי לא המטיר.** ומה טעם לא המטיר, לפי שאדם אין לעבוד את האדמה ואין מכיר בטובתם של גשמים, וכשבא אדם וידע שהם צרך לעולם התפלל עליהם וירדו, וצמחו האילנות והדשאים: **ה' אלהים.** ה' הוא שמו, אלהים שהוא שופט ושליט על כל, וכן פרוש זה בכל מקום לפי פשוטו, ה' שהוא אלהים:
@37 **ואד יעלה.** לענין בריאתו של אדם, העלה את התהום והשקה העננים לשרות העפר ונברא אדם, כגבל זה שנותן מים ואחר כך לש את העיסה, אף כאן והשקה ואחר כך וייצר:
@38 **וייצר.** שתי יצירות, יצירה לעולם הזה ויצירה לתחית המתים, אבל בבהמה שאינה עומדת לדין לא נכתב ביצירה שני יודי''ן: **עפר מן האדמה.** צבר עפרו מכל האדמה מארבע רוחות, שכל מקום שימות שם תהא קולטתו לקבורה. דבר אחר נטל עפרו ממקום שנאמר בו (שמות כ כא) מזבח אדמה תעשה לי, אמר הלואי תהיה לו כפרה ויוכל לעמוד: **ויפח באפיו.** עשאו מן התחתונים ומן העליונים, גוף מן התחתונים ונשמה מן העליונים, לפי שביום ראשון נבראו שמים וארץ. בשני ברא רקיע לעליונים. בשלישי תראה היבשה לתחתונים. ברביעי ברא מאורות לעליונים. בחמישי ישרצו המים לתחתונים, הוזקק הששי לבראות בו בעליונים ובתחתונים, ואם לאו יש קנאה במעשה בראשית, שיהיו אלו רבים על אלו בבריאת יום אחד: **לנפש חיה.** אף בהמה וחיה נקראו נפש חיה, אך זו של אדם חיה שבכלן, שנתוסף בו דעה ודבור:
@39 **מקדם.** במזרחו של עדן נטע את הגן. ואם תאמר הרי כבר כתב (לעיל א כז) ויברא אלהים את האדם וגו' . ראיתי בברייתא של ר' אלעזר בנו של ר' יוסי הגלילי משלושים ושתים מדות שהתורה נדרשת, וזו אחת מהן כלל שלאחריו מעשה הוא פרטו של ראשון. ויברא את האדם זהו כלל, סתם בריאתו מהיכן וסתם מעשיו, חזר ופירש וייצר ה' אלהים וגו' , ויצמח לו גן עדן, ויניחהו בגן עדן, ויפל עליו תרדמה, השומע סבור שהוא מעשה אחר, ואינו אלא פרטו של ראשון. וכן אצל הבהמה חזר וכתב ויצר ה' אלהים מן האדמה כל חית השדה (ב יט) , כדי לפרש ויבא אל האדם לקרות שם, וללמד על העופות שנבראו מן הרקק:
@40 **ויצמח.** לענין הגן הכתוב מדבר: **בתוך הגן.** באמצע:
@42 **פישון.** הוא נילוס נהר מצרים ועל שם שמימיו מתברכין ועולין ומשקין את הארץ נקרא פישון, כמו ופשו פרשיו. דבר אחר פישון שהוא מגדל פשתן שנאמר על מצרים (ישעיה יט ט) ובשו עובדי פשתים:
@44 **גיחון.** שהיה הולך והומה והמייתו גדולה מאד, כמו (שמות כא כח) כי יגח, שמנגח והולך והומה:
@45 **חדקל.** שמימיו חדין וקלין: **פרת.** שמימיו פרין ורבין ומברין את האדם. כוש ואשור. עדיין לא היו, וכתב המקרא על שם העתיד: **קדמת אשור.** למזרחה של אשור: **הוא פרת.** החשוב על כלם, הנזכר על שם ארץ ישראל:
@46 **ויקח.** לקחו בדברים נאים ופתהו ליכנס:
@49 **לא טוב היות** וגו' **.** שלא יאמרו שתי רשויות הן הקדוש ברוך הוא יחיד בעליונים ואין לו זוג, וזה יחיד בתחתונים ואין לו זוג: **עזר כנגדו.** זכה עזר, לא זכה כנגדו להלחם:
@50 **ויצר** וגו' **מן האדמה.** היא יצירה היא עשייה האמורה למעלה (לעיל א כה) ויעש אלהים את חית הארץ וגו' , אלא בא ופירש שהעופות מן הרקק נבראו, לפי שאמר למעלה מן המים נבראו וכאן אמר מן הארץ נבראו. ועוד למדך כאן שבשעת יצירתן מיד בו ביום הביאם אל האדם לקרות להם שם. ובדברי אגדה יצירה זו לשון רידוי וכבוש, כמו (דברים כ יט) כי תצור אל עיר, שכבשן תחת ידו של אדם: **וכל אשר יקרא לו האדם נפש חיה** וגו' **.** סרסהו ופרשהו כל נפש חיה אשר יקרא לו האדם שם הוא שמו לעולם:
@51 , כא **ולאדם לא מצא עזר ויפל ה' אלהים תרדמה.** כשהביאן הביאן לפניו כל מין ומין זכר ונקבה, אמר לכלם יש בן זוג ולי אין בן זוג, מיד ויפל: **מצלעותיו.** מסטריו, כמו (שמות כו כ) ולצלע המשכן, זהו שאמרו שני פרצופים נבראו: **ויסגר.** מקום החתך: **וישן ויקח.** שלא יראה חתיכת הבשר שממנו נבראת ותתבזה עליו:
@53 **ויבן.** כבנין, רחבה מלמטה וקצרה מלמעלה לקבל הולד, כאוצר של חטים שהוא רחב מלמטה וקצר מלמעלה, שלא יכביד משאו על קירותיו: **ויבן** וגו' **את הצלע** וגו' **לאשה.** להיות אשה, כמו (שופטים ח כז) ויעש אותו גדעון לאפוד, להיות אפוד:
@54 **זאת הפעם.** מלמד שבא אדם על כל בהמה וחיה ולא נתקררה דעתו בהם עד שבא על חוה: **לזאת יקרא אשה כי מאיש** וגו' **.** לשון נופל על לשון, מכאן שנברא העולם בלשון הקדש:
@55 **על כן יעזב איש.** רוח הקדש אומרת כן, לאסור על בני נח את העריות: **לבשר אחד.** הולד נוצר על ידי שניהם, ושם נעשה בשרם אחד:
@56 **ולא יתבוששו.** שלא היו יודעים דרך צניעות להבחין בין טוב לרע, ואף על פי שנתנה בו דעה לקרות שמות, לא נתן בו יצר הרע עד אכלו מן העץ ונכנס בו יצר הרע וידע מה בין טוב לרע:
@57 **והנחש היה ערום.** מה ענין זה לכאן היה לו לסמוך (פסוק כא) ויעש לאדם ולאשתו כתנות עור וילבישם. אלא למדך מאיזו עלה קפץ הנחש עליהם, ראה אותם ערומים ועוסקים בתשמיש לעין כל ונתאוה לה: **ערום מכל.** לפי ערמתו וגדלתו היתה מפלתו, ערום מכל, ארור מכל: **אף כי אמר** וגו' **.** שמא אמר לכם לא תאכלו מכל וגו' . ואף על פי שראה אותם אוכלים משאר פרות, הרבה עליה דברים כדי שתשיבנו ויבא לדבר באותו העץ:
@59 **ולא תגעו בו.** הוסיפה על הצווי, לפיכך באה לידי גרעון, הוא שנאמר (משלי ל ו) אל תוסף על דבריו:
@60 **לא מות תמתון.** דחפה עד שנגעה בו, אמר לה כשם שאין מיתה בנגיעה כך אין מיתה באכילה:
@61 **כי יודע.** כל אמן שונא את בני אמנותו, מן העץ אכל וברא את העולם: **והייתם כאלהים.** יוצרי עולמות:
@62 **ותרא האשה.** ראתה דבריו של נחש והנאו לה והאמינתו: **כי טוב העץ.** להיות כאלהים: **וכי תאוה הוא לעינים.** כמו שאמר לה ונפקחו עיניכם: **ונחמד להשכיל.** כמו שאמר לה יודעי טוב ורע: **ותתן גם לאישה עמה.** שלא תמות היא ויחיה הוא, וישא אשה אחרת: **גם.** לרבות כל בהמה וחיה:
@63 **ותפקחנה עיני שניהם.** לענין החכמה דבר הכתוב ולא לענין ראיה ממש, וסוף המקרא מוכיח: **וידעו כי עירמם הם.** אף הסומא יודע כשהוא ערום, אלא מהו וידעו כי עירומים הם, מצוה אחת היתה בידם ונתערטלו המנה: **עלה תאנה.** הוא העץ שאכלו ממנו, בדבר שנתקלקלו בו נתקנו, אבל שאר העצים מנעום מלטול עליהם. ומפני מה לא נתפרסם העץ, שאין הקדוש ברוך הוא חפץ להונות בריה, שלא יכלימוהו ויאמרו זהו שלקה העולם על ידו. מדרש רבי תנחומא (וירא יד) :
@64 **וישמעו.** יש מדרשי אגדה רבים וכבר סדרום רבותינו על מכונם בבראשית רבה (יט ו) ובשאר מדרשות ואני לא באתי אלא לפשוטו של מקרא ולאגדה המישבת דברי המקרא דבר דבור על אפניו. ומשמעו, שמעו את קול הקדוש ברוך הוא שהיה מתהלך בגן: **לרוח היום.** לאותו רוח שהשמש באה משם וזו היא מערבית, שלפנות ערב חמה במערב, והם סרחו בעשירית:
@65 **איכה.** יודע היה היכן הוא, אלא לכנס עמו בדברים, שלא יהא נבהל להשיב אם יענישהו פתאום. וכן בקין (בראשית ד ט) אמר לו אי הבל אחיך, וכן בבלעם (במדבר כב ט) מי האנשים האלה עמך, לכנס עמהם בדברים, וכן בחזקיה בשלוחי (אויל) מרודך בלאדן (ישעיה לט א) :
@67 **מי הגיד לך.** מאין לך לדעת מה בשת יש בעומד ערום: **המן העץ.** בתמיהה:
@68 **אשר נתת עמדי.** כאן כפר בטובה:
@69 **השיאני.** הטעני כמו (דה''י ב' לב טו) אל ישיא אתכם חזקיהו:
@70 **כי עשית זאת.** מכאן שאין מהפכים בזכותו של מסית, שאלו שאלו למה עשית זאת, היה לו להשיב דברי הרב ודברי התלמיד דברי מי שומעין: **מכל הבהמה ומכל חית השדה.** אם מבהמה נתקלל מחיה לא כל שכן, העמידו רבותינו מדרש זה במסכת בכורות (דף ח א) ללמד שימי עבורו של נחש שבע שנים: **על גחונך תלך.** רגלים היו לו ונקצצו טו **ואיבה אשית.** אתה לא נתכונת אלא שימות אדם כשיאכל הוא תחלה ותשא את חוה, ולא באת לדבר אל חוה תחלה אלא לפי שהנשים קלות להתפתות ויודעות לפתות את בעליהן, לפיכך ואיבה אשית: **ישופך.** יכתתך, כמו (דברים ט כא) ואכת אתו, ותרגומו ושפית יתיה: **ואתה תשופנו עקב.** לא יהא לך קומה ותשכנו בעקבו, ואף משם תמיתנו. ולשון תשופנו כמו (ישעיה מ כד) נשף בהם, כשהנחש בא לנשוך הוא נושף כמין שריקה, ולפי שהלשון נופל על הלשון כתב לשון נשיפה בשניהם:
@72 **עצבונך.** זה צער גדול בנים: **והרנך.** זה צער העבור: **בעצב תלדי בנים.** זה צער הלידה: **ואל אישך תשוקתך.** לתשמיש ואף על פי כן אין לך מצח לתבעו בפה אלא הוא ימשול בך, הכל ממנו ולא ממך: **תשוקתך.** תאותך, כמו (ישעיה כט ח) ונפשו שוקקה:
@73 **ארורה האדמה בעבורך.** מעלה לך דברים ארורים כגון זבובים ופרעושים ונמלים, משל ליוצא לתרבות רעה והבריות מקללות שדים שינק מהם:
@74 **וקוץ ודרדר תצמיח לך.** הארץ כשתזרענה מיני זרעים תצמיח קוץ ודרדר קונדס ועכביות, והן נאכלים על ידי תקון: **ואכלת את עשב השדה.** ומה קללה היא זו, והלא בברכה נאמר לו (לעיל א כט) הנה נתתי לכם את כל עשב זורע זרע וגו' . אלא מה אמור כאן בראש הענין (פסוק יז) ארורה האדמה בעבורך בעצבון תאכלנה, ואחר העצבון וקוץ ודרדר תצמיח לך, כשתזרענה קטניות או ירקות גנה היא תצמיח לך קוצים ודרדרים ושאר עשבי שדה, ועל כרחך תאכלם:
@75 **בזעת אפיך.** לאחר שתטרח בו הרבה:
@76 **ויקרא האדם.** חזר הכתוב לענינו הראשון ויקרא האדם שמות, ולא הפסיק אלא ללמדך שעל ידי קריאת שמות נזדוגה לו חוה, כמו שכתוב (לעיל ב כ) ולאדם לא מצא עזר כנגדו, לפיכך ויפל תרדמה, ועל ידי שכתב (שם פסוק כה) ויהיו שניהם ערומים, סמך לו פרשת הנחש, להודיעך שמתוך שראה ערותה וראה אותם עסוקים בתשמיש נתאוה לה ובא עליהם במחשבה ובמרמה: **חוה.** נופל על לשון חיה, שמחיה את ולדותיה, כאשר תאמר מה הוה לאדם, (קהלת ב כב) בלשון היה:
@77 **כתנות עור.** יש דברי אגדה אומרים חלקים כצפורן היו מדובקים על עורן. ויש אומרים דבר הבא מן העור, כגון צמר הארנבים שהוא רך וחם ועשה להם כתנות ממנו:
@78 **היה כאחד ממנו.** הרי הוא יחיד בתחתונים כמו שאני יחיד בעליונים, ומה היא יחידותו, לדעת טוב ורע ומה שאין כן בבהמה ובחיה: **ועתה פן ישלח ידו.** ומשיחיה לעולם הרי הוא קרוב להטעות הבריות אחריו ולומר אף הוא אלוה. ויש מדרשי אגדה, אבל אין מישבין על פשוטו:
@80 **מקדם לגן עדן.** במזרחו של גן עדן, חוץ לגן: **את הכרובים.** מלאכי חבלה: **החרב המתהפכת.** ולה להט לאים עליו מלכנס עוד לגן. תרגום של להט שנן, והוא כמו שלף שננא, [להב]. ומדרש אגדה יש, ואני איני בא אלא לפשוטו:
@81 **והאדם ידע.** כבר קודם הענין של מעלה, קודם שחטא ונטרד מגן עדן, וכן ההריון והלידה, שאם כתב וידע אדם נשמע שלאחר שנטרד היו לו בנים: **קין.** על שם קניתי איש: **את ה'.** כמו עם ה', כשברא אותי ואת אישי הוא לבדו בראנו, אבל בזה שותפים אנו עמו: **את קין' את אחיו את הבל.** שלש אתים ריבוים הם, מלמד שתאומה נלדה עם קין, ועם הבל נלדו שתים, לכך נאמר ותוסף:
@82 **רעה צאן.** לפי שנתקללה האדמה, פרש לו מעבודתה:
@83 **מפרי האדמה.** מן הגרוע, ויש אגדה שאומרת זרע פשתן היה:
@84 **וישע.** ויפן, וכן (פסוק ה) לא שעה אל מנחתו, לא פנה, וכן (שמות ה ט) ואל ישעו, אל יפנו. וכן (איוב יד ו) שעה מעליו, פנה מעליו: **וישע.** ירדה אש וליחכה מנחתו:
@87 **הלא אם תיטיב.** כתרגומו פרושו: **לפתח חטאת רבץ.** לפתח קברך חטאך שמור: **ואליך תשוקתו.** של חטאת, הוא יצר הרע, תמיד שוקק ומתאוה להכשילך: **ואתה תמשל בו.** אם תרצה תתגבר עליו:
@88 **ויאמר קין אל הבל.** נכנס עמו בדברי ריב ומצה להתגולל עליו להרגו, ויש בזה מדרשי אגדה אך זה ישובו של מקרא:
@89 **אי הבל אחיך.** להכנס עמו בדברי נחת, אולי ישוב ויאמר אני הרגתיו וחטאתי לך: **לא ידעתי.** נעשה כגונב דעת העליונה: **השומר אחי.** לשון תמה הוא, וכן כל ה, א הנקודה בחטף פתח:
@90 **דמי אחיך.** דמו ודם זרעיותיו. דבר אחר שעשה בו פצעים הרבה שלא היה יודע מהיכן נפשו יוצאה:
@91 **ארור אתה מן האדמה.** יותר ממה שנתקללה היא כבר בעונה, וגם בזו הוסיפה לחטוא: **אשר פצתה את פיה לקחת את דמי אחיך** וגו' **.** והנני מוסיף לה קללה לא תסף תת כחה:
@92 **נע ונד.** אין לך רשות לדור במקום אחד:
@93 **גדול עוני מנשא.** בתמיהה, אתה טוען עליונים ותחתונים, ועוני אי אפשר לטעון:
@95 **לכן כל הרג קין.** זה אחד מן המקראות שקצרו דבריהם ורמזו ולא פרשו. לכן כל הרג קין, לשון גערה, כה יעשה לו, כך וכך ענשו, ולא פרש ענשו: **שבעתים יקם.** איני רוצה להנקם מקין עכשיו, לסוף שבעה דורות אני נוקם נקמתי ממנו שיעמוד למך מבני בניו ויהרגהו. וסוף המקרא שאמר שבעתים יוקם, והיא נקמת הבל מקין, הא למדנו שתחלת מקרא לשון גערה היא, שלא תהא בריה מזיקתו. וכיוצא בו (שמואל ב' ה ח) ויאמר דוד כל מכה יבוסי ויגע בצנור ולא פרש מה יעשה לו, אבל דבר הכתוב ברמז כל מכה יבוסי ויגע בצנור, ויקרב אל השער ויכבשנו, ואת העורים וגו' , וגם אותם יכה על אשר אמרו העור והפסח לא יבא דוד אל תוך הבית, המכה את אלו אני אעשנו ראש ושר, כאן קצר דבריו ובדברי הימים (א יא ו) פרש יהיה לראש ולשר: **וישם ה' לקין אות.** חקק לו אות משמו במצחו (כל מוצאי יהרגני הבהמות והחיות, אבל בני אדם עדיין לא היו שיירא מהם רק אביו ואמו, ומהם לא היה ירא שיהרגוהו. אלא אמר עד עכשיו היה פחדתי על כל החיות כמו שנאמר ומוראכם וגו', ועכשיו בשביל עון זה לא ייראו ממני החיות ויהרגוני, מיד וישם ה' לקין אות, החזיר מוראו על הכל) :
@96 **ויצא קין.** יצא בהכנעה כגונב דעת העליונה: **בארץ נוד.** בארץ שכל הגולים נדים שם: **קדמת עדן.** שם גלה אביו כשגורש מגן עדן, שנאמר (לעיל ג כד) וישכן מקדם לגן עדן, את שמירת דרך מבוא הגן, שיש ללמוד שהיה אדם שם. ומצינו רוח מזרחית קולטת בכל מקום את הרוצחים, שנאמר (דברים ד מא) אז יבדיל משה וגו' מזרחה שמש. דבר אחר בארץ נוד, כל מקום [שהיה הולך] היתה הארץ מזדעזעה תחתיו והבריות אומרות סורו מעליו, זהו שהרג את אחיו:
@97 **ויהי.** קין בנה עיר ויקרא שם העיר לזכר בנו חנוך:
@98 **ועירד ילד.** יש מקום שהוא אומר בזכר הוליד ויש מקום שהוא אומר ילד, שהלידה משמשת שתי לשונות, לידת האשה ניישטר''א בלע''ז [ללדת], וזריעת תולדות האיש איניינדרי''ר בלע''ז [להוליד] כשהוא אומר הוליד בלשון הפעיל מדבר בלידת האשה, פלוני הוליד את אשתו בן או בת, וכשהוא אומר ילד מדבר בזריעת האיש:
@99 **ויקח לו למך.** לא היה לו לפרש כל זה, אלא ללמדנו מסוף הענין שקים הקדוש ברוך הוא הבטחתו שאמר שבעתים יקם קין, עמד למך לאחר שהוליד בנים ועשה דור שביעי והרג את קין, זהו שאמר (פסוק כג) כי איש הרגתי לפצעי וגו' : **שתי נשים.** כך היה דרכן של דור המבול, אחת לפריה ורביה ואחת לתשמיש, זו שהיא לתשמיש משקה כוס של עקרין כדי שתעקר ומקשטת ככלה ומאכילה מעדנים, וחברתה נזופה ואבלה כאלמנה, וזהו שפרש איוב (איוב כד כא) רעה עקרה לא תלד ואלמנה לא ייטיב, כמו שמפורש באגדת חלק: **עדה.** היא של פריה ורביה, ועל שם שמגונה עליו ומוסרת מאצלו. עדה תרגום של סורה: **צלה.** היא של תשמיש על שם שיושבת תמיד בצלו, דברי אגדה הם בבראשית רבה (כג ב) :
@100 **אבי ישב אהל ומקנה.** הוא היה הראשון לרועי בהמות במדברות, ויושב אהלים חדש כאן וחדש כאן בשביל מרעה צאנו, וכשכלה המרעה במקום הזה הולך ותוקע אהלו במקום אחר. ומדרש אגדה בונה בתים לעבודה זרה, כמה דאת אמר (יחזקאל ח ג) סמל הקנאה המקנה, וכן (פסוק כא) אחיו תופש כנור ועוגב לזמר לעבודה זרה:
@102 **תובל קין.** תבל אמנתו של קין. תובל לשון תבלין, תבל והתקין אמנתו של קין לעשות כלי זין לרוצחים: **לטש כל חרש נחשת וברזל.** מחדד אמנות נחשת וברזל, כמו (איוב טז ט) ילטוש עיניו לי. חרש אינו לשון פעל אלא לשון פועל שהרי נקוד קמץ קטן. וטעמו למטה, כלומר מחדד ומצחצח כל כלי אמנות נחשת וברזל: **נעמה.** היא אשתו של נח:
@103 **שמען קולי.** שהיו פורשות ממנו מתשמיש לפי שהרג את קין ואת תובל קין בנו, שהיה למך סומא ותובל קין מושכו, וראה את קין ונדמה לו כחיה ואמר לאביו למשוך בקשת, והרגו. וכיון שידע שהוא קין זקנו, הכה כף אל כף וספק את בנו ביניהם והרגו, והיו נשיו פורשות ממנו והוא מפיסן: **שמען קולי.** להשמע לי (לתשמיש) , וכי איש אשר הרגתיו לפצעי הוא נהרג, וכי אני פצעתיו מזיד שיהא הפצע קרוי על שמי, וילד אשר הרגתי לחבורתי נהרג, כלומר על ידי חבורתי, בתמיהה, והלא שוגג אני ולא מזיד, לא זהו פצעי ולא זהו חבורתי: פצע, מכת חרב או חץ נברידור''א בלע''ז [פצע]:
@104 **כי שבעתים יוקם קין.** קין שהרג מזיד נתלה לו עד שבעה דורות, אני שהרגתי שוגג לא כל שכן שיתלה לי שביעיות הרבה: **שבעים ושבעה.** לשון רבוי שביעיות אחז לו. כך דרש רבי תנחומא (אות יא) . ומדרש בראשית רבה (כג ד) לא הרג למך כלום ונשיו פורשות ממנו משקימו פריה ורביה, לפי שנגזרה גזרה לכלות זרעו של קין לאחר שבעה דורות, אמרו מה אנו יולדות לבהלה, למחר המבול בא ושוטף את הכל. והוא אומר להן וכי איש הרגתי לפצעי, וכי אני הרגתי את הבל שהיה איש בקומה וילד בשנים, שיהא זרעי כלה באותו עון, ומה קין שהרג נתלה לו שבעה דורות, אני שלא הרגתי לא כל שכן שיתלו לי שביעיות הרבה. וזהו קל וחומר של שטות, אם כן אין הקדוש ברוך הוא גובה את חובו ומקים את דברו:
@105 **וידע אדם** וגו' **.** בא לו למך אצל אדם הראשון וקבל על נשיו, אמר להן וכי עליכם לדקדק על גזרתו של מקום, אתם עשו מצותכם והוא יעשה את שלו. אמרו לו קשוט עצמך תחלה, והלא פרשת מאשתך זה מאה ושלשים שנה משנקנסה מיתה על ידך, מיד וידע אדם עוד וגו' . מהו עוד, ללמדך שנתוספה לו תאוה על תאותו:
@106 **אז הוחל.** (לשון חלין) לקרא את שמות האדם ואת שמות העצבים בשמו של הקדוש ברוך הוא לעשותן עבודה זרה ולקרותן אלהות:
@107 **זה ספר תולדת אדם.** זו היא ספירת תולדות אדם, ומדרשי אגדה יש רבים: **ביום ברא** וגו' **.** מגיד שביום שנברא הוליד:
@109 **שלשים ומאת שנה.** עד כאן פרש מן האשה:
@130 **ויתהלך חנוך.** צדיק היה וקל בדעתו לשוב להרשיע, לפיכך מיהר הקדוש ברוך הוא וסלקו והמיתו קודם זמנו [וזהו ששנה הכתוב במיתתו לכתוב ואיננו בעולם למלאות שנותיו: **כי לקח אתו.** לפני זמנו] כמו (יחזקאל כד טז) הנני לקח ממך את מחמד עיניך:
@134 **ויולד בן.** שממנו נבנה העולם:
@135 **זה ינחמנו.** ינח ממנו את עצבון ידינו, עד שלא בא נח לא היה להם כלי מחרשה והוא הכין להם, והיתה הארץ מוציאה קוצים ודרדרים כשזורעים חטים, מקללתו של אדם הראשון, ובימי נח נחה, וזהו ינחמנו, ינח ממנו. ואם לא תפרשהו כך, אין טעם הלשון נופל על השם, ואתה צריך לקרות שמו מנחם:
@138 **בן חמש מאות שנה.** אמר רבי יודן מה טעם כל הדורות הולידו למאה שנה וזה לחמש מאות, אמר הקדוש ברוך הוא אם רשעים הם יאבדו במים ורע לצדיק זה, ואם צדיקים הם אטריח עליו לעשות תבות הרבה, כבש את מעינו ולא הוליד עד שהיה בן חמש מאות שנה, כדי שלא יהא יפת הגדול שבבניו ראוי לעונשין לפני המבול דכתיב (ישעיה סה כ) כי הנער בן מאה שנה ימות, וראוי לענש לעתיד, וכן לפני מתן תורה: **את שם את חם ואת יפת.** והלא יפת הוא הגדול, אלא בתחלה אתה דורש את שם שהוא צדיק, ונלד כשהוא מהול, ושאברהם יצא ממנו וכו' :
@140 **בני האלהים.** בני השרים והשופטים. (דבר אחר בני האלהים הם השרים ההולכים בשליחותו של מקום, אף הם היו מתערבים בהם) . כל אלהים שבמקרא לשון מרות, וזה יוכיח (שמות ד טז) ואתה תהיה לו לאלהים, (שם ז א) ראה נתתיך אלהים: **כי טבת הנה.** אמר רבי יודן טבת כתיב, כשהיו מטיבין אותה מקשטת לכנס לחפה, היה גדול נכנס ובועלה תחלה: **מכל אשר בחרו.** אף בעולת בעל, אף הזכר והבהמה:
@141 **לא ידון רוחי באדם.** לא יתרעם ויריב רוחי עלי בשביל האדם: **לעלם.** לאורך ימים, הנה רוחי נדון בקרבי אם להשחית ואם לרחם, לא יהיה מדון זה ברוחי לעולם, כלומר לאורך ימים: **בשגם הוא בשר.** כמו בשגם, כלומר בשביל שגם זאת בו שהוא בשר, ואף על פי כן אינו נכנע לפני, ומה אם יהיה אש או דבר קשה, כיוצא בו (שופטים ה ז) עד שקמתי דבורה, כמו שקמתי. וכן (שם ו יז) שאתה מדבר עמי, כמו שאתה, אף בשגם כמו בשגם: **והיו ימיו** וגו' **.** עד מאה ועשרים שנה אאריך להם אפי ואם לא ישובו אביא עליהם מבול. ואם תאמר משנלד יפת עד המבול אינו אלא מאה שנה, אין מקדם ומאחר בתורה, כבר היתה הגזרה גזורה עשרים שנה קודם שהוליד נח תולדות, וכן מצינו בסדר עולם (פרק כח) . יש מדרשי אגדה רבים בלא ידון, אבל זה הוא צחצוח פשוטו:
@142 **הנפלים.** על שם שנפלו והפילו את העולם, ובלשון עברית לשון ענקים הוא: **בימים ההם.** בימי דור אנוש ובני קין: **וגם אחרי כן.** אף על פי שראו באבדן של דור אנוש שעלה אוקיינוס והציף שליש העולם, לא נכנע דור המבול ללמוד מהם: **אשר יבאו.** היו יולדות ענקים כמותם: **הגבורים.** למרוד במקום: **אנשי השם.** אותן שנקבו בשמות עירד, מחויאל, מתושאל, שנקראו על שם אבדן שנמוחו והותשו. דבר אחר אנשי שממון, ששממו את העולם:
@144 **וינחם ה' כי עשה.** נחמה היתה לפניו שבראו בתחתונים, שאלו היה מן העליונים היה ממרידן: **ויתעצב.** האדם: **אל לבו.** של מקום, עלה במחשבתו של מקום להעציבו, זהו תרגום אנקלוס. דבר אחר וינחם, נהפכה מחשבתו של מקום ממדת רחמים למדת הדין, עלה במחשבה לפניו מה לעשות באדם שעשה בארץ, וכן כל לשון נחום שבמקרא לשון נמלך מה לעשות (במדבר כג ט) ובן אדם ויתנחם, (דברים לב לו) ועל עבדיו יתנחם, (שמות לב יד) וינחם ה' על הרעה, (שמואל א' טו יא) נחמתי כי המלכתי, כלם לשון מחשבה אחרת הם: **ויתעצב אל לבו.** נתאבל על אבדן מעשה ידיו, כמו (ש''ב יט ג) נעצב המלך על בנו. וזו כתבתי לתשובת המינים, גוי אחד שאל את רבי יהושע בן קרחה, אמר לו אין אתם מודים שהקדוש ברוך הוא רואה את הנלד, אמר לו הן. אמר לו והא כתיב ויתעצב אל לבו, אמר לו נלד לך בן זכר מימיך, אמר לו הן. אמר לו ומה עשית, אמר לו שמחתי ושמחתי את הכל. אמר לו ולא היית יודע שסופו למות, אמר לו בשעת חדותא חדותא, בשעת אבלא אבלא. אמר לו כך מעשה הקדוש ברוך הוא, אף על פי שגלוי לפניו שסופן לחטוא ולאבדן לא נמנע מלבראן בשביל הצדיקים העתידים לעמוד מהם:
@145 **ויאמר ה' אמחה את האדם.** הוא עפר ואביא עליו מים ואמחה אותו, לכך נאמר לשון מחוי: **מאדם עד בהמה.** אף הם השחיתו דרכם. דבר אחר הכל נברא בשביל אדם, וכיון שהוא כלה מה צורך באלו: **כי נחמתי כי עשיתם.** חשבתי מה לעשות להם על אשר עש י ת י ם:

@1 ואומר שמלת **ראשית** נאמר בלשוננו על חלק המדבר הקודם אי זה קדימה שתהיה מהקדימות המפורסמות כמו שביארנו בששי מספר מלחמות יי' ויהיה אמרו בראשית ברא אלהים וכו' במדרגת אמרו תחלת דבר יי' אל הושע שביאורו הוא תחלת הדבור שדבר יי' בהושע הוא שאמר אל הושע קח לך וגו' וכן הכונה הנה בראשית הבריאה כאשר ברא השם השמים והארץ ומה שנלוה לזה משאר ההויות אמר השם יתע' יהי אור והארץ זו המציאות השפל כי הוא יאמר ככלל על כל זה המציאות השפל ר"ל היסודות בכללם ובפרט יאמר על הארץ היסודית וכאשר יזכר עם השמים הוא נאמר בכללות על כל היסודות ומה שתחת השמים:
@2 ו **תהו ובוהו** הם החמ' והצורה אשר הם התחלות ההויה כמו שהתבאר בראשון מהשמע וזהם החמר הראשון והצורה האחרונה. ר"ל הצורה אשר יקבלה החמר הראשון תחלה קודם קבולו שאר הצורות כאלו תאמר הצורות היסודיות אמרו ז"ל תהו זה קו ירוק שמקים העולם והוא רמז לצורה בהו אלו אבנים מפורלמוות והוא רמז לחמר וכן נמצא בכתוב שייחס הקו לתהו והאבנים לבהו אמר ונטה עליה קו תהו ואבני בהו ולהיות חלק אלו ההתחלות במציאות חלוש עד שטבעם קרוב לטבע ההעדר נתפרסם כדברי רבותי' שיכנו הפסד זה העולם אל חזרתו לתוהו ובהו והנה ידוע שנטיית הקו כבניין הוא הצורה האחרונה לבניין ההוא והאבנים אשר הם שתותיו ויסודותיו הם החמר הראשון לו וראה אמרם בתוהו שזה קו ירוק שמקיף את העולם כי ההויה תהיה בהשתנות הנושא מהפך אל הפך כמו שהתבאר בטבעיות והממוצע בין ההפכים תמצא בו הדריכה אל ההויה והיותר מפורסם שבממוצעים שבין ההפכים הוא במרים ולזה לקח הירוק שהוא הממוצע שבמראים תמורת הממוצע בין ההפכים ועוד שבממוצע יש בו חלק מכל אחד מההפכים וההפכים והנושא הם התחלות כמו שנזכר בא' מהשמע וקרא החמר הראשון אבנים מפולמות ר"ל נעלמות ונסתרות ונגזר מפלמוני שהוא מורכב מאלמוני ופלני ופלני' שם ההסתר וההעלם כאמר והוא פלאי וכן אלמוני ופלמוני המקובץ משניהם וממנו נגזר מפולמות ואמנם קרא זה החמר אבנים מפולמות להיותו בתכלית ההעלם וההסתר עד שאי אפשר שיצוייר עניינו כמו שהתבאר בא' מהשמע.
@2 **וחשך** פי' בו הרב המורה הוא אש היסודי והביא ראיה מהפסוקים מהם אמרו כשמעכם את הקול מתוך החשך ואמר במקום אחר ודבריו שמעת מתוך האש וזה ממה שיורה שהחשך הוא אש ואמר ג"כ כל חשך טמון לצפוניו תאכלהו אש לא נופח. וכבר יסופק על זה הדמיון ספק חזק כמו שאבאר וזה כי הענין אשר היה ממנו האש במתן תורה ראוי שיקרא חשך להיותו חשוך מאד ולזה אמר כשמעכם את הקול מתוך החשך ואמ' ג"כ את הדברים האלה דבר יי' אל כל קהלכם בהר מתוך האש הענן והערפל כבר ביאר לך שהם שמעו דבריו מתוך האש ומתו' הענן והערפל אשר הוא החשך ולזה יתבאר שאמרו מתוך החשך לא יחוייב שיהיה נאמר על האש כמו שהבין הרב המורה והוא מבואר שאין ראוי שיפול שם החשך על האש המתלקחת כי היא מאירה ולא על האש היסודי לפי שהיא ספיריית ולא יקרה ממנה חשך ואולם נאמר בזה הפסוק הנזכר על העניין אשר נתחדש בו זה האש במתן תורה ולזה ג"כ יאמ' כל חשך טמון לצפוניו תאכלהו אש לא נופח. וכבר יסופק על זה הדמיון ספק חזק כמו אבאר וזה כי הענין אשר היה ממנו האש במתן תורה ראוי שיקרא חשך להיותו חשוך מאד ולזה אמר כשמעכם את הקול מתוך החשך ואמ' ג"כ את הדברים האלה דבר יי' אל כל קהלכם בהר מתוך האש הענן והערפל כבר ביאר לך שהם שמעו דבריו מתוך האש ומתו' הענן והערפל אשר הוא החשך ולזה יתבאר שאמרו מתוך החשך לא יחוייב שיהיה נאמר על האש כמו שהבין הרב המורה והוא מבואר שאין ראוי שיפול שם החשך על האש המתלקחת כי היא מאירה ולא על האש היסודי לפי שהיא ספיריית ולא יקרה ממנה חשך ואולם נאמר בזה הפסוק הנזכר על העניין אשר נתחדש בו זה האש כמתן תורה ולזה ג"כ יאמ' כל חשך טמון לצפוניו תאכלהו אש לא נופח וזה כי הענן שיצאו ממנו הלהבות והדברים המפסידים הוא ברוב העתים חשוך מאד. והנרא' בעיני שהכונה במלת חשך יהיה בזה המקום אשר אנחנו בו היסוד הארצי כי הוא בעצמו חשוך מאד ונעדר מהצורה אשר הוא האור יותר משאר היסודות זולת הארץ כי שאר היסודות הם ספיריים זולת הארץ והארץ היא גם כן הגשם אשר קנה מחצור' יותר מעט מכל הגשמים הנמצאים בזה העולם השפל עד שמדרגתו קרובה למדרגת החמר הראשון אמר כי עפר אתה ואל עפר תשוב וכבר תמצא שייוחס החשך אל העדר הצורה והשלמות אמר אבן אפל וצלמות והוא מחמר הראשון כמו שביארנו בביאורינו לספר איוב. ולזא' הסבה ראוי שייוחס שם החשך לארץ וכבר יתבאר זה עוד ממה שאמר וחשך על פני תהום וזה כי התהום בלי ספק השטח השפל מהמים והוא עמק המים ולזה יחס החשך לפני תהום שהוא שטח המי' השפל ויחס הרוח לפני המים והוא שטחם העליון והיה הרצון באמרו על פני תהום אצל פני תהום ולא עליו כמו עליו מטה מנשה ונתת על המערכת לבונה זכה שהרצון אצל המערכת כמו שיתבאר בי"א ממנחות. ולזה יחס החשך לפני תהום שהוא עמק המים והשטח השפל מהן והרוח לפני המים והוא שטחם העליו' לפי שפני התהום הוא שטחם השפל והוא השפל וכבר יקשה לרב המורה למה יחס החשך על פני תהום שהוא עמק המים כאמרו תהום אמר לא כי היא. והנה היה ראוי שייחסו על פני הרוח לא שייחס היותו על שפל המים כי זה בתכלית זרות ורוח אלהים הוא האויר היסודי וסמכו לאלהים להורות על גודל כמותו כי הרוח המנשבת מעטת הכמות ביחס אל היסוד האוירי ולפי ששם הרוח משותף לאויר ולרוח המנשבת הנה תארו בגודל להורות מאי זה רוח ידבר כבר תמצא זה כלשוננו הרבה ר"ל שיסמך אחר משמות השם יתע' לדבר כשירצה להפליג בגודלו או בחזקו אמר כהררי אל. שהלבת יה. חצי שדי. כקול שדי. והנה כלל במלת רוח האויר והאש לפי שכבר ברחה התורה מלקרא אש להורו' על המרחק אשר בינו ובין האש המוחש והנה הוא כמו אויר אלא שהוא יבש ובזה יאמרו החכמים שהאויר הוא שלש' חלקים החלק שיהיה בו הגשם והמטר ושאר הדברים הנוהגים מנהגם וחלק האמצעי והוא חם ולח והחלק העליון הוא חם ויבש. כי הרוח המנשבת הוא מורכבת לא פשוטה: **מרחפת** ר"ל נחה וכן על גוזליו ירחף ינוח.
@3 **יהי אור.** זה האור הוא עולם המלאכים אשר הוא האור על דעת האמת אמר ונהורא עמיה שריה. אמרו במדרש תלים כמזמור אורי וישעי.
@4 **וירא אלהים כי טוב** אמר רבי יהודה ברבי סימון הבדיל הקב"ה את האור לעצמו משל למלך שראה מנה יפה ואמר זו לבני הה"ד אור זרוע לצדיק. ראה איך הסכימו כלם שזה האור אינו אור מוחש אבל הוא אצלם אור השכל. ומה נפלא מאמרם בזה למי שיתבונן ויבין אופן המחלוקת אשר ביניהם. וזה שר' יהודה בר' סימון ראה שאי אפשר לשכל האנושי שישיג השכלים הנפרדים בשום צד מן ההשגה וחכמי' יראו שאפשר לו השגתם כמה שישפע לו מאורם וזיום בדרך שישלם לו ההשארות בזאת ההשגה ואע"פ שאי אפש' לו השגתה. באופן שלם כמו שהתבאר בא' מספר מלחמות יי' ואולם מאמר רבי אבין הלוי הוא מאמר נפלא מבואר שזה האור הוא קודם בסבה לשאר הנמצאות. וכזה אמר החכם שהשם עיין בעולם השכלים הנפרדים והשפיע מהם המציאות.
@6 **רקיע** הוא הגרם השמימיי.
@6 **המים** הוא הגשם בלתי שומר תמונתו אשר הוא בין קצת הגלגלים לקצת. כמו שביארנו חיוב מציאותו בחלק הראשון מהמאמר החמישי מספר מלחמות יי'.
@6 וכבר ביאר הרב המורה רקיע המקום אשר יתהוה בו הענן לפי שהיה זר אצלו המצא המים למעלה מהגרם השמימיי. אלא שכבר תמצא שדוד אמר הללוהו שמי השמים והמים אשר מעל השמים וזה בלי ספק נאמר על גרם השמימיי. וכבר נתבאר לך ממאמרם ז"ל שהם הבינו זה כמו שביארנוהו. אמרו בבראשית רבה בפרשת אלה תולדות השמים והארץ. רבי עזריה בשם רבי כלפי למעלה הדבר אמור שכל מה שאתה רואה תולדות השמים והארץ הם שנאמר בראשית ברא אלהים את השמים ואת הארץ בשני בראו מהעליונים שנאמר ויאמר אלהים יהי רקיע. בשלישי בראו מן התחתונים שנאמר ויאמר אלהים יהי מאורות ברקיע השמים וגו' הנה התבאר לי מזה המאמר שהרקיע שנברא ביום שני הוא מהגרמים השמימיים. וכבר תמצא במדרש נכפל במקומות רבי' שהשמים נעשו מאש ומים ורמזו בזה לשני מינים הגרמים השמימיים שיש בו האחד שומר תמונתו והוא אשר יוחס אל המים והנה אמרו בבראשית רבה מה שיורה תכלית ההודאה על ביאורינו זה והוא אמרם בשעה שאמר הקדוש ברוך הוא יהי רקיע בתוך המים נגלדה טפה האמצעית ונעשו שמי' התחתונים ושמי השמים העליוני' לחים היא שמים ביום ראש' וקרשו' ר"ל שנתן להן עמידה וקיום.
@6 **יהי רקיע.** יחזק הרקיע רבי יודה ברבי סימון אומר יעשה מטלת הרקיע כמה דאת אמר' וירקעו את פחי. אמר רבי חנינה יצתה אש של מעלה ולחכה פני רקיע וכו' אמר רבי פינחס בשם רבי הושעיה' כחלל שבין הרקיע לארץ כך יש בין הרקיע למים העליונים יהי רקיע למים העליונים יהי רקיע בתוך המים בינם ובנתים אמר רבי תנחומא אנא אמרית טעם אלו נאמר ויעש אלהים את הרקיע ויבדל אלהים בין המים אשר על הרקיע הייתי אומר על גופו של רקיע המים נתונים כשהוא אומ' בין המים אשר מעל לרקיע הוי אומ' המים העליונים תלוים במאמר. והנה לך ראיות מזה המאמר שהם הבינו שזה הרקיע הגרם השמימיי. הראשונה אמרו ונעשו שמים התחתוני' ושמי השמים העליונים וזה ממה שאין ראוי שיאמר על הענן ולא על המקום שיתהוה בו. והשנית ממה שאמר יצתה אש של מעל ולחכה פני רקיע וזה אין ראוי שיאמ' על הענן כי התעבותו הוא התלחלח וצריכה להוית המי' לא יובש והפועל לו הוא הקור אשר בחלק ההוא מן האויר כמו שהתבאר בספר האותות לא האש. והשלישית מה שאמר כחלל שבין הרקיע לארץ כך יש בין הרקיע למים העליונים ואלו היה הרקיע ענן או מקום הענן היו שם גם כן מים העליונים בכח לא עליו. ואולם כשיובן זה לפי מה שספרנו יאות זה המאמר כי הם כבר תמצאם אומרים שעביו של רקיע כשעור מה שבין הארץ לרקיע. וכן יהיה השעור אצלם בין רקיע לרקיע אמרו בבר מהארץ לרקיע מהלך ת"ק שנה ועביו של רקיע מהלך ת"ק שנה ומרקיע עד הרקיע מהלך ת"ק שנה. ולפי זה המאמר יהיה שיעור המים התחתונים והוא חלל שבין הרקיע לארץ ר"ל בין השטח השפל מהרקיע לארץ. כשיעור מה שיש בין השטח השפל מהרקיע למים העליוני' ולזה אמרו יהי רקיע בתוך המים בינם ובנתים שיהיו השעורים שוים עד שיהיה שעור עובי הרקיע כשעור המים התחתונים ויהיה שעור המים העליונים גם כן כמו זה השעור. והנה שעור המים התחתונים הוא חלל שבין הרקיע לארץ ושעור הרקיע הוא חלל שבין הרקיע שהוא השטח השפל מהגלגל למים העליונים ובזה ימשך השעור אצלם בכל רקיע ורקיע ומאמר רבי תנחומא שהמים העליונים תלוים במאמ' נפלא מאד וזה שהוא יאמר שאין טבעם כטבע אלו המים התחתונים שהם כבדים והארץ נושאת אותן. אבל הם תלוים במאמר ר"ל שאין להם דבר ישאם כי אינם קלים ולא כבדים ולזה דקדק ואמר משלו שאלו היה כתוב ויבדל בין המים אשר על הרקיע הייתי אומר על גופו של רקיע המים נתונים ר"ל שהם עליו והוא ישאם. אבל אמר מעל הרקיע ולא תאר אותם בשהם על הרקיע. להיותם נסמכים על עצמם וזה דקדוק נפלא מאד. וכבר הורו לנו שמה שיאמ' בשמים שהם אש ומים הוא על צד הדמיון. מזולת שיהיה כן באמרם כב"ר שמים שחבריות משתוממין עליהם לומ' של מים הם של אש הם. הורו בזה שזה נאמר לבד על צד הדמיון והמשל מזולת שיהיה העניין בעצמו כן. ולזה אמר רבי עקיבה בפרק אין דורשין כשאתם מגיעים לאבני שיש טהור אל תאמרו מים מים שכן כתוב דובר שקרים לא יכון. הנה קרא אבני שיש טהור הגרמים השמימיים וקראם כן להיותם ספיריים ונקיים מכל עכירות ועובי ואמנם אמר זה שכבר אמר שנקרא הגשם ההוא אשר שם מים על צד הדמיון וההמשל לא שיהיה טבעו כטבע אלו המים היסודיים. וראוי שתדע שכבר ימצאו גם כן מאמרים לרבותינו מודים על מה שהבינו הרב המורה מעניין זה הרקיע והם מעטים אבל רובם ימצאו מסכימי' למה שהכננו והוא היותר נאות לפי הסדור הטבעי כמו שתראה מדברינו. והנה שם בריאת הגלגלים מדרגה שנית מן ההויה ולא כלל בריאתם עם בריאת המלאכים שהם צורה להם להורות על שצורותיהם והם השכלי' הנפרדים אינם דבקים בהם כדבקות הצורות ההיולאניות לחמר. אבל צורותיהם נבדלות ולזה יחס צוואת בריאתם ליום אחד ובריאת הגלגלים ליום ב' וראוי שתדע שכל מה שאפשר שחידושי מן הטבע לפי מה שהטביעו הש' ית' לא יוחסה בריאתו לשם יתע' בזה הספור כי הוא יעשהו באמצעות הטבע ולזה לא יחס לש' ית' הוית הצמחים והבעלי חיים המהתוים מהעפוש ומזולת מינם. אבל יחס לשם בריאת מה שלא יתהוה על המנהג הטבעי כי אם ממינו. כי בריאתו לא ממינו היתה על דרך פלא ולזה לא ייחס הויית היסודות לש' ית' כי די הויתם באמצעות הצורות היסודיות כמו שיתבאר זה למי שעיין בטבעיות.
@14 **לאותות** הם הפעולות המסודרות מהגרמים השמימיים בזה העולם השפל אשר הכוכבים מודים עליהם לפי מה שיותר בו א"א מהם על האופן שהתבאר בחכמת משפטי הכוכבים. וכבר יורה שהענין כן אמרו ומאותות השמים אל תחתו. הידעת חקות שמים אם תשים משטרו בארץ. כבר ביארנו בביאורנו לחכמת הטבעית ובספר מלחמות יי' במאמר הששי ובמאמר השני ממנו כמה שאין ספק בו שמהגרמים השמימיים יסודר כל מה שיתחדש בזה העולם השפל. ומפאת זה הסדור יתכן שתגיע הודעה באלו המקרים לאדם בחלום או בקסם או בנבואה אליו כי הבחירה האנושית תוכל לשנות באופן מה הסדור ההוא כמו שביארנו שם. ואולם החסרון המגיע בחכמת משפטי הכוכבים הוא מצד קצורנו לא מצד העניין בעצמו אמר הידעת חקות שמים אם תשים משטרו בארץ. ואמרו **למועדים** ר"ל ולמועדים מוגבלים וזה כי פעם יהיה זה הכוכב לאות על מה שיתכן שיקרה ופעם ככב אחר כאלו תאמר שזה הכוכב מושל בזאת השעה ותלקח ההוראה בה ממה שיורה עליו עניין זה הכוכב לפי מה שהתבאר בנסיון. ובשעה השנית ימשול כוכב אחר וכן העניין ביום ובשנה שכבר יהיה כוכב מיוחד מושל בזה היום וכוכב אחר בשני וכזה יהיה כוכב מיוחד מושל בזאת השנה וכוכב אחר בשה האחרת ולזה אמר **ולימים ושנים**.
@16 **לממשלת היום** הוא השולטנות על הפעולות על שאר הכוכבים וזה שמן המפורסם הוא שפעולות השמש והירח יותר נגלות ונראות בזה העולם השפל מפעולות שאר הכוכבי'. וכבר נזכר זה בחכמת משפטי הככבים אופן מה מהממשלה לשמש ביום ולירח בלילה במשפטי מולדות בני האדם. אלא שעם כל זה הוא מבואר שיש לשאר הכוכבים ממשלה מה ושולטנות מה ביום ובלילה וכבר נתפרסם זה למי שעיין מעט בחכמת המשפט והנה קרא השמש מאור גדול והירח מאור קטן מצד הכמות ומצד האיכות ואף על פי שהם נראים שוים כשיהיה אור הירח שלם. אם מצד הכמות כי השמש יותר גדול מהירח עד שבו משעורי הירח כמו חמשים אלף בקרוב מעט כמו שביארנו בחלק ראשון ממאמר חמישי ממלחמות יי' ואם מצד האיכות לפי שאור השמש יותר חזק מאד מאור הירח עד שאור הירח הוא נאצל מאור השמש כמו שהתבאר מחכמת הכוכבים.
@26 **לממשלת היום** הוא השולטנות על הפעולות על שאר הכוכבים וזה שמן המפורסם הוא שפעולות השמש והירח יותר נגלות ונראות בזה העולם השפל מפעולות שאר הכוכבי'. וכבר נזכר זה בחכמת משפטי הככבים אופן מה מהממשלה לשמש ביום ולירח בלילה במשפטי מולדות בני האדם. אלא שעם כל זה הוא מבואר שיש לשאר הכוכבים ממשלה מה ושולטנות מה ביום ובלילה וכבר נתפרסם זה למי שעיין מעט בחכמת המשפט והנה קרא השמש מאור גדול והירח מאור קטן מצד הכמות ומצד האיכות ואף על פי שהם נראים שוים כשיהיה אור הירח שלם. אם מצד הכמות כי השמש יותר גדול מהירח עד שבו משעורי הירח כמו חמשים אלף בקרוב מעט כמו שביארנו בחלק ראשון ממאמר חמישי ממלחמות יי' ואם מצד האיכות לפי שאור השמש יותר חזק מאד מאור הירח עד שאור הירח הוא נאצל מאור השמש כמו שהתבאר מחכמת הכוכבים.
@29 ואמרו **ויאמ' אלהים הנה נתתי לכם את כל עשב** וגומ' היא בריאה ונתינת טבע לא מצוה והעד הנאמן אמרו בסוף העניין ויהי כן ואופן הבריאה הזאת הוא שנתן בכח האד' שיהיו הצמחים מזון לו עם היותם רחוקים מאד מטבעו וכן נתן זה הכח לשאר הב"ח ומזה המקום יוסר זה הספק אשר יסופק בזה המאמר וזה שהו' מבואר מצד העיון ומצד התור' שהרצון האלהי לא ישתנ' וכבר יחשב שיחוייב מזה המאמר שישתנה רצון השם במה שיצוהו מהמצות וזה שכבר יחשב שהשם יתברך מנע בזה המאמר אכילת בשר לאדם ואחר כך התירו לנה אמרו כל רמש אשר הוא חי לכם יהיה לאכלה וזהו שקר עצום ראוי שיברח ממנו כל בעל דעת וכבר אמרו זה בדרש קצת רז"ל אלא באלו העניניי' ובכיוצא בהם לא נביט למאמ' אומר כמו שהורנו הרב המורה אבל נמשך אל מה שיאות על שרשי התורה והעיון. והו' מבואר שאין ההאמנה בכל מה שאמרוהו רז"ל מחוייבת לנו כי כבר ימצאו בהם דברים סותרי' קצתם קצת ולזה לא נרחיק היות בהן דברי' בלתי צודקים בכמו אלו הדברים וכבר יחשב שעם כל זה יתחייב לנו שישתנה הרצון האלהי במה שיצוהו מהמצו' שכב' התיר לבני נח אכילת כל הב"ח אמ' כל רמש אשר הוא חי לכם יהיה לאכלה ואח"כ אסר קצת' בתורה ונאמר שאם היה בא האיסור לבני נח בכללם היה זה בי ספק שנוי בחק הרצון האלהי אבל למה שלא נאסר זה אלא לקצתם והם בני ישראל הנה אין שנוי כי אמנ' רצה השי"ב ישראל שיהיו יותר קדושים מכל האומות כמו שאמור בזה העניין בפרשת ביום השמיני והתקדשתם והייתם קדושי' כי קדוש אני ולזה מנע מהם קצת מה שהתיר לבני נח וכזה תמצא שאסר לבני אהרן קצת דברים הם מותרי' לנו לרצותו בהם שיהיו יות' קדושים' משאר בני ישראל ואסר לכהן גדול קצת דברים הותרו לבני אהרן לרצותו שיהיה יותר קדוש מהם כמו שנ' בתורה וזה אמ' הנביא יי' חפץ למען צדקו יגדיל תורה ויאדיר. ר"ל כי ברצותו בצדק ישראל הגדיל להם התור' והאדירה במה שהרבה להם מהמצות ובכאן הותר זה הספק.
@33 **ויכל אלהים ביום השביעי** פירש בו זולתינו ענין ההשלמ' והביאם זה אל שיפרשו ביום השביעי קודם יום השביעי וזה זר מאד עם שיהיה בזה המאמ' מותר כי אח' שנשלמו שמים וארץ וכל צבאם בששת הימים שזכר הנה כלתה המלאכה בהכרח קודם יום השביעי. ולזה יהיה פירושו אצלנו מעניין חשק וכוסף כטעם ותכל דוד שהוא מעניין החשק כמו שאמר נכספה וגם כלתה נפשי ואם יספק מספק עלינו ויאמר שאם היה הדבר כן יהיה חסר נפש כמו ותכל דוד שהרצון בו ותכל נפש דוד לפי שזה הפועל הוא נקשר עם הנפ' אמרנו לו שזה אמנ' יתכן כשהיה החושק מורכב מגוף ונפש כמו האדם ר"ל שאם ייוחס זה החשק לנפש אשר הוא החלק ממנו שאפשר שייוחס לו החשק והכוסף אמנם השם יתעלה אין בו חלק ייוחס לו לבדו החשק כי איננו מורכב ולזה ייוחס החשק אשר הוא חושק אליו בעצמו לא אל חלק ממנו ואופן חשקו **ביום השביעי מלאכתו אשר עשה** הוא שהוא חושק בזה הסדור המושכל אשר לעולם אשר הוא השם ית' באופן מה כמו שזכר הפילוסוף במה שאמר שהשם יתברך הוא נימוס הנמצאו' וסדרם וישרם עם מה שכבר ביארנוהו מזה בספר מלחמות יי' והוא אשר ממנו השתלשל המציאות רוצה לומ' שבזה הסדור המושכל אצל ה' המציא העולם כמו שימציא הפועל הכלי מהסדור מושכל אשר לו בנפשו כאלו תאמ' שהגר יעשה הכסא מהסידור המושכל אשר לו בנפשו ולזה תמצא רבותי' ז"ל שאמרו שבקצת שם השי"ת נברא העולם אמרו שהעולם הזה נברא בה"א והעולם הבא ביו"ד וסמכו אל זה מה שאמר הכתוב כי ביה יי' צור עולמי'. וזה נפלא מאד ומסכי' לאמת כבר תבי' זה כשתתבונן במה שביארנוהו מזה העניין בספר מלחמות יי' וזה החשק אשר לה' יתע' בזה הסדור המושכל הוא סבה שישיגהו אל השי"ת תמיד ובזאת ההשגה יהיה נשמר זה המציאות על עניינו כמו שהתבאר למי שיפליג העיון באלהיות וזה כי השכלים הנפרדים יחשקו גם כן להדמות לבוראם להיותו הולך מהם מהלך הפועל והצורה והתכלית וישיגו מזה הסדור לפי מדרגתם ויחשקו לעשות לפי מה שיגזרהו הסדור ההוא לפי מה שנתן להם השם ית' מהפעולו' בהשלמות העולם ובשמירתו ויתנועעו הגלגלים בעבור זה הציור באופן אשר הם מתנועעים בו וישלימו בזה כל הנמצאות.
@38 **לנפש חיה** ר"ל לנפש אשר ימצא בה החיות והקיום בעצמותה מה שאין כן בנפש שאר הב"ח כי היא ההיולאנית ולזה היא נפסדת בהפסד החומר ואולם נפש האדם היא נבדלת באופן מה כמו שביארנו בא' ממלחמות יי' ומזה הצד היה אפשר בה שתשאר קיימת בהפרדה מן החומ' ומפני זה תרגם אנקלוס ע"ה לנפש חיה לרוח ממללא הורה בזה שהו' תואר לנפש המדברת אשר בה האדם אדם ומזה הענין ג"כ באמרו **כל אשר יקרא לו האד' נפש חיה הוא שמו** וזה שמה שקרא אדם מהשמות אין הרצון בו קריאת השם לפי הסכמת הלשון לבד מזולת שיורה על מהות זה השם הנקרא בו אבל הרצון קריאת השם המורה על מהות דבר ודבר והשמות אשר זה עניינם הם הגדרים אמרו בב"ר בשעה שבא השם לברא אדם הראשון נמלך במלאכי השרת אמר להם נעשה אדם אמרו לו אדם זה מה טיבו אמ' להם חכמתו מרובה משלכם הביא לפניהם עוות ובהמות וחיות אמר להם חכמתו מרובה משלכם היבא לפניהם עופות ובהמות וחיות אמר להם זה מה שמו ולא היו יודעין העבירן לפני אדם ואמר לו זה מה שמו ואמר זה שור וזה חמור וזה סוס וזה גמל וכו' כבר הורו לך שקריאת אלו השמות חכמה נפלאה ואם היתה קריאתם לפי הסכמת הלשון לד לא תהיה בזה חכמ' כי כבר היה יכול לקראת באיזה שם שירצה כאלו תאמר שכבר היה אפשר לו שיקרא לשור חמור ולחמור שור לפי הסכמתו ומה שהוא בזה התואר לא יהיה יחוד השם לנקרא בו חכמה אבל כאשר הנחנו השמות ההם על מהות הדברים הנקראים באלו השמות היה בזה מהחכמה מה שלא יעלם לאחד מבעלי העיון. ולזה יחסו ז"ל קריאת אלו השמות לחכמה נפלאה ואמ' שכל מה שיקרא האדם מהשמות כזה האופן יהיה השם ההוא נפש ימצא בה החיות בעצמותה כי השם ההוא הוא מושכל הדבר הנקרא בו ואלו המושכלות כשהגיעו לאדם הם נצחיו' כמו שביאר' בראשון ממלחמות יי'.
@39 **גן** הוא רמז אל השכל ההיולאני ואופן ההמשל בזה שכמו שימצאו בגן הצמחי' אשר הוא כחיי עליהם בכח כן ימצאו בשכל ההיולאני המושכלות אשר הוא כחיי עליהם בכח וכבר נכפל ההמשל בזה האופן בשיר השירים כמו שביארנו שם. ובדברי רז"ל תמצא ג"כ זה ההמשל אמרו בשני מחגיגה פרק אין דורשין. ד' נכנסו לפרדס וכו' ואמר ' נטעו כי בזולת זה לא יהיו הצמחים בו בכח קרוב והנה הודיענו בזה המאמר שהשכ' ההיולאני אינו במדרגת העדר והכח הגמור אבל הוא צורה ידבק בה זה הכח ולזאת הצורה היה לאדם מה שהוא ואופן נטיעת זה הגן שהוכנו לו כלים להשגת הדברים המוחשים אשר בהם יגיעו אלו המושכלות בשפע השוע לו מהשכל הפועל כמו שיגיעו לגן הנטוע הוית פירותיו בנהר אשר ישקה אותו באופן הראוי, עדן, הוא רמז אל השכל הפועל וקראו עדן להיותו תכלית התענוג האפשרי לנו שנדבק בו ונשיגהו באופן האפשרי לנו וזה התענוג לא ישוער להפלגתו עד שאין יחס לתענוגים הגופניים אליו וכבר יהיה זה התענוג לאדם על תכליתו אחר המות וזה יתבאר מהערבו' והתענוג אשר נשיגהו אנחנו במה שנשיג המושכלות בהיותינו דבקים בהומר אשר לא ידבק בנו כי אם זמן מועט מאד לקושי השמע השפע כחו' הנפש אל השכל אשר בנו עד שישלים לו כל ההתבודדות הראוי לו בהשגתו והנה אנחנו נמצא התענוג ההוא נפלא מאד עד שאין יחס לתענוגנו הגופיים אליו וכל שכן יהיה התענוג ההוא בהשגה שתהיה אחר הפרד מהחומ' יותר חזק להיותו בלתי נפסק ולהיות השכל משיג אז יחד כל המושכלות אשר קנה בהיותו דבק עם הגוף ולזה נקרא עדן כי התענוג השלם יהיה לאדם בדבקו בו כפי מה שאפש' וכבר העירו בו רז"ל על זה הביאור אמרו בפרק חלק מאי דכתיב עין לא ראתה אלהים זולתך אלהים יעשה למחכה לו ואמרו קצתם זה עדן שלא שלטיה בו עין מעולם ואם תאמר אדם הראשון היכן היה דר בגן וא"ת גן הוא עדן ת"ל ונהר יוצא מעדן הנה כבר ביארו לך מה שהעירונו עליו ואולם אמרם שלא שלטה בו עין מאולם הוא מבואר שאינו גוף שתשלט בו העין ועין השכל האנושי גם כן לא יתכן שישיגהו בשלמות כמו שביא' במה שאין ספק בו בא' ממלחמות יי'.
@39 **מקדם.** ר"ל מראשית הענין.
@40 **ויצמח יי' אלהים מן האדמה.** הוא מושך עצמו ואחר עמו ועניינו שכבר הצמיח הש' ית' מן האדמה כל עץ נחמד למראה וטוב למאכל והצמיח גם כן ממנה בתוך הגן עץ החיים ועץ הדעת טוב ורע. העץ נחמד למראה וטוב למאכל הוא רמז להשגת הדברים הערבים כי העץ הוא רמז להשגה בזה המשל. וכבר תמצא זה האופן מההמשל במשלי אמר על השגת התורה עץ חיים היא למחזיקים בה ובשיר השירים ימצא זה ההמשל הרבה ועץ החיים הוא סדור המושכל אשר לנמצאות שהשכל האנושי כחיי על השגתם כי בזאת ההשגה ישיג השכל האנושי החיים הנצחיים. אמרו בבראשית רבה עץ החיים מהלך ת"ק שנה וכל מימי בראשית מתפלגין תחתיו. רבי יודן אומר בשם רבי יהודה ב"ר אלעאי לא סוף גופו מהלך ת"ק שנה אלא קורתו מהלך ת"ק שנה ירצו בזה שעץ החיים הוא הסדור המושכל אשר לנמצאות השפלות ששעורם ת"ק שנה אצלם כמו שזכרנו במה שקדם. ולזה אמרו שכל מימי בראשית מתפלגים תחתיו כי מזה הסדור המושכל יתהוה כל ההוה מהם כמו שיתבאר בחכמת הטבעית ובמה שאחר הטבע. ואמנם זכרו זה המציאות הטפל לבד להיות השכל הפועל הוא הסדור המושכל אשר מאלו הנמצאות השפלות כמו שבא' במלחמו' יי' להיות האדם יות' כחיי על השגתו מהשגת מה שלמעלה ממנו ולזה גם כן תמצא שאמרו ז"ל שקומת אדם הראשון היה מהארץ ועד לרקיע ואחר כך נתמעטה קומתו כשחטא וזאת הקומה שיעורה אצלם ת"ק שנה וראוי שתדע שעם היות הענין כן תגיע לאדם הצלחתו גם כן במה שיקנה מן ההשגה בנמצאות העליונות אבל תהיה ההשגה חלושה אשר לו בהם יותר נכבדת ויותר חשוקה מההשגה החזקה אשר לו באלו הדברים השפלים ואומר שהוא בתוך הגן לפי שהגן הוא כחיי על השגתו כמו שקדם ועץ הדעת טוב ורע ענינו ועץ הדעת דעת טוב ורע וכמוהו הארון הברית וביאורו השגת הערב והבלתי ערב הנאה והמגונה והמועיל והמזיק ושאר מה שיאמר עליו הטוב והרע לפי מה שיראו האנשי' ואלו ההשגו' ג"כ בתוך הגן כמו שקדם כי מהשכל האנושי יגיעו באופן מה כאמצעי' החושי' והדמיון וכבר אמרו בב"ר שעץ הדעת לא גלהו הקב"ה לאדם ולא עתיד לגלותו ראה מה כתוב ואשה אשר תקרב אל כל בהמה לרבעה אותה והרגת את האשה ואת הבהמה. אם אדם חטא בהמה מה חטאת אלא שלא תהא בהמה עוברת בשוק ויאמרו זו היא שנסקלה פלונית על ידה אם על כבוד תולדותיו חס הקב"ה על כבוד אד' עצמו על אחת כמה וכמה. וכבר אמרו זה לפי שכבר אמרו קצתן שחיטה היתה שהשיגו באכילתה הטוב המגיע ממנו וקצתם אמרו תאנה היתה והשיגו בה מהערבות מה שהביאם לחקור בטוב וברע. וזה החכם אמר שלא נתגלה זה האילן לאדם ולא יתגלה וזה לכבוד אדם הראשון. ועל דרך האמת אף על פי שכבר נשיג הטוב והרע באמצעות השכל באופן מה אין ההשפעה בזאת ההשגה המכוונת בעצמותה מהש"י וראוי שתדע שעדן הוא מקום מהישוב ולמזרחו היה נמצא הגן אר בו כל פרי מגדים אמר בעדן גן אלהים היתה וכו'. כל עץ בגן אלהים לא דמה אליו ביופיו וישם מדברה כעדן וערבתה כגן יי' כגן עדן הארץ לפניו וזה כלו ממשה שיורה שזהו מקום נמצא בישוב ושהמקום ההוא רענן ודשן מאד ולזה גם כן המשיל בו מה שהמשיל ומן המבואר גם כן שמעדן יצא נהר להשקות את הגן ההוא.
@41 **ומשם יפרדו.** אלו הארבע נהרות המפורסמות שזכר אשר הם נהרות גדולים ישקו חלק גדול מהישוב לפי מה שהתפרסם מעניינם וזה היה מחכמת זה המשל שפשוטו הוא דבר נמצא כן וזה מה שיוסיף העלם והסתר במה שכוון בזה המשל והתפרד הנהרות מהגן הוא משל למה שיושפע מהשכל ההיולאני אל שאר כחות הנפש כמו שממנו כל ענינם ופעולותיהם.
@46 **ויקח יי' אלהים את האדם.** ר"ל ששם באלו הטבעיות טבע ימשכהו לעבוד ולשמור הגן בדרך שיוציא פריו וזאת העבודה והשמירה היא ההשתמשות בקניין המושכלות בדרך שיצא מה שבכח הגן אל הפעל והנה זה הטבע אשר ימשכהו הוא מה שיראה בתחלת העניין באלו הנמצאות הטבעיות משלמות היצירה וטוב הסדר והיושר כי זה ממה שימשוך האדם אל שיחקור בענינם עד שידע הסדור המושכל אשר לאלו הנמצאות וכבר ביארנו זה בספר שיר השירים. אמרו בבראשית רבה כי אמרו ויקח יי' אלהים ר"ל פתה אותו כמה דתימה קחו עמכם דברים וזה מסכים למה שאמר אכל תאכל הוא משל אל ההשגה כי האכילה תאמר על ההשגה כמו שאמר אכול דבר הרבות לא טוב וכבר נכפל ההמשל בזה בשירי השירים ובמשלי.
@48 **מות תמות.** ר"ל תפסק השגתך והפך זה ותחי רוח יעקב אביהם.
@52 **מצלעותיו.** ר"ל מצדדיו. אמרו בב"ר ויקח אחת מצלעותיו. ר' שמואל בר נחמן אמר מן סטרוהי כמה דתימה ולצלע המשכן.
@52 **ויסגר.** אצר והסתיר כמו יסגור על איש. והענין היה שהש' יתע' ברא על דרך מופת באחד מצדדי האדם קרום בדמות שליא ברא בו הבשר שנתהוה ממנו חוה ואמנם היה בריאת האשה מן האיש לפי שהוא הסבה במציאותה ר"ל שהיא נברא לעבודתו ולהורות שהוא במדרגת ההתחלה לה הושמה בריאתה ממנו כדי שתהיה יותר נשמעת אליו לעבדו העבוד הצריכה לו עם שבזה האופן ג"כ נמצאת יותר מתיחסת אל טבע האדם ואולם בשאר הב"ח אין העניין כן ולזה נבראו יחד ממקום אחד וכבר אמרו זה בב"ר ר"ל שאדם נברא מן האדמה וחוה נבראה מאדם ודע כי אי' אמ' עצם מעצמי ממה שיתחיל שתהיה בריאת' מן האדם כשלקח ה' עצם מעצמיו והוא הצלע שאם היה הדבר כן היה גם כן מחוייב לזאת הסבה שתהיה בריאתה ממנו כשלחק ה' חלק מבשרו כי הוא אמר ובשר מבשרי, וג"כ אם היה הדבר כן היה האדם חסר זה העצם אחר בריאת חוה וזה מגונה.
@57 **והנחש.** הוא משל לכח הדמיוני והמשילהו לנחש להיותו מזיק לאדם בהגעת שלמותו כמו שקדם ולהיות כל השגתו מגעת בנסיון ר"ל שכאשר הושג בחוש בדבר פלוני שהוא מתוך הנה יצייר אותו הכח הדמיוני בזה האופן ולזה תמצא ענין הנחש נופל בנסיון אמר נחשתי ויברכני יי' בגללך. אמרו ז"ל על הנחש שהוא היה כשעור גמל וסמאל רוכב עליו ושהקב"ה שחק על גמל ורוכבו וכבר יפילו ז"ל שם סמאל על היצר הרע להיותו נגזר מהשמאל אשר היא הנטייה הדרך הישר וכבר התבאר לך במה שקדם שהכח הדמיוני מנהיג באופן מה הכח המתעורר ומוליך אותו לאשר יפנה במה שיציירהו מהטוב והרע בדברים. **מכל חית השדה.** הנה קרא הכחות הנפשיי' המצאים באדם ובזולתו מהב"ח חית השדה להיותם כמו חיצונים ממהותו המיוחד לו ואמנם היה זה כן לפי שהשדה חוץ לעיר ולזה תמצא שהשתמשו הרבה ליחס מה שהוא חוץ מהדבר אל השדה עד שכבר ביארו ז"ל ובשר בשדה טרפה לא תאכלו הבשר שיצא חוץ למחיצתו כמו שנזכר בפרק בהמה המקשה ובמקומות רבינו מהתלמוד. ולזאת הסבה בעינה נקרא הב"ח המדברי חית השדה להיות מקומו חוץ מהמקום שיהיה בו ישוב בני אדם אמר וחית השדה הושלמה לך ואופן היות הכח הדמיוני ערום יות' משאר הכחות המשיגו' ההיולאניות הוא מבואר כי הוא יצייר מה שרצה לציירו כשלא ימנעהו מזה כחות הנפש ולא ימצא בכל הכחות המשיגות היולאניות כח מצייר זולת הדמיון ומזה הצד היה למדמה מבוא גדול בעניין הנבואה ובמה שידמה לה'.
@59 **ומפרי העץ אשר בתוך הגן.** ר"ל ההשגות אשר לא ייוחסו לגן בעצמות אלא שהן מגיעות באמצעה והם השגות הטוב והרע.
@61 **והייתם כאלהים יודעי טוב ורע.** ר"ל הם השופטים מנהיגי המדינות כי רוב מה שישתמשו במשפטיהן הוא באלו ההשגות כאלו תאמר שהם ייסרו האדם מהשתמש בדברים המגונים או בהמצאת ההזקים וזה מבואר מאד מעניין השופטים כי רוב משפטיהם הוא מצר הטוב והרע.
@62 **ונחמד העץ להשכיל.** ר"ל שהשגתו מגעת בקלות נפלא מה שאין כן בהשגת האמת והשקר אשר תגיע בהם ההצלחה האנושית על תכליתה ואולם השיא הנחש האשה להיות האשה יותר חלושת השכל מן האיש ולזה היא יותר קלה להתפתות בזה והיא אח"כ הסיתה האדם כי האדם נמשך מאד להסתות האשה הלא תראה כי שלמה שחכם מכל אדם הטו נשיו לבבו.
@63 **עלה תאנה.** הוא מבואר ואמנם לקחו עלה תאנה להיות בו רחב וקיום עד שלא ימצא עלה רחב כמוהו יהיה אפשר לו הקיום באופן קיום עלה התאנה מתהלך בגן הקול הוא שהיה מתהלך כאמרו קולה כנחש ילך וכן אמרו ז"ל בב"ר לרוח היום הוא רמז קולה כנחש ילך וכן אמרו ז"ל בב"ר לרוח היום הוא רמז אל העת כקרוב לזריחת השמש כי אז יתעורר הרוח וינשב וה העת הוא משל ליציאה מאופל הסכלות לאור החכמה וכדומה לזה בא המשל הרבה בשיר השירים.
@64 **ויתחבא האדם ואשתו.** הוא משל אל התחבואות המחוייב להם מצד נטות השגתם מהמושכלות אל השגת הטוב והרע כי מפני זה כשירצה הפועל להשפיע להם במושכלות לא ימצאם מוכנים וההתחבאות היה בתוך עץ הגן אשר נטתה השגתם אליו.
@65 **ויקרא יי' אלהים אל האדם.** הוא על דרך משל עש"ד ויאמר יי' אל השטן. ויאמר יי' לדג. וכמאמר יי' לאשה ולנחש והנה הועילתנו התורה בספרה זה העניין על זה האופן תועלת נפלאה בהנהגה המדינית והיא שאין לשופט לשפוט את האדם אם לא אמת העניין עמו פנים בפנים כי אולי יש לו טענת התנצלות הלא תראה כי ה' ית' עם היותו יודע כל הדברי סופר בזה המשל לא ענש אדם וחוה עד שדבר עמם וידע אם יש להם התנצלות וכן העניין במה שבין האדם לרעהו כי לא יאמין האד' מרעהו שעשה דבר או אמר כנגדו אם לא כשיתאמת זה עמו. בזה יוסרו הרבה ההיזקים הנופלים בין בני אדם.
@70 **ויאמר יי' אלהים אל הנחש.** ודע כי זאת הקללה היא צודקת כנחש כי הוא ארור מכל ב"ח ההולכים בשכבר הוא לבדו נמצא הולך על גחונו ולא הוכנו לו רגלים ללכת כמו הענין בשאר ההולכים שאמר הכתוב ונחש עפר לחמו וכן תמצא שהאיבה קיימת בין הנחש ובין בני אדם עד שישוך בני אדם מזולת שיגיע לו תועלת מזה ושהאדם כשירצה לשברו ולכתתו בדר' שלא יזיק לו יכהו מראשו כי לא יועיל הכותו במקום אחר אז בזנבו כי אחר כן יחיה ויזיקהו כשיכהו הנחש ישבר ויכתת בני אדם בעקבם כי הוא הולך על גחונו ומשם יכתתם וימיתם כי כבר יתפשט האר בגופם וימותו וזה מחכמת זה המשל ואולם לפי הנמשל יאות זה המאמר גם כן כמו שיתבאר ויהיה ביאור ראש ועקב לפי הנמשל בראשונ' ובסוף וכן תרגם אנקלוס ואכלת את עשב השדה. ר"ל שהשגתו תהיה ממין השגת שאר הב"ח כי עשב השדה הוא מזון להם.
@75 **בזעת אפך תאכל לחם.** ר"ל שבקושי גדול תשיג ההשגה האמתית המיוחדת לאדם והמשילה ללחם להיותו מזון מתוקן לאדם.
@77 **כתנות עור.** הוא כמו שביאר המתרגם במה שהמציא והרצון בו שכבר היו אלו הכתנות באופן מהרכות והחלקות שהיו נאותות ללבשם על עוד בשרם והנה המציא ה' ית' אלו הכתנות בפליאה כמו הענין בששת ימי הבריאה ואולם המציאם להם להיות האדם הכרחי ללבוש ישמרהו מהיזק האויר המקיף ואלו המתין זה עד שהתבאר להם דרך המלאכה הזאת יארך הזמן וימותו אם מהחום אם מהקור.
@78 **ולקח גם מעץ החיים.** ר"ל שיקח ההשגה הזאת בזולת הדרך שיגיעו בה אליה.
@78 **ואכל וחי לעולם.** ר"ל שאם אכל ממנו וזה יהיה כשיקח ההשגה על הסדר הראוי יגיע לו ממנה החיים הנצחיים והנה יהיה ביאור הענין כן האם האדם הושם בזה האופן מהבריאה אשר אפשר לו בה שישיג המושכלות באופן מתיחס השגתו לעליונים לתכלית שישתמש בה בהשגות הטוב והרע ועתה כיון שמרה והחטיא כונתנו שמא יהרוס להכנס במושכלות בזולת ההצעות אשר אם יקח ההשגה ההיא על הסדר הראוי יגיע לו ממנה החיי' הנצחיים ולזה שלחו מגן עדן לשמרו מן ההריסה ואפשר שנאמר שאמרו פן ישלח ידו הוא על דרך אורח חיים פן תפלס שהרצון בו שאם יש תוחלת בזאת האשה הזרה שתפלס אורח חיים זה לא יתכן כי נעו מעגלותיה מנתיבות. ולזה לא תדע ארחות חיים וכן העניין בכאן האם יש תוחלת שישלח ידו ולקח מעץ החיים ויאכל ממנו זה לא יתכן כמו שיתבאר אחר זה. וזה הפ' השני הוא יותר נאות מאד מן הראשון.
@80 **הכרובים.** הם הצורות הדמיונות אשר יגיעו באמצעותם המושכלו' כמו שהתבא' בספר הנפש ובא' ממלחמות יי' וקראם כרובים שהרצון בו נערי' קטנים לפי שהן בלתי שלמים כמו הענין בנערים וקטנים והשכל ישלימם כשיפשיט מהן המשנים ההיולאניות ויהיו אלו הצורות בעצמם הם המושכלות כמו שיהיה מהנער איש.
@80 **ואת להט החרב המתהפכת.** הוא משל להשפעה אשר תגיע לשכל ההיולאני מהשכל הפועל כמו שקדם.
@85 **ויפלו פניו.** ר"ל שהשיגהו בושת כי זה ממנהג מי שיבוש שיפלו פניו.
@87 **שאת.** הוא מעניין הסבל כמו לא אוכל לבדי שאת אתכם.
@87 **חטאת.** הוא היחר הרע כבר התבאר זה בב"ר והוא חסר הנושא כמו ומאכלו בריאה שהוא חסר הנושא המתואר בבריאה וענינו איש חטאת. ואמר שהוא רובץ לפתח ר"ל שהוא שוכן תמיד אצלו מראשית הענין לחטיאו ולהשיאו כי תכף שתהיה בו הבחיר' ימצא בו היצר הרע. ואולם היצר הטו' לא ימצא באדם אם לא אחר שקנה מהשלמות קניין מה ואפשר שנאמר שאמרו שאת הוא מעניין נשיאת הפרי ר"ל שישאו הצמחים פרים אשר בעבורם היה עובד האדמה או נשיאת הברכה כטעם ישא ברכ' מאת יי'.
@87 **וחטאת.** הוא עונש כטעם מחטאת סדום. אמרו בב"ר אם תטיב שאת ברכה ואם לא תטיב קללה.
@88 **ויאמר קין אל הבל אחיו.** לא פורש מה אמר לו ואפשר שאמ' לו שיצאו יחד בשדה או אמר לו דברי תוכחות והראשון הוא יותר נאות אצלי.
@93 **עוני.** ענשי.
@93 **מנשא.** מסבול.
@95 **לכן כל הורג קין.** קצר המאמר ולא פיר' מה יהיה ענשו וכמוהו ויאמר דוד כל מכה יבוסי ויגע וגו'. לא פירש מה יהיה שכרו וכן ויקרא יעבץ לאלהי ישראל לאמר אם ברך תברכני וגו'. לא פיר' מה יעשה אם יביא הש' את אשר שאל. והנה לא פירש בכאן העונש לפי שכבר הבטיחו הש"י שלא יכנו כל מוצא אותתו.
@95 **שבעתים.** לשבעה דורות. וזה כי הדור השביעי אחר קין היה זרע למך והוא מת במבול.
@139 **טובות.** יפות וכן כי טוב הוא והוא טוב תאר מאד.
@140 **בני האלהים.** הם הענקים וסמכם לאלהים להורות על גדלם וחזקם כטעם כהררי אל שלהבת יה.
@140 **ויקחו.** חטפו ולקחו בחזקה.
@141 **ידון.** מעניין דין ומשפט או יהיה מעניין ריב ומדון.
@141 **רוחי.** הוא רוח האדם אשר הוא בה אדם והוא השכל ויחסה לש' יתע' להיותה נאצלת ממנו.
@142 **הנפילים.** הם בני האלהים והם הענקים כמו שקדם.
@144 **וינחם יי'.** הוא על דרך משל כי לא אדם הוא להתנחם אבל דברה תורה כלשון בני אדם. וכן אמרו ויתעצב אל לבו ואמרו אל לבו הוא לרצונו ר"ל שכבר נתעצב דרך משל בעבור מה שהיה רצונו בעת בריאת העולם לברא אדם.
@145 **ויאמ' יי'.** הנה אמ' זה לנח כמו שנזכר בתורה אחר זה או יהיה זה על דרך האמירות הנזכרות במעשה בראשית שלא נאמרו לנביא אבל היתה ההוראה בהם הרצון לבד כמו ויאמר אלהים יהי אור וחביריו.

@1 **בראשית ברא אלהים את השמים ואת הארץ.**
@1 אמר לוי בן גרשום מבואר למי שראה דעות האנשים אשר היו בימי משה רבינו ע"ה כי בימיו היתה הפילוסופיא חסרה מאד עד שרובם לא היו מודים שיהיה שם נמצא זולת הנמצא המוחש ולא היו מרגישים בסבה הצוריית כלל אבל היו חושבים כי חמר אחד בעינו הוא נמצא בפעל בנמצא נמצא ויראו קצתם שלא יתחלפו קצת הנמצאות מקצת כי אם במצב חלקי החמר אשר ממנו היו וכתמונתם וברבוי החלקים ההם ומעוטם וקצתם יראו שיהיה התחלפות באופן אחר לפי הדעת שנתיחדו בו ומה שנשתתפו בו רוב האנשים ההם בזמן ההוא הוא שהם לא יראו שתהיה בכאן סבה פועלת וזה מבואר ממה שזכר הפילוסוף מדעות הקודמים בשני ממה שאחר הטבע, בהיות העניין כן והיתה כונת התורה להגיע המתנהגים בה אל השלמות האמתי כמו שזכרנו הנה מן הראוי שתיסד בה לנו זה השרש האמתי תחלה והוא שיש בכאן סבה פועלת אלו הנמצאות והעמידנו על מציאות הסבה הצוריית כי בזולת זה השרש לא יתכן לנו שום קנין נפשיי וזה מבואר למי שעיין בחכמת הנמצאות וגם כן בעבור היות התורה מקפת בשלשה חלקים אשר זכרנו בפתיחתינו. והיה החלק המקיף ממנה בחכמת הנמצאות הולך מהלך השלמות והצורה לשאר החלקים הנה ראוי שיונח קודם כי הוא אשר אליו היתה הכונה בתורה ואין ראוי שיסופק עלינו מה שבמצות התורה מההאמתה בשם ית' ובעבודתו וביראתו שהם כל פרי התורה ויחשב שראוי שיהיה קודם מפני זה אל החלק המקיף בחכמת הנמצאות. וזה כי לא יתכן שיאמר שנירא מיי ונעבדהו טרם השיגנו שיש שם נמצא בזה התואר וכאשר נדע חכמת הנמצאות לפי מה שאפשר לנו ונתיישר אל שיש בכאן נמצא הוא הפועל לכל הנמצאות ונשכיל ונדע אותו מצד פעולותיו. הגיע אותנו זאת ההשגה אל שנעבדהו ונירא ממנו. וגם כן בעבור שהיה מפנות התורה ההאמנה במופתים והיה מבואר שאם היה העולם קדמון אין דרך למציאות המופתים חוייב בהכרח שייסר לנו תחלה אמונה החדוש. ולזאת הסבה התחיל בחדוש העולם עם שהוא מהדרושים העמוקים בתכלית עד שהוא רחוק שיגיע האמת בו לחכם בדרך עינוי אם לא יתיישב בזה ממה שהישירתהו אליו התורה והודיע לנו עם זה הרבה מסודות הנמצאות כמו שנבאר. ואחר שביארנו לאי זו סבה חוייב שיקדי' התרת זה הדרוש ראינו להציע בכאן השרשים אשר מהם יתבאר מה שבא במעשה בראשי'. ונאמ' שכבר נתבאר בו' ממלחמת יי' שהוית העולם מיי' יתע' ראוי שתהיה בזולת זמן וכבר ביארו ז"ל שהשמים והארץ נבראו יחדו. אמרו בפרק אין דורשין וחכמי' אומרי' זה וזה כאחת נבראו שנאמר אף ידי יסדה ארץ וימיני טפחה שמים קורא אני אליהם יעמדו יחדיו וזה יתבאר עוד אצלינו מזה שאמר בתורה אלה תולדות השמים וארץ כהבראם למדנו מזה כי השמים והארץ ותולדותיהם נבראו ביום אחד. והנה המשילו החכמים הגלות בקצת הדברים קודם קצת במעשה בראשית למי שזרע זרעים חלוקים קדם בארץ ויצמח קצתם קדם קצת וכן אמרו שהיה הענין בהוית העולם שהכל נתהוה יחד מהשם יתע' ונגלה קצתו קודם קצת או נאמר שכבר נתיחסה ההויה לקצת הדברים קודם קצת להעיר על היותם קודמים בעצם וכסבה כי כונת התורה היא להעמידנו על חכמת הנמצאו' בזה הספור הנפלא כמו שקדם ואיך שיהיה העני' הנה יסוד מזה המקום הספק אשר סופק לקצת הקודמים באי זה דבר שוער יום ראשון ויום שני ויום שלישי. והנה לא היו המאורות נמצאים עד יום רביעי וזה מבואר לפי ההנחה הראשונה שכבר יאמ' לפי זאת ההנחה כי הגרם השמימיי היה נמצא ביום הראשון. והסבוב האחד ממנו הוא יום אחד בקרוב היה שנשער בו אנחנו או שלא נשער בו ואם איננו זר אם נאמר שהיה ידוע אצל השם יתע' שיעור הזמן בזולת שמש וככבים וזה מבואר מאד בנפשו. ואולם לפי ההנחה השנית הוא יותר מבואר כי היו ג"כ המאורות נמצאים ביום ראשון ואל זה כוונו באמרם המאורות נבראו ביום ראשון ולא תלאם עד יום רביע. ר"ל שלא תלה התהוותם בזמן קודם ליום רביעי. והנה יתבאר הסבה בזה במה שיבא. רצוני לומר למה לא נתיחסה ההויה בהם קודם זה ואי אפשר שנבין ממאמרם שהיו נבראים ביום ראשון נפרדים ותלאם ביום רביעי ברקיע כי אינן תלוים בו אבל הוא בעומק הרקיע קבועים וקיימים וזה מבואר מאד למעין בזה הספר ונאמר עוד שהוא מבואר בלא ספק שהשכלים הנפרדי' הן קודמים בסבה ובמציאות לגרמים השמימיים והגרמים השמימיים הם קודמים בסבה ובמציאות ליסודות ומה שיתהווה מהם והיסודות קודמים לדומם והדומם לצומח והצומח לחי על מדרגותיו אלא שזאת הקדימה היא קדימה היולאנית:
@1 **וכבר** ביארנו בחמשי מספר מלחמות יי' שבין גלגל לגלגל יש גשם בלתי שומר תמונתו הוא הסבה שלא ימשכו כל תנועות הגלגלים העליונים לשפלים או שלא ימשכו כל תנועת הגלגלים השפלים לעליונים והוא אשר נקרא מים בזאת הפרשה כמו שהתבאר שם לדמיון אשר בינו ובין המים בהעדר שמירת התמונה. וראוי שתדע כמו שנקראו המים מים שהוא מורה על ההכפל ממלת מה מצד רבוי המצבים אשר לחלקיהם קצתם עם קצת אשר הוא בלתי תכליי כן נקרא הגלגל שמים להורות על ההכפל ממלת שם שמורה על המקום מפני רבוי המצבים אשר לו במקום האחד בעינו ובתנועתו הסבובית אשר לא ימיר בה מקומו כי אם בחלקיו שימרוהו במקרה זהו מה שרצינו להציעו קודם שנתחיל בביאור זאת הפרשה. ומהנה נתחיל בביאור המלות:
@1 **ביאור דברי הפרשה:**
@1 **אמר** כי בראשית ברא הבריאה כאשר ברא השם השמים והארץ ומה שתחתיהם וברא בשפלי' התחלותיו הראשונות אשר הם החמר הראשון והצורה ההיולאנית הראשונה והיא הצורה היסודית אשר קבל החמר הראשון במקומותיו ר"ל שהיתה הארץ כמרכז למטה משטח המים השפל והאש והאויר למעלה משטח המים העליונים הנה בראשית זאת הבריאה כלה אמר הש' יתעלה שימצא עולם האור והוא עולם המלאכים ותכף שרצה זה נהיה לשום מעשה והנה הבדיל יי' ית' בין זה העולם הנכבד ובין זה השפל אשר הוא החשך תכלית ההבדל כי זה האור הוא דבק לחיים הנכבדים דבקות מתמיד ושמח בהשגתו הנכבדת. תכלית השמחה והמציאות השפל הוא בהפוך זה. והמשיל הש' יתע' זה האור ליום לרוב בהירותו וזכותו והחשך ללילה לרוב ערבובו ועכירותו ורוע סדורו. ואפשר שנאמר שכבר הבדיל יי' יתע' בין העולם הזה הנכבד שהוא כמו צורה לעולם האמצעי ובין הצרות ההיולאניות שהם כזה העולם השפל שהוא חושך ביחס אל זה האור הנכבד והמשיל זה האור ליו' לרב בהירותו וזכותו והצורו' האלו היולאניו' המשיל ללילה להעדר זה האור הנכבד מהם והיותר נכון שנאמר שבזה האור מדרגות חלוקות הולכים קצתם לקצתם מדרגת הצורה והשלמות כמו שזכר הפילוסוף במה שאחר הטבע ועוד כי כבר הבדיל הש' ית' בין המדרגה הגבוהה למדרגה השפלה ממנה אשר היא חשך בהקש אליה לפי שהיא הולכת ממנ' מהלך ההיולי והמשיל הגבוהה ליום והשפלה ללילה ואם הם כלם אור אלא שקצתם קנו מהשלמות יותר מקצת וה היתה המדרגה הראשונה מהוית העולם כי היא קודמת לשאר הנמצאות במציאות וסבה כמו שקדם ולזה יחס התהוותה ביום ראשון והנה אמ' שכבר קרא יי' יתע' לאור יום ולחשך קרא לילה להעיר אל השלמות האפשרי לנמצא נמצא מאלו השכלים הנפרדים ביום הבראו כונן לא יקנו עוד אחר זה שלמות לא היה להם כמו שאפשר זה בנו לפי שהשלמות אשר לנו הוא בנו בתחילה בכח לא בפעל ואין הענין כן באלו השכלים אבל ישארו תמיד על ענינם ולזה יהיה תמיד הגבוה גבוה והשפל שפל ולזה אמ' שקרא השם יתעלה לאור יום ולחשך קרא לילה להעיר שזה יהיה תמיד שהם וזה כי כמו שלא יקרא אדמוני בעת שהאדימו פניו בעת מה מפני הבשת כן לא יתואר אצל השם ית' בתואר מה מי שאינו עם זה התואר תמיד והוא כאלו אמ' שתמיד יהיה האור יום והחשך לילה וראוי שתבין מזה שכן העניין במה שאמר אחר זה ויקרא אלהים לרקיע שמי'. ויקרא אלהים ליבשה ארץ כמו שנבאר בג"ה בהגיענו שם וזה שלא יתכן שנאמר שתהיה קריאת השמות האלו מונחת מהש' יתע' שאם היה הענין כן לא היה אפשר בשום לשון שישנה אלו השמות וזה חלוף מה שנראה מזה. ועוד שכבר יקשה לתת הסבה מה זה שקרא הש' יתע' שם לאלו השלשה דברים לבד מבין שאר הנמצאות ובנשאר מהם קרא האדם שמות כאשר הסכים ולזה מבואר שהענין בבזה כפי מה שזכרנו והנה קרא המדרגה הגבוה' מאלה יום והשפלה ממנו לילה שלא יחשב חושב שיהיה אפשר למדרגה השפלה מאלו הצורות שתשיג בשלמות הצורה שהיא עליונה ממנה ותשוב היא והצורה דבר אחד כי אין באילו הצורות דבר בכח אבל כל מה שבהם הוא להם בפועל לא יקנו אחר זה שום שלמות זולת השלמות אשר נבראו עליו ביום הבראם ובהיו' הענין כן הנה העליונות הוא מתמיד העליונה והחסרון והשפלה הוא מתמיד בשפלה ולזה יקרא שם לעליונה יום מצד יתרון אורח וזיוה ויקרא שם לשפלה לילה מצד תמידות חסרון אורה וזיוה ביחס אל העליונה ממנה ולזאת הסבה הוצרך לומ' ויקרא אלהים לכך כך בשלשה מקומות לבד בזאת הפרש כמו שאנו עתידים לבאר בג"ה. והנה אמרנו שאמר ויקרא אלהים לכך כך כשהיה הדבר ההוא מתמיד לפי שהוא מבואר שהדבר לא יהיה נקרא בשם העניין אשר לא יתקיים לו כי אם מעט כמו אדמימות הביישן וירוקות הפחדן שלא יקרא מפני זה אדום או ירוק ואמנם יקרא אדום או ירוק מי שהיה כן בטבע:
@6 **ויאמר אלהים יהי רקיע.**
@6 **באור דברי הפרשה:**
@6 **אמר** הש' ית' שיהיה גרם שמימיי ממקצת הגשם הבלתי שומר תמונתו הנקרא בזה המשל מים ושיהיה עוד נברא טבע מבדיל בין החלק אשר ממנו למטה מהרקיע ובין החלק אשר ממנו מלמעלה לרקיע. וזה הטבע הוא ההכנה והכח אשר נתן הש' ית' בעת הבריאה לחלק השפל לקבול הצורות היסודיות אשר הוא בחיי עליהם. ועשה זה הש' יתע' כשרצהו ר"ל שהוא עשה את הרקיע והבדיל בין המים אשר מעל לרקיע ובין המים אשר מתחת לרקיע. כששם כח והכנה במים אשר מתחת לקבל הצורות אשר החמר הראשון כחיי עליהם. והמים אשר מעל לרקיע לא נתן להן זה הכח אבל הם נשארים על עניינם ובזה ההבדל היה זה המציאות בעניין אשר הוא בו ר"ל שקבל החמר השפל צורותיו היסודיות וצורת המתדמי החלקים המורכבים מהם כי יספיק בהויתם זה הכח וההכנה עם תנועת הגרמים השמימיים. ומפני זה לא ייוחסה הויתם לשם יתע' בזה הספור. ולפי שהרקיע הוא שם משותף לכל דבר נרקע קרא ש' יתע' זה הרקי' בשם ייחדהו שהוא שמים והרצון בו ששם דמיון שני מקומות בלתי מתנועעים והם קטבי הגלגל כי שם יאמר על המקום וכאלו באר בזה שהש' ית' שמם מתנועעים תכף שנבראו כי מצד התנועה יוכרו שני אלו המקומות. ולפי שהן הושמו בטבע שיהיו מתנועעים תמיד לא ינוחו אמר שכבר קרא הש' ית' לרקיע שמים כי אין להם כח על המנוחה כלל. וכבר ייוחסה זאת הבריאה ליום שני לסכה שזכרנו במה שקדם. והנה לא נאמר במה שנברא בשני כי טוב לפי שמה שנברא בו מעניין זה החמר השפל היה בו כח והכנה לבד כמו שבארנו והטבע הוא אשר הוציא זאת ההכנה לפעל. וענין שהוא כזה אין ראוי שיאמ' בו כי טוב למעוט חלקו במציאות. והגלגלים בו היו גם כן בלתי שלמים לפי שלא נבראו בהם הככבים ולזה לא אמר במציאותן כי טוב עד שנשלמו. וזהו אמרם בבראשית רבה למה אין כתוב בשני כי טוב ואמרו קצתם לפי שנברא בו גיהנם. ואמנם היה זה כן לפי שהכח וההכנה אשר לחמר השפל הוא סבה באופן מה אל ההפסד וההעדר. וקצתם אמרו מפני המחלוקת רוצה לומר כי בזה הכח אשר נתן לחמר השפל קבל הצורות היסודיות ההפכיות אשר הם סבות ההפסד כמו שהתבאר בחכמה הטבעית. וקצתם אמר לפי שלא נגמרה מלאכת המים רוצה לומר שמה שנברא במים התחתונים אינו פעל גמור אבל כח והכנה ומה שעשאו מהמים והוא הרקיע לא נגמר עניינו עד יום ד' שנבראו בו הכוכבים ואז נאמר בגלגלים כי טוב ולזה כלל זה העניין אמרם שלא נגמרה מלאכת המים כי כבר אמרו שהרקיע מהמים נתנוה וזה כשגלדה הטפה האמצעית כמו שזכרנו במה שקדם. הנה זהו מה שנראה לנו בביאור זאת הפרשה הזנית והוא נפלא כמו שתראה והוא מסכים לדברי רבותינו ז"ל ולאמת בעצמו לפי מה שביארנו מבריאת עולם כספר מלחמות יי'. וראוי שתדע שאי אפשר שיובן זה ההבדל שאשר בזאת הפרשה הבדל במקום שאם היה הדבר כן היה בזה המאמר מותר. וזה שהגשם אשר הוא באמצע המים אין ספק שהוא מבדיל בין מה שממעל ממנו ובין מה שמתחת. ולזה יהיה אמרו ויהי מבדיל בין מים למים מותר אין צורך לו וכן יהיה מותר אמרו ויבדל אלהים בין המים אשר מעל לרקיע ובין המים אשר מתחת לרקיע. ועוד שכבר יהיה אמרו ויהי כן בתכלית הזרות כי אחר שעשאו אין צורך לומר שיהיה כן. אמנם יצטרך לזה אלו לא אמר שעשה השם הרקיע וזה כשיאמר ויאמר אלהים יהי רקיע בתוך המים ויהי מבדיל בין מים למים ויהי כן וזה מבואר מאד. ולזה הוא מבואר שאמרו ויהי כן רמז בו אל הויה אחרת זולתי מה שזכר תחלה והוא מה שיצא לפועל באמצעות הטבע מפני זאת ההכנה נבראת בחמר השפל לפי מה שביארנו:
@9 **ויאמר אלהים יקוו המים מתחת השמים וגו'.**
@9 **בעבור** שהיה הגלות החלק הנגלה מהארץ מפני ההויות אשר יתהוו בו ר"ל הצמח והחי והיה זה החלק מהארץ דבר שאי אפשר שייוחס אל הטבע. זכר בבריאה אשר יחס אותה ליום הג' והוא היות הצמח ההוה ממינו מה שהמציאו השם יתע' בעת בריאת העולם מהראות היבשה. לפי שהוא דבר אי אפשר שייוחס אל הטבע. והנה המלות הזכרות בזאת הפרשה הם מבוארות:
@9 **וזה ביאור דברי הפרשה:**
@9 **אמר** השם יתע' שיאספו אל מקום אחד אשר היו מקיפות בטבעם אל יסוד הארצי בדרך שתראה היבשה ויהי הדבר כן. והנה קרא הש' ליבשה ארץ. ואע"פ שהארץ יאמר בכלל על כל היסודות בכללם כמו שקדם כבר נתייחס שם ארץ לזה היסוד להעיר שכבר יהיה תמיד זה החלק מהארץ נגלה. ולמקוה המים קרא השם יתע' ימים להעיר שכבר יהיה שם תמיד היסוד המימיי. ואמנם אמר ימים ולא אמר ים לפי שטבע הים מתחלף להתחלף טבע מקומות הארץ שאר יעברו מימיו בהם כמו שהתבאר בספר האותות. וזהו אמרם בב"ר והלא ים אחד הוא מה ת"ל ולמקוה המים קרא ימים אלא לא דומה טעם דג העולה מעכו לעולה מצידון ולעולה מאספמיא. והנה למדתנו התורה בזה המים הוא היסוד המימיי. וכבר ביאר זה הפילוסוף בספר האותות. וכבר ידע השם ית' כי מה שהמציאו מזה הוא טוב לפי שבו תועלת להיות ההויה בחלק הנקגלה מהארץ ובעבור זה התכלית המציאו הש' יתע'. והנה קרא הש' יתעלה ליבשה ארץ ולמקוה המים קרא ימים להורות שחלק הנגלה מהארץ יהיה תמיד נגלה והים יהיה ים תמיד בדרך שלא יפסד זה המקום הנגלה בכללו'. ולזה יהיה לזה המקום זה השם תמיד ר"ל היבשה וכן העניין בים אשר הוא היסוד המימיי. ואחר זה אמר השם יתעלה שתוציא הארץ צמיחת ההוים ממנה וזכר תחלה הצומח החסר והוא עשב המזריע. ואחרי כן זכר השלם והוא האילן העושה פרי אשר בפרי ההוא זרע יתהוה ממנו מינו לפי שזה הוא הסדור הניאות לפי הטבע. וכבר יתבאר לך שהעשב הוא חסר בהקש אל האילן לפי שבו ימצאו רבים הוים מהעפוש מה שאין כן באילן. ועוד כי פעולות הטבעיות הם יותר שלמות. והנה בעת שאמר הש' שיהיו אלו הצמחים מן הארץ היו כמו שרצה ר"ל שכבר הוציאה הארץ דשא עשב מזריע זרע יתהוה מהזרע ההוא מינו. ועץ עושה פרי אשר בפרי ההוא זרע יתהוה ממנו מינו. וידע הש' ית' כי מה שהמציאו מזה הוא טוב ונתיחסה זאת ההויה ליום השלישי. ואפשר שנאמר שהרצון בזה הוא אשר אמר שיהיה אז כח לארץ להוציא אלו הצמחים ויהיה כן ר"ל שנתן לארץ כח והכנה אז על דרך פלא הוציאה אלו הצמחים כשצמחו ממנה כאלו היו נזרעים הזרעים בארץ ולא היו הצמחים האלו נמצאים בעת הבריאה יחד כשאר הנבראים. ולזה אמר אחר זה וכל שיח השדה טרם יהיה בארץ וכל עשב השדה טרם יצמח כי לא המטיר וגומר. כבר התבאר כי אחד זאת הבריאה הנזכרת כאן היתה הצמיחה וזהו אמרם בבראשית רבה. ותוצא הארץ דבר שהוא פקוד בידה ר"ל שהוא כמו פקדון בידה. ועוד אמרו שם תולדות הארץ בראשון כדברי ב"ה ושהתה ג' ימים ראשון ושני ושלישי והוציאה שלשה ילדות אילנות ודשאים וג"ע. כבר ביארו לך שהצמיחה אחר ששם השם יתעלה כח ההולדה היתה יחד בזאת הארץ זמן מה. והנה ידע הש' ית' באלו הצמחים שהמציא שהם טובים ולזאת הסבה לא אמר ויברא דשא עשב וגו' כמו שאמר בשאר הבריאות ויעש אלהים את הרקיע ויעש אלהים את שני המאורות ויברא אלהים את התנינים הגדולים ויעש אלהים את חית הארץ ויברא אלהים את האדם. אבל אמר ותוצא הארץ להורות על מה שבראו הש' ית' מהצמח לא נשלם הצמיחה כמו העניין בשאר הדברים שברא. כי שאר הדברים בראם שלמי הבריאה ביום הבראם ואפשר עוד שנאמר שהסבה באמרו ותוצא הארץ ולא אמר ויעש אלהים דשא עשב לפי שזה המין הוא מהבעלי נפש ולא ילבש צורה אחרת בתכלית שלמות הויתו כמו העניין בב"ח. וזה שכבר ימצא בב"ח תחלה הכח הצומח עד שתשלים הויתו שלמות מה שתגיע בו הנפש החיונית ולזה יצטרך התחלה אחרת זולת ההתחלה אשר שם אותה אז הש' ית' במים ובארץ ולזה ייחס זאת הבריאה לש' יתע' אבל הצמח לא יצטרך אל התחלה אחרת זולת ההתחלה אשר שם הש' יתע' להצמיח אלו הצמחים כי אין להם. צורה נוספת על הצמיחה:
@14 **ויאמר אלהים יהי מאורות ברקיע השמים להבדיל בין היום ובין הלילה והיו לאותות ולמועדים ולימים ושנים:**
@14 **באור דברי הפרשה:**
@14 **אמר** הש' ית' שיהיו גופים מאירים ברקיע השמים והם השמש והירח ושאר הכוכבים ואמנם רצה במציאותם להבדיל בין היום ובין הלילה ר"ל שיתחדשו מהם בזה העולם השפל דברים מקבילים מצד היום והלילה המתחדש מהם כי יתחדשו מהם בזה העולם השפל דברים טבעיים מקבילים בד' תקופות המתחדש מהכוכב. וזה כי בהיות השמש על האופק יגביר האויר והאש ובהיותו תחתיו יגבר הארץ והמים וזה מבואר מאד בשמש. וכן ראוי שנבין הענין ככוכב כוכב ר"ל שכבר יקרו ממנו דברים מקבילים מצד היום והלילה המתחדש ממנו. ובכמו זה העניין יקרה לשמש מצד מרחקו מהפיאה הצפונית אשר שם הישוב וקרבתו ממנה. רצוני כי בקרבתו יגבר האש והאויר ובמרחקו יגבר הארץ והמים. והיה יומו בזה האופן בהיותו בפאה הצפונית להיות ניצוצו אז חזק לקרבתו מהישוב. ולילו בהיותו בפאה הדרומית וכן ראוי שנבין העניין בשאר הכוכבים ר"ל שכבר ימצאו מהם דברים מקבילים מפני היותם פעם בצפון ופעם בדרום אשר הוא יום הכוכב ולילו כמו שהתבאר. וזכר עוד שאמנם רצה הש' יתע' במציאותם לתועלת שנית. והוא שיהיו מהם פעולות מתחלפות ייוחדו בהם הכוכבים קצתם מקצת ויהיו הכוכבים לאותות לאלו הפעולות אשר ייוחדו בהם. וזה אמנם יהיה מהם למועדים ולימים ושנים כאלו תאמר שבזה המועד יהיה המתחדש לפי מה שיגזרהו הכוכב האחד. ובמועד השני לפי מה שיגזרהו כוכב אחר עד שתאמר שהמושל בזאת השעה הוא שבתי והמושל בשעה השנית הוא צדק. והמושל בזה היום הוא שבתי והמושל ביום השני הוא השמש. וכן העניין בשנים ובשאר המועדים היותר גדולים מהשנה אשר תיוחס הממשלה בהם לכוכב ככב לפי מה שהונח בחכמת משפטי הכוכבים ויקרו מזה יחסים רבים מחלופי ההוראות והנה זכר שני מינים מהחלופים ר"ל החלוף אשר יקרה לככב בעצמו בפעולותיו מפני יומו ולילו שביומו תמשך ממנו פעול מקבלת ממנה. והחלוף אשר יקרה מפני הפעולות המתחלפות אשר יקרו מהכוכבים המתחלפים. עד שקצתם ימצא לו רושם מיוחד בהנעת האש. וקצתם בהנע' המים. וקצתם בהנעת האויר ובאלו שני מינים מהחלופים אשר זכר ישלם כל מה שנמצא בזה העולם השפל ויהיו נשמרים חלקיו כפי מה שאפשר כי בזה ישלם השווי בין היסודות והשמירה אשר לחום הטבעי אשר לנמצא כמצא הזמן האפשרי. ותשלם בזה האופן מהשגחה מאישי מין האדם לשמרם מהרבה מההזקים אשר יתכן שיזוקו בהם כמו שביארנו בביאורנו לספר איוב ובספר מלחמות השם. ובאלו שני הצדדין מהחלוף גם כן היה אפשר שיסתעפו מהגלגלים הפעולות הרבות המתחלפות אשר ימצאו בזה העולם השפל. וזכר עוד שכבר רצה הש' ית' במציאותם לתועלת השלישית והוא שיהיו מאירים על הארץ כי בזה ישלם מציאות האדם ושאר הב"ח וזה מבואר מאד כי בזולת האור לא ישיג דבר הכלי אשר בו יראה הב"ח מוחשיו והנה ראותו מוחשיו הוא הכרחי לו מאד כי הוא מהסבות היותר גדולות אל שיברח מהמזיק ויכוין אל הניאות והוא באדם עם זה מבוא אל השלמות במושכלות לפי שהתחלות המושכלות נקנה אותם מן החוש כמו שיתבאר במקומותיו ולפי שכבר רצה במציאות הככבים כדי שיגיעו מהם התועלת הנזכרות המציאם באופן שיתכן שיגיעו מהם ולזה המציאם בשעור אשר הם בו מהגודל ובמרחק אשר הם בו מהארץ ובשיעור מהתנועה מהמהירות והאיחור שהם בו. כי אם היה מתחלף ענינם באחד מאלו הענינים ממה שהם בו היה בלתי מגיע מהם זה התועלת. והמשל שאם היה השמש יותר גדול ממה שהוא היה נפסד זה המציאות השפל בקיץ מחוזק החום וכן אם היה יותר קרוב לארץ ממה שהוא. ואם היה יותר קטן או יותר רחוק מהארץ היה נפסד זה המציאות השפל בסתיו מחוזק הקור. ואם היתה תנועתו יותר מאוחרת ממה שהיא היה נפסד זה המציאות השפל מקיץ לחוזק החום לאורך התמדת השמש כפאה הצפונית ובסתיו לחוזק הקור לאורך התמדת השמש בפאה הדרומית. ואם היתה תנועתו יותר מהירה היה החום חלוש בקיץ יותר מן הראוי והקור בסתו. וכן ראוי שנבין העניין בככב ככב. ובהיות הענין כן הנה הוא מבואר כי הוא ית' מפני שרצה הככבים כדי שיגיעו מהן אל התועלות הנה המציאם ה' באופן היותר שלם שאפשר שיגיעו מהם אלו התועלות. ואמר שתכף שרצה הש' יתע' זה היה כן. וספר שכבר עשה השמש למשול ביום והירח בלילה והככבים אשר להם ג"כ ממשלה מה כמו שקדם. וזכר שכבר עשאם בצד שיגיעו מהם אלו התועלות הנזכרות ר"ל שיאירו על הארץ כדי שיוכל הב"ח לראות מוחשיו. ולמשול ביום ובלילה בדרך שיסודרו מהם אלו המקרים המתחלפים והמתחדשים בזה העולם השפל כשימשול זה פעם וזה פעם כמו שקדם. ולהבדיל בין אור הכוכב והוא עת היותו על האופן ובין חשך הכוכב והוא עת היותו תחת האופק. וכן יהיה אור הכוכב קורבתו מהפאה הצפונית אשר שם הישוב כי אז יהיה ניצוצו חזק בזאת הפאה הצפונית. וחשך הכוכב יהיה מרחקו מהפאה הצפונית כי אז יהיה ניצוצו חלוש בה. ולזה אמר בכאן. ולהבדיל בין האור ובין החשך תמורת מה שאמר ראשונה להבדיל בין היום ובין הלילה להוסיף ביאור על מה שכיון בזה המאמר. ולזה אמר ולמשול ביום ובלילה תמורת אמרו והיו לאותות ולמועדים ולימים ושנים ממה שיוסיף גלוי ושלמות על מה שבארנו בזה המאמר ר"ל אמרו והיו לאותות ולמועדים וימים ושנים. ואמר אחר כן שהשם ידע שמה שהמציאו מהכוכבים הוא טוב. ויחס ההויה זאת ליום רביעי.
@14 **והנה** בכאן שני ספקו' גדולות ראוי שנשתדל בהיתרם. האחד שכבר התבאר ממה שאמרנו שאלו הככבים המציאם השם יתעל בעבור אלו הנמצאות השפלות ויהיה אם כן הנכבד בעבור הפחות וזה שקר עצום אצל החכמים. והשני שכבר היה ראוי לפי הסדור הטבעי שתיוחס זאת ההויה ליום השלישי כי השמים והככבים קודמים בסבה ובמציאות ליסודות ולמה שיתהוה מהם:
@14 **ונאמר** שהספק הראשון ואם הוא מפורסם הנה אין התירו ממה שיקשה. וזה שכבר יראה תמיד שהנכבד ישלים השפל במה שישפע לו ובזה האופן ישלים השם יתעלה כל הנמצאות כמו שהסכימו עליו הפילוסופים ובעלי התורות ולא נאמר מפני זה שיהיה השם יתברך בעבור הדברים השפלים ממנו אבל נאמ' שמציאותו הוא באופן מהשלמו' שיוכל להשפיע משלמותו לכל הנמצאות לפי מה שאפשר להם שיקבלו ממנו. ואמנם מה שהוא מן השקר שישלם הנכבד בפחות רוצה לומר שיקנה הנכבד שלמות מהפחות עד שיהיה מהפחות משלי' הנכבד. ובהיות הענין כן הנה יסור זה הספק במה שאמרנו וזה כי הגלגלים נמצאו בעבור עצמותם ולמה שיהיה יותר נכבד להם שיתנועעו משינוחו כי היתה התנועה חיים לדברים הטבעיים הושמו מתנועעים. ולפי שכבר אפשר להם בתנועתם שישפיעו שלמות לנמצא השפל והיה יותר נכבד להם שישפיעו משלא ישפיעו לפי שזה דרך הנמצאים השלמי' שיערף להם מהשלמות באופן שישפיעו ממנו לזולתם הושמו תנועתיה' באופן שישלמו בהם הנמצאות השפלות. ולזה המציא השם יתע' בקצת חלקיהם ניצוצים מאירים שיהיו כלים להם להשפיע למה שלמטה מהם מצד הניצוצים המגיעים מהם. ובזה הותר זה הספק והוא עיון נפלא מאד נבוכו בו רבים. והוא מבואר שזה ההיתר לא יספיק בשלמות אם לא בהנחת העולם מחודש ולזה זכרה בכאן התורה בריאת הכוכבים והתועלת המגיע מהם אשר בעבורו נמצאו להעמידנו על שהעולם מחודש כי העיון יחייב עם ההתכוננות הטוב שבריאת הכוכבים הוא לאלו הפעולות לבד לא לעצמות הגלגלים כמו שביארנו בספר מלחמות השם. והיות גם כן לככבים פעולות מתחלפות עם היותם מטבע אחד אי אפשר גם כן שישלם לפי הטבע ולא התחלפות' משאר חלקי הגלגל כי הם עמו מטבע אחד אי אפשר גם כן שישלם לפי הטבע ולא התחלפותם קצתם מקצ' ושיהי' זה מאיר מעצמו וזה יקב' האור מזולתו ולא התחלפות' משאר חלקי הגלגל כי הם עמו מטבע אחד ולזה תלקח הוראה חזקה בעניין הככבי' בחדוש העולם כמו שביארנו בספר מלחמו' יי'. ואולם הספק הב' הנה הוא קשה מאד וראוי שנאמר כהיתרו לפי קצורנו. ונאמר כי התורה זכרה זה הספור להעמידנו על חכמת הנמצאות לפי מה שאפשר בחדוש העולם. וכוונה עם זה לפי מה שיראה מדבריה להיישינו אל הדברים שיישיר אותנו מאד מצד העיון שהעולם מחודש. ולפי שהגלות הארץ הוא מהדברים שיישיר בנפשותנו אמונת החדוש לפי מה שאי אפשר שייוחס ענינו אל הטבע כמו שביארנו בספר מלחמות יי'. הנה רצתה התורה לזכור בריאת הככבים אחר בריאת הגדלות הארץ כדי שלא נטעה כשניחס הגלות הארץ אל הכוכבים כמו שעשו הפילוסופים כשלא מצאו בכאן סבה אחרת ייחסו אליה הגלות הארץ. וכבר יראה שהוא בלתי אפשר שתיוחס זאת ההויה אל הככבים לפי שאם הענין כן היה המקום הנגלה מהארץ שלם הסבוב כי הככבים האלו סובבים סביב מחלק הארץ אשר תחתיהם סבוב שלם על יחס אחד ואנחנו לא נמצא העניין כן אבל נמצ' שהחלק הנגלה מהארץ לא יעדיף על חצי הקף המקו' ההוא הנגלה כמו שהתבאר בספר מלחמות השם באופן שלם ובכאן הותר זה הספק:
@20 **ויאמר אלהים ישרצו המים:**
@20 **ראוי** שנציע בכאן מה שכבר התבאר בספר ב"ח מדרגות הב"ח והו' שהחי היותר חסר מהב"ח המולידי' מינם הוא המימיי ואחריו המעופף ואחריו החי הולך בלתי מדבר והאדם הוא הב"ח השלם בתכלית מה שאפשר ויורה על זה במה שנזכר שם. כי החי המימיי עושה ביצה בלתי שלמה והחי המעופף עוש' ביצה שלימה והחי ההולך מוליד ב"ח ובזאת ההדרגה נזכרת בכאן בריאתם רוצה לומ' שכבר נזכר' תחלה בריא' המימיי ואחריה בריאת החי המעופף ואחריה בריאת החי ההולך הבלתי מדבר ואחריה בריאת החי המדבר ולהיות מדרגת העופף ממוצעת בין מדרגת המימיי והארציי' אמרו רבותינו ז"ל על העופות שנבראו מן הרקק אשר הוא מים וארץ מעורבי' והנה לרוחק בריאת האד' מבריאת שאר הב"ח היה ראוי שיפריד לבריאתו יום אחד. ואמנם זכר עמה בריאת ב"ח ההולך להיותה במדרגת ההיולי הקרוב לו ולהיות הולדת החי המימיי והמעופף חסרה נצטרכו לברכת פריה ורביה רוצה לומ' שהם צריכין להשגחה אלהית נוספת בהולידם כדי שתשלם ההויה ויתקיים מינם יותר מהב"ח ההולך כי הוא עושה ב"ח בגופו וזאת ההשגחה היא שנתן להם השם ית' כלי תשלם בו הולדתם החסרה ולזה נתברכו הדגי' והעופות בשיפרו וירבו ולא נתברך הב"ח ההולך. ולזאת הסבה לא היה צריך האדם שיתברך שיפרח וירבה כי כבר נתן לו השם יעלה בבריאתו כח שלם להולדה, ולזה הסכימו רבותינו ז"ל שמה שנאמר בכאן לאדם ויאמר להם אלהים פרו ורבו ומלאו את הארץ הוא מצות עשה. ובכאן עוד סבה אחרת תחוייב שיהיה זה המאמ' מצוה לא נתינת טבע על ההולד' והוא שזה הפועל רוצה לומר חבור הזכר והנקבה הוא באדם מהבחירה כי באדם כח אל שיעשה זה הפועל ואל שלא יעשהו ואפשר לו גם כן שיעשהו בזולת עשיית פרי כשיהיה דש מבפנים וזורה מבחוץ כמו שאמרו רבותינו ז"ל על אונן כמה שספרה עליו התורה. והיה אם בא אל אשת אחיו ושחת ארצה. מה שאין כן בשאר הבעל חי והכרעת השם יתברך אחד משני חלקי האפשר אשר תפול בהם הבחירה אל שתהיה אליו הבחירה הוא בהכרח מצוה לא טבע ובהיות העניין כן הנה יהיה בלי ספק זה המאמר מצוה. ואולם נזכרה בכאן לפי שהיא הולכת מדרגת השלמה מהבריאה האנושית כי בזה יתקיים המין האנושי ולפי שהו' זכר בכאן בריאת שאר הדברים הנולדי' ממינם והסבות העוזרו' להם לקיום מינם כדי שימשך המציאות זכר גם כן זאת המצוה עם זכירת בריאת השם האדם. וראוי שתדע שזאת המצוה נתנה פעמים כמו שהשרישו ז"ל זה בפרק גיד הנשה ואמנם היה זה כן לפי שהתורה בכללה תמצאה מיוחסת למשה רבינו עליו השלום וזה נכפל הרבה בתורה ובדברי הנביאים. אמר תורה צוה לנו משה מורשה קהלת יעקב. זכרו תורת משה עבדי. עם שכבר נתייחד משה ע"ה בזאת המדרג' מהנבואה מבין שאר הנביאי' ולזה יחוייב שתהיה התורה בכללה נתונה ע"י משה רבי' ע"ה עד שכבר תמצא שמצות מילה שצוה בה אברהם הושב הצווי בה בתורה אמ' וביום השמיני ימול בשר ערלתו וראוי זה להיו' כן לפי שהתור' בכללה היא נימוס אחד יכון בו אל תכלית אחד במספר והוא ההצלחה האנושית והפועל האחד כמה שהוא אחד במספר ראוי שתהיה הגעתו בעצמות מאחד במספר וגם כן הנה הנבואה האחת במה שהיא אחת תמצאה תמיד מגעת לנביא אחד ואם הגיע לשנים הגיע בכללה לאח' ואח' מהם כמו שתרא' מנבואת ישעיה וירמיה במה שנתנבאו יחד על דבר אחד. ואולם החסרון המגיע בנבואה הוא שכבר יקרה שלא יודע פירושה לו כמו העניין בנבואת דניאל אבל עכ"פ יגיע אליו כל הנבואה לא חלק זולת חלק ובהיות הענין כן הוא מבואר שכלל התורה ראוי שיהיה נתן ע"י משה. ואם נתן ממנה חלק לזולתו שיושב הצווי בו במה שנתן לו מהתורה וגם כן הנה תמצא שמה שהתאמת לישראל כמעמד הר סיני הוא נבואת משה רבינו וקבלו עליה' לעשו' כל מה שהגיע לו בנבואה ואלו היה קצת התורה נתון ע"י זולתו מהקודמים הנה לא יהיה זה ממה שהתאמת ענינו לישראל ולא ממה שקבלוהו עליהם ואם אמרנו שכבר הגיע למשה בנבוא' שזה החלק נתן לזולתו בנבואה שלמה ויאמינו בו ישראל מזה הצד כמה אני תמה למה קיצר הש"י משיתנהו למשה עצמו והצריכו להתחבר לנבואתו בנבואת זולתו עם היות נבואת זולתו מגעת לו בנבואתו זה ממה שלא יתכן ולזה מי שיראה שהתורה כולה נתנה למשה ומה שנתן ממנה לזולתו כמו המילה שצוה בה אברהם לא נתן על שיהיה החלק מהתורה אבל נתן לתכלית מיוחד והוא שיהיה לאות ברית בינו ובין השם יתברך ולהישיר אל שיהיה ממנו זרע מוכן אל השלמות ולקבל זאת התורה האלהית כמו שיתבאר במקומו בג"ה וגם כן אלו נתנה התורה חלקים חלקים על שם שהם חלקי' מהתורה מזולת שתהיה בכללה מנעת על ידי אחד הינו באחד משני דברים אם שנאמ' שמה שכיון בחלק חלק ממנה כשנתן נפרד בעת נתיבתו הוא תכלית אחר זולת התכלית המגיע בעצמות מהתורה ויהיה אם כן הגעת זה התכלית האמתי מהתורה בדרך המקרה וזה מגונה או נאמר שכבר כוון בחלק חלק ממנה כשנתן נפרד זה התכלית והוא ההצלחה האנושית ויהיה אם כן חסר למה שהגיע מזה הנימס כפעם בפעם כי הוא נתן לתכלית אי אפשר שיגיע ממנו אם לא כשיתחבר נימוס זולתו וזה ג"כ מגונה כי לא תבא הנבואה בזה האופן מהחסרון כמו שקדם ובהיות העניין כן הוא מבואר שהוא ראוי שתהיה התורה בכללה נתונה ע"י משה וזה מבואר שזה המאמר והוא מה שנאמר בבריאת האדם פרו ורבו ומלאו את הארץ נצטוינו בסיני ואז היה העולם מלא:
@20 **באור דברי הפרשה:**
@20 **אמר** השם יתברך שישרצו המים שרץ נפש חיה ושיתהוה עוף יעופף על הארץ על פני רקיע השמים וכן היה. רוצה לומר שכבר ברא ה' בזה האופן כל מיני הדגים המולידים מינם הנמצאים במים וכל מיני העוף המולידים מינם וידע השם ית' ממה שהמציאו מזה הוא טוב מאד לתכלית אשר אשר בעבורו נמצא ונברא וכבר בראו גם כן באופן היותר שלם שאפשר בבריאתם עד שמה שנשיגהו מן הטוב והחנינה אשר המציא בבריאתם ואם הוא רב מאד כמו שהתבאר בחכמה הטבעית אצל זכרון תועלת אברי הב"ח הנה הוא מעט מזער בהיקש אל מה שיש מן הטוב ומן החנינה בבריאתם. ולפי שהכח שנתן להם ביצירתם על ההולד' הוא כח חסר ברכם השם יתברך כשיפרו וירבו וימלאו הדגים את הארץ בימים והעוף יפרה וירבה בארץ וזאת הברכה היתה שנתן להם כטבע כחות עוזרי' להשלים תולדותיהם החסרה כמו שקדם. וכבר נתיחסה זאת הבריאה ליום החמישי:
@24 **ויאמר אלהים תוצא הארץ:**
@24 **ביאור דברי הפרשה:**
@24 **אמר** השם יתברך שתוציא הארץ מיני הב"ח ההולכים המולידים מינם וכן היה ר"ל שכבר עשה השי"ת כל מיני הב"ח הבלתי מדברים ההולכים בזה האופן וידע השי"ת במה שהמציאו מזה שהוא טוב למה שהמציאו בתכלית מה שאפשר בו כי הוא שם יצירתו באופן היותר נכבד שאפשר למה שכוון בו ואח"כ אמר הש"י לעליונים ותחתונים שיעשה מהם אדם בעל שכל ואמר ה' גם כן שיהיה זה האדם באופן מהבריאה שישלטו אישיו בכל הבעלי נפש הנמצאים בעולם ההויה וההפסד וכן עשה ר"ל שכבר ברא השם יתברך בזה האופן את אר' בצורה האנושי' המיוחסת לו והוא השכל ההיולאני ולזה בראו בצלם העליונים כמו שקדם כי שכל האדם נתייחס באופן מה לשכל העליונים והנה בראם זכר ונקבה כי בזולת זה לא תשלם ההולדה וכזה ראוי שנבין שיהיה זה העניין במה שבראו השם יתברך משאר הב"ח והנה ברכם הש"י להשגחה על קיומם ושמירתם ואמר להם שיפרו וירבו וימלאו את הארץ ויחזיקו בה. ר"ל שכבר גזר בבראם שיצוה האד' בזה כשימצא שם מקבל ראוי שתנתן התורה על ידו ונתן להם גם כן ביום הבראם שישלטו בדגת הים ובעוף השמי ובכל הרמש הרומש על הארץ. וכבר זכרנו במה שקדם שמה שאמר בכאן פרו ורבו הוא מצות עשה נצטוינו בו בסיני. וכבר נזכרה בכאן בכאן להיותה הולכת מדרגת השלמו' מזאת הבריאה האנושית לפי שבה יתקיי' המין האנושי ועוד שכבר היתה ראויה זאת המצוה ושאר המצות התוריות הנוהגות מנהגה להנתן מן היום שנבר' אדם אלא שלא היה שם נביא יהיה ראוי שינתן התורה על ידו עד עת בא משה רבינו אדון הנביאים ולזה תמצא אותם רז"ל אומרים שהתורה נברא' קודם שנברא העולם ובהיות העניין כן הנה יהיה זה המאמר התוריי כאלו נאמ' אז להיותו מכוון בעת הבריאה ולהיותו הכרחי להתמיד מציאות המין והאנושי ולזה ג"כ נזכר בזה המקום והנה ראוי שנבאר שרשי זאת המצוה מהמלות הנאמרות בה כמו שיעדנו ונאמ' כי השרש הראשון מזאת המצוה הוא שהוא לאיש ולא לאשה וזה שהאשה אין ספק בידה לעשות והמצוה אמנם תצוה למי שאפשר לו שיעשה ואמנם שאין ספק ביד האש' לעשות זאת המצוה הוא מבואר לפי שאין לאשה התחלה בזה הפועל אבל היא מקבלת הפועל ואין בבחירת' ג"כ עשיית זה הפועל כי כבר אפשר שתכין עצמה לקבל זה הפועל ולא ישלם ממנה פרי להיו' הזכר דש מבפני' וזורק מבחוץ. וכבר נתבאר זה השרש בששי מיבמות:
@24 **השרש** השני שלא יפט' האד' מפריה ורביה אם לא יהיו לו זכר ונקבה ישלם בהם מלא כל הארץ. וזהו שאמרו פרו רמז בו על ההולדה ואמרו ורבו רמז בו חיוב הרבוי בהולדה ואמרה ומלאו את הארץ יתחייב שישלם בזה מלא הארץ והנה הרבוי הראשון בהולדה הוא שנים לפי שאי אפשר לקיום העולם בלא זכרי' ובלא נקבות הנה יהיו אלו שנים זכר ונקבה ובזה ישלם מלא הארץ כי האד' ואשתו הם זכר ונקבה ואם יולידו זכר ונקבה לא יחסר מלא הארץ בהפקדם עד שישלם בזה האופן קיו' אנשי הארץ על עניי' אחד ויתבאר ממה שאמרנו שאם היה הזכר סריס או הנקב' אילוני' או שמתו ולא הולידו הנה לא נפטר האב מפריה ורביה כי אלו התולדו' לא ישלם בהם מלא האר' אבל נפקד מקומם במותם. ואולם אם הוליד זכר ונקבה ומתו ונשאר לו מהם זכר ונקב' הנה הוא פט' מפריה ורביה כי כבר השלי' חקו במה שהוליד ונשאר לו מהם מה שישלם בו מלא האר' אבל אם לא הוליד האב זכר ונקבה והיו לו ממי שהוליד אותו זכר ונקבה הנה לא נפטר האב מן פריה ורביה כי לא השלים חוקו הראוי לעצמו. וכבר נתבאר זה השרש וכל מה שחוייבנו ממנו בששי מיבמות:
@24 **השרש** הג' שהאדם יתחייב בזאת המצוה מעת היותו ראוי על מנהג הטבעי להוליד הולדה שלמה ישלם בה מלא הארץ וזה יתבאר ממה שאמר ומלאו את הארץ. וכבר זכרו רז"ל שזה הזמן הוא מן התורה לפי מה שהיה מקובל אצלם מעת היותו בן כ' שנה לא קודם זה. ואע"פ שהוא יכנס בגדר שאר המצות מעת היותו בן י"ג שנה ויום אחד. והסבה בזה שהאדם בהכנסו לגבול י"ג שנה ויום אחד ימצא בו המותר הזרעי מעט להכלו' מזונו בגדול חזוק הנמצא לו סביב הזמן ההו' ולזה אם יוליד אז יהיה הולדה חסרה לפי המנהג הטבעי ובזה תמצא שאפלטון יצוה בהמה שחבר מהנהגת המדינ' החשובה שלא יתחברו הזכרי' לנקבו' אם לא אחר שיגיעו קרוב לזמן אשר הגבילוהו חז"ל כדי שיהיו הנולדי' שלמי היצירה וכבר נתבאר זה השרש בפרק ראשון מקדושין ואולם מה שיתחייב מאלו השרשים בשנית אין מבוא לזכרו בזה המאמ' והמשל שכבר יתחייב מזה כמי שלא קיים פריה ורביה שלא ישא אשה. בלתי ראויה להוליד ושלא יקיימנה אם נשאה אם לא ישא עמה אחר' בת בני' ואלו הדינין ג"כ התבארו בו' מיבמו' ובמקומות מכתובות:
@24 **והנה** התועלת בזאת המצוה מבואר והוא שימשך ממנה קיום המין האנושי כי האדם להיות פעולתיו בבחירתו היה אפש' לו שישחית מינו כאלו תאמ' אם תשלם ההסכמה בין האנשים להמנע מהוליד ולזה השגיחה בו התורה בזה האופן. ולזאת סבה בעינה מנעתנו התור' מהשחית כלי ההולדה ומהרביע כ"ח כלאי' כי ההולד' תפסק בזה האופן כמו שהתבא' בספר ב"ח. ואח' שנשלם לנו ביאור שרשי המצוה הזאת ותועלתה נשוב למה שהיינו בו מהביאור. אמר הש"י הנני נותן לכם כח שיהיה כל עשב וזורע זרע ופרי עץ הזורע זרע נאות לכם למזון ובזה אתן כח לכל הב"ח המעופפים והולכים שיהיה לכם נאות זה למזון עם כל ירק עשב ר"ל שגם עלי הצמחים והאילנות יהיה נאות להם למזון וכאשר רצה יי' שיהי' זה כן היה כמו שרצהו ואולם זכר בכאן זאת הבריא' כי בה תקיימו אלו המינין וישמרו מציאותם והנה ידע ה' כל אש עשה והנה טוב מאד למה שכוון בו וכבר המציאו באופן היותר שלם שיהיה אפש' וכבר כלל בזה המאמ' כל אשר עשה לפי שמה שעשה מהעולם היה קצתו בלתי מכוון בעצמו ולא נשלם הטוב עד השלם התכלית אשר בעבורו היה מה שלפני התכלי' וכן הטו' השלם לא נשלם לעולם בכללו עד שיהיה בשלמות ותמותו וכבר יחס זאת ההויה ליום הו' וכבר הודיענו בזה שרש אח' נבנית עליו כל החכמה הטבעית והוא שאין בנמצאו' הטבעיות דבר לבטלה:
@32 **ויכלו השמים והארץ וכל צבאם:**
@32 **ביאור דברי הפרשה:**
@32 **איר** שכבר זכר מדרגות הבריאה בשלמות חתם מאמרו שכבר נשלמו באלו הששה ימים השמים והארץ ומה שבהם מן הנמצאת ולפי שזאת הפעולה אינה במדרג' המלאכה אשר נעשה אנחנו באומנו' שלא תצטרך אל הפועל אחר ההשלמה כאלו תאמ' הבית כשיבנה כבר יתקיים ואם נעדר הבונה אבל היא צריכה אל הפועל תמיד יעמידנה וישמרנה כמו שהתבאר באלהיות הנה זכר שביו' השביעי חשק השי"ת הסדור המושכל אשר לנבראות שהחשק ההוא הוא סבת קיום המציאות כמו שקדם ואז שבת מכל מלאכתו אשר עשה ר"ל שלא נצטרך אחר זה לחדש הנמצאות על זולת המנהג הטבעי והנה נתיחסה ליום השביעי זאת ההשג' והחשק אשר הוא סבת קיום העולם על ענינו אחר שנברא כי היא כמו מדרגת שביעית לבריאה אבל היא המדרגה היותר נכבדת:
@32 **אמרו** בב"ר משל למלך שעשה לו חופה סיידה וכיירה וציירה מה היתה החופה חסרה כלה שתכנס לחופה. כך מה היה העולם חסר שבת. ורבנן אמרי למלך שעשה לו טבעת מה היתה חסרה חותם שלה כך מה היה העולם חסר שבת וזה מאמר נפלא מאד לפי מה שרצהו כי בלי ספק מה שאמרנוהו לא יתכן שיאמר על הזמן אשר יכללהו יום השבת כי איננו הולך מהלך השלמות והתכלית מהנבראות כמו שהמשילו וכאשר התישב לנו זה הפירוש הנה אפשר שנפרש ויכל אלהים מעניין ההשלמה ויהיה הכל הולך אל מקום אחד עם הפירוש הראשון וזה כי זאת ההשלמה אמנם היא במה שיתמיד השם ית' להמציא הנמצאות באופן שהם עליו וזה אמנם יהיה ממנו במה שיושפע ממנו תמיד על האופן שזכרנו והיא כמו מדרגה שביעית לבריאה ולזה נתייחסה ליום השביעי ולהורות על עניין חדוש העולם ובאופן אשר יעמיד בו הש"י זה המציאות אחר שבראו בירך אלהים את יום הז' וקדשו. וזה אמנם היה כשנתן התורה באמרו' כי ששת ימים עשה יי' את השמים ואת הארץ וגו'. על כן ברך אלהים את יום השביעי וקדשו כי היתה לו מנוחה מכל מלאכתו אשר ברא לעשות המציאות תמיד על עניינו כמו שקדם וראוי שלא נעלם מדוע לא נקרא הש"י בכל מה שקדם מספור מעש' בראשי' כי אם אלהים ובמה שבא אחר זה נקרא יי' אלהים לולא בדברי נחש וחוה עד עניין קין והבל ומענין קין והבל עד סוף הפרק נקר' יי' ואחר זה נקרא לפעמים אלהים ולפעמים יי' כי זה בלתי אפשר שלא יהיה לענין כמו זה המאמר השלם. ונאמר כי מה שתגזרהו החכמ' האלהית שיהיה הוא מה שהמציאו הש"י בששת ימי בראשית כי מה שנהיה היה כפי הסדור המושכרל לש"י מענין המיאו' אשר יתכן שישתלשל ממנו כשרצהו השם ולזה אמרו רז"ל שהעולם נברא במדת הדין והנה תמצאם שיקראו מידת הדין מה שיאות אל טבע המציאות ומידת רחמים מה שיעשהו יי' על זולת המנהג הטבעי להשגיח על עונש חסידיו ויראיו וכאשר התישב לנו זה נאמר כי השי"ת ואם אחד פשוט בתכלית הפשיטות הנה יתואר בשני אלו השמות ר"ל יי' אלהים משני צדדים מתחלפים וזה שמצד עצמותו יתואר בשהוא יי' כמו שאמר זה שמי לעולם והוא השם המור' על עצמותו אשר לא ישתתף עמו זולתו כי הוא מורה על עניין חיוב המציאות אשר ייוחד בו הט"י ר"ל שמציאותו הוא מצד עצמותתו ומציאות זולתו הוא נשפע ממנו כמו שיתבאר בג"ה בפרשת ואלה שמות ומצד מה שיתכן שיושפע ממנו זה המציאות וינהיגהו בהנהגה המתוקנת בתכלית מה שאפשר נקרא אלהים ולפי שאחר שנשלמה הבריא' בששת ימי בראשית הספיק לזאת ההנהגה אשר ינהיג בה העולם השיגו עצמותו כמו שקדם אשר זאת ההשגה היא עצמותו נקרא יי' כמו שהתבאר למי שעיין בספר הנפש ובחכמות האלהיות הנה שבלקרא אותו בשם אשר יורה על עצמותו ועל זאת ההשגה יחד ולזה קראו יי' אלהים. וכבר אמרו בב"ר שהוא מזכיר שם מלא על עולם מלא הוזה מאד נאות למה שזכרנוהו ומזה הצד יתבאר שכבר יספיק להעמיד המציאו' מה שיורה עליו או מה שיורה עליו שם אלהים כי הכל עניין אחד וזה כי מצד השיגו עצמו אשר זאת ההשגה היא עצמותו נקרא יי' אלהים וזאת ההשגה מספקת בקיום המציאות על עניינו ומצד השיגו הסדור המושכל אשר לנמצאות יתואר באלהים כי בזאת ההשגה תשלם ההנהגה המתוקנת למציאות וזאת ההשגה היא ג"כ השגת עצמותו כמו שקדם ולזה נקרא אחר זה פעם יי' ופעם אלהים. הנה זה הוא מה שנראה לנו בזה המקום והוא נפלא מאד ומסכים ללשון התורה ולאמת בעצמו ובכאן נשלם לנו הביאור המסכים לאמת וללשון התורה בכל מה שבא במעשה בראשית. ישתבח וית' הצור המגלה לנו עמוקותיו ברוב רחמיו וחסדיו על כל ברכה ותהלה. וראוי שלא נקצר מלתת תודה לקודמים במה שדברו במעשה בראשית כי הם ואם נמצאו רחוקים מאד מהכונה אשר מצאנוה בכאן כמו שתראה ממה שביאר בזה הרב המורה גספרו הנכבד מורה הנבוכים והחכם ר' אברהם א"ע בפירוש התורה הנה הם היו סבה באון מה להעמידנו על האמת בזה ואולם השלמות המאמר בחידוש העולם והתרת הספקות הנופלות בו מדרך העיון היה ממנו בספר מלחמות יי' ולא ראינו בכאן לזכור דבר מזה כי יצטרך זה למאמר ארוך לא יכילהו זה הספר ומהנה נתחיל לבאר שנמשך לזה בתורה מספור סודות המציאו' ואנחנו מתנצלים תחלה אם לא ימצאו דברינו מסכימים ללשון התורה כמה שקדם לנו מהביאור לפי שפוטי הכתובים על האופן שנמצאו מסכימים ללשון הענינים הנמשכים לזה הושמו בתורה העלמים מאד במשלים חזקי העלם וההסתר':
@32 **והתכלית** המכוון בו לפי הנראה לנו הוא להודיע הכלים אשר נתן י' ית' לאדם להגיעו אל ההצלחה הנפש אשר בה יהיו לנו אלו החיים הנצחיים ואנחנו מציעים בכאן הצעה מקפת בכל מה שילכלהו זה הספור הנמשך לזה עד פרשת והאד' ידע את חוה אשתו וזה שכבר התבאר בספר הנפש כי השכל האנושי ערום בתחילת הבריאה מכל המושכלות אשר ישיגם ושהשכל הפועל הוא אשר ישפיע לו המושכלות באמצעות החושים והכח הדמיוני והכח הזוכר וזאת ההשפעה אשר ישפיע לו בהודעת סודות המציאות העמוקים תדמה לברק או ללהט החרבה המתהפכת שיוצץ פעם ויעלם פעם מפני קושי הגעת ההתבודדות אשר יצטרך לשכל האנושי מבין שאר כוחות הנפש בזה האופן מההשג' כמו שביארנו בביאורינו לשיר השירי'. וכבר זכר זה הרב המורה גם כן בספרו הנכבד המורה נבוכים וכבר ביארנו זה בראשונה ממלחמות יי' שההצלחה שתגיע לאדם בהשכילו מנימוס הנמצאות וסדרם וישרם כפי מה שאפשר לו ושבזה האופן יחיה שכלו החיים הנצחיים ויות' מה שאפשר שיודע לו מסודות המציאות הוא מה שבזה העולם השפל. ר"ל הסדור המושכל אשר לו ואולם בשמים ומה שעליהם במדרגה תהיה השגתו חלושה לרוחק מציאותו ממציאותם בעצם ובמקום וכבר התבאר בספר הנפש שהכח המדמה והכח המתעורר יביע הב"ח אל מה שיתנועע אליו או ממנו וזה המדמה כבר יצייר דבר מהמדברים המוחשים ויתעורר כח המתעורר מהציור ההוא ויגיע הב"ח אל שיתקרב למוחש ההוא אשר ציירו הכח הדמיוני או שיברח ממנו ולפי שבזה האופן יקרה לאדם שימשך אחר ההנאות הגופיות אשר הם המרחיקות אותו משלמותו הנה יהיה הכח המתעורר הוא יצר הרע והכח הדמיוני הוא המנהיגנו הנה כבר התבאר לך שהכח הדמיוני הוא כלי להגעת השלמות לאדם והוא בעינו כלי להרחקת השלמות אלא שזה אמנם יהיה מצדדים מתחלים המכוון בו ביצירתו הוא ההגעה אל השלמות ומבואר גם כן שבכאן הגות אנושיות אינן לאדם במה שהוא אדם אבל ישתתף בהם באופן מה לב"ח והוא השגת הטוב הרע כאלו תאמר ידיעת הערב מהדברים והבלתי ערב אשר הוא טוב ורע אצל קצת האנשים והמועיל מהם והמזיק והנאה מהם והמגונה כי על כל אלו דברים יאמר הטוב והרע לפי מה שיראו האנשים עד שקצתם ישים הטוב הערב והרע הפכו וקצתם יראה שהטוב הוא הכבוד והרע הפכו וקצתם יראה שהטוב הוא הנצוח והשררה והרע הפכו וקצתם יראה שהטו' הפעולו' היפות והרע הפכם כמו שנזכר כספר המדות. הנה אלו הדברים ואם הם מגיעים לאדם באופן מה מהשכל באמצעות החושים כמו העניין בשאר ההשגות האנושיו' הנה לא יגיע בקניינם לאדם ההשארות הנפשי המכוון בו אבל אולי ירחיקהו ממנו וזה אם נמשך לדברים הערבים להנאה המגעת לו מהם אם מצד שיכלה זמנו בחקירות אלו הדברים ותמנע ממנו ההשגה בנימוס הנמצאות וסדרם וישרם אשר בה תהיה ההצלחה האמיתית כמו שקדם ואולם אמר שכבר ישתתף כאלו ההשגות באופן מה לב"ח וכן תמצא בקצת הב"ח ההשגה המועיל והמזיק עד שהם יברחו מהדברים המזיקי' להם ואם לא קדם להם הרגשה כברוח אפרוחי התרנגולים מהעוף האוכל אותם והשה מהזאב ויקרבו אל הדברים המועילים כמו שתמצא בחולדה שכאשר נשכח הנחש תלך לעשב אחד בעל קוצים ותגלגל עליו כדי שינקב עורה במקומות רבים ויצא ממנה ארס הנחש וכן תמצא כסנונים שכאשר ינקרו עיני אפרוחיה תבקש עשב הסנונים אשר הוא מועיל לזה תועלת נפלא ובכלל הנה מה שתמצא מזה לב"ח הם הרבה וכן תמצא בקצת הב"ח השגת המגונה והנאה עד שיאמרו שהסוס לא יבא על אמו והגמל לא ישמש בפני כל בריה ותרנגול לא יזקק לתרנגולות אם לא פייסה תחלה ולהיות דעות האנשים מתחלפות בעניין הטוב והרע זה האופן מהחלוף עד שהטוב אצל קצתם הוא זולת הטוב אצל קצתם יתחלפו תכונות האנשים חלו רב כי כל אחד מהם יבחר במה שהוא טוב אצלו כמו שנזכר בספר המדו' ומבואר גם שנקבת האדם תתיחד מבין שאר הנקבות הב"ח שהיא נבראת לעבודת הזכר באשר ישלם לו הפנאי להשתדל במושכלות להגיעו אל הצלחתו. ואולם נקבות שאר הב"ח לא ימצא בהם זה היתרון לזכר על הנקבה. הנה זהו מה שראינו להציעו קודם שנכנס לביאור זאת הפרשה וכמעט שכל ענייני זאת הפרשה מבוארים בו:
@35 **אלה תולדות השמים והארץ:**
@35 **ביאור דברי הספור:**
@35 **אלה** תולדות השמים והארץ ביום הבראם כאשר עשה הש' ית' התחתונים והעליונים ר"ל מה שכבר זכר אותו מהבריאה על מדרגותיו והנה בעת הבריאה לא היו האילנות נראים בארץ עדין ולא צמחו העשבים כי לא ירד עדיין המטר ולא היה האדם נמצא בעת ההוא שנבראו שיעבד האדמה והאם שני דברים צריך הצמח אליהם או לאחד מהם לכל הפחות. ק"ל עבודת האדמה והמטר ולזה לא נראו הצמחים תכף הבריאה ההיא אבל הצמיחה אותם הארץ מעט מעט באמצעות המטר עד שנשלמו והמטר הוא שהשק' כל פני אדמה היתה הויתו מן האיד העולה מן הארץ שכבר יתהוה ממנו המטר כמו שהתבאר בספר האותות. ואולם זכר זה בכאן לפי שהשלמות ביצירתו לא תגיע אלא לזמן ארוך אחר הבריאה שבראם יי' ית' בששת ימי בראשית. וכן זכר גם כן לזאת הסבה בריאת האדם לפי שהשלמות האמתי ביצירתו לא נשלם לו בעת הבריאה ג"כ וגם אח"כ לא יגיע לו כי אם בקושי גדול וזכרו גם כן לסבה שנית והו' להעמידנו על סודו' הבריאה האנושית ובאי זה תגיע לו הצלחתו ולזה שב להגיד הבריאה שספר עליה איך היתה ואמר שכבר יצר ה' ית' את האדם מהתחתונים ואמנם זר העפר לבד לפי שרוב בניינו מהעפר כמו שאמרו ז"ל ועוד כי הוית הב"ח ההולך נתיחסה אל העפר לפי שבו עמידתו אמר תוצא הארץ נפש חיה וכו' ולזאת הסבה ג"כ נתיחסה הוית האדם אל העפר והנה בסוף ההויה שם בו נשמת חיים מהעליוני' והיה האדם בזה האופן לנפש שימצא בו החיות והקיום בעצמותה מה שאין כן בשאר הב"ח כי צורותיהם אין להם עמידה כי אם בחמר. וכבר המציא השם באדם מראש שלמות בריאתו שכל בו בכח כל המושכלו' והיתה המצאתו אותו באמצעו' השכל הפועל ושם בזאת המדרגה האדם אשר יצר ר"ל שישתדל בחזקת היד להשלים שכלו ולא יפנה לעניינים אחרים ואמנם אמר זה להורות על שהכונה היתה בבריאתו לזה התכלית לבד ובעבורו נמצא לו כלים רבים והנה הצמיח הש' ית' מהמוחשות אשר בזה המציאות השפל כל ההשגה מההשגות אשר יושג בהם הערב והבלתי ערב ובכלל הטוב והרע כי זה ממה שיושג בחושי' בקלות אלא שלא תשלם זאת ההשגה אם לא באמצעות השכל כמו שזכר אחר זה וכבר יצמח מאלו המוחשות השגה אשר בה יקנה האדם החיים הנצחיים באמצעות השכל האנושי וזה אמנם יהיה לו ג"כ באמצעות השפע השופע עליו מהשכל הפועל אשר נקרא ענן בזה המשל ויצמח ג"כ מאלו המוחשות השגת הטוב והרע באמצעות השכל האנושי במה שישפע עליו מהשכל הפועל והנה זה השפע השופע על השכל ההיולאני מההשכל הפועל יתפרדו ממנו השפעות רבות יושפעו מהשכל האנושי לכחות הנפשיות ובאלו ההשפעות ישלמו לאדם פעולותיו הבחירות כלם אשר ישתדל בהם וכבר משך ה' ית' האדם ושם בו תשוקה אל שתהיה השתדלותו לעבוד ולשמור השכל אשר בו עד שישלימהו ויוציאהו מן הכח אל הפעל. וזאת התשוקה אמנם הושמה בו מצד השלמות הנראה בתחלת העניין באלו הנמצאו' הטבעיות אשר יעירו האד אל שיתבונן במה שיש מן החכמה בבריאתם ולהיות כונת ה' יתע' שיהיה השתדלותו בהשלמת השכל האנושי לבד צוה האדם שישתדל בהשגות המיוחסות אל שכל האנושי והן המושכלות אשר ישוב בהם נצי ויעזוב השגת הטו' והרע עכי בעת השתדלותו בו יבצר ממנו שלמותו האמת אשר בו יקנה החיים הנצחי' ולזה גם כן ברא ה' ית' את האשה להיות לעזר לאדם בעשותה המלאכות הצריכות לאדם לתקון גופו ובזה יהיה לו פנאי להשתדל במושכלו' ואם כבר נבראת האשה גם כן לתכלית אחר והוא קיום המין הנה זכר בכאן זה התכלית להיותו יותר נכבד ולהעיר על זה הענין ספר ד"מ שכבר אמר השם שאינו טוב באדם היות לבדו אחר שכבר נברא לזה התכלית שזכר כי הוא לבדו לא יוכל על זה בשכבר יטרך לו חלק גדול בזמנו בתקון מזונותיו ושאר המלאכו' ההכרחיות לו להעמדת גופו ולזה הסכים הש' ית' שיעשה לו עזר כנגדו והוא האשה והנה מה שיצר הש' יתע' מהב"ח ההולכי' והמעופפים אשר יתכן הרגשם לאדם בקלות הביא אל האדם לראות מה יקרא לו ר"ל להשיג מהותם אשר ייוחס בו א' מהם והוא הסדור המושכל אשר ממנו השתלשל מציאותו וכל אשר השיגהו האדם מזה בא אח' מהנמצאות הטבעיות היה שמו נפש חיה ר"ל שהמושכל ההו' כשהיגיע לאדם היה שכל נצחי והנה בזה האופן קרא האדם שמות לכל הב"ח לו בעצמו לא מצא עזר כנגדו ר"ל שכאשר השיג המושכלות וידע שלזה התכלית נברא מצא עצמו חסר עזר מתיחס לו כי הב"ח והצמחים כלם הם עזר לו. כי הם נבראים כלם לעבודתו כמו שקדם אלא שלא ישלם בהם העזר הצריך לו כי העזר ההוא צריך שיהיה מבעל שכל לפי שהמלאכות הצריכות לאדם הם כלם מסודרות מהשכל והן אשר יקראוהו הפילוסופי' השכל המעשי והנה הפיל ה' ית' תרדמה על האדם בדרך שיגיע לו השינ' ובאחד מצדדיו ברא השם חתכת בשר מכוסת קרום כמו שתהיה בריאתה בעת הבריאה אשר תהיה ברחם ומהחתכה ההיא ברא הש' יתע' את האשה כדרך שתשלם הבריאה ברחם ר"ל שיתהוו מהשפיר האברים הפנימיים והחיצוניים באופן אשר יתבאר בב"ח כן בנה מהחתיכה ההיא את האש כשצייר איבריה פנימיים וחיצוניים אלא שזאת ההויה כרגע וההויה אשר תהיה ברחם לא תשלם אלא בזמן ארוך וזאת ההויה ג"כ היתה בלתי חסרה אל הצמיחה. אבל נבראו אדם וחוה בקומתן ולזה אמרו בב"ר שהם היו בעת שנבראו כבן כ' שנה והנה כשהקיץ האדם מצא האשה הנבראת אצלו כי שם היתה בריאתה ויאמר האדם זאת הפעם מצאתי העזר שהייתי חסר כי היא ממני לזאת יקרא אשה והוא שם נגזר מן האיש כי מן האיש לוקחת ונבראה לעבודתו ולפי שהאשה הוא העזר לאדם במה שיצטרך לו לתקון גופו. הנה ראוי שיעזוב את אביו ואמו וידבק באשתו עם שבזה תועלת שני והוא שיהיו לבשר אחד והוא רמז אל החבור אשר ישלם בו קיום המין ולפי שלא השתמשו האדם ואשתו בהשגת הטוב והרע היו עומדים מבלי לבוש ולא השיגו שיהיה בזה בשת וגנו'. והנה הכח הדמיוני היה ערום יותר משאר כחות הנפש המשותפות לאדם ולשאר הב"ח ואמר לאש באמצע הכח המתעות מה זה שאינכם משתמשים בהשגת הטוב והרע אשר היא מגעת באמצעות השכל האם אמר השם שלא תשתמשו בהשגות השכל ואמרה אליו שהאשה שבהשגות המיוחסות לשכל ישתמשו ואולם בהשגות שאינם מיוחסות אל השכל בעצמות אלא שהם מגיעות באמצעות כמו העניין בהשגת הטוב והרע לא יתקרבו אליהם ולא ישתמשו בהשגתם פן יבצר מהם שלמותם ויפסק והנה השיב הכח הדמיוני לאשה שאין הענין כן אבל יתחדש להם שלמות נפלא מאד יהיו בו במדרגת השופטי' מנהיגי המדינות. והנה האשה לחלשת שכלה נתפתתה בראותה הערבות' אשר יושג בזה האופן מההשגה כי בה יושגו המזונות הערביים והפעולות הערבות בכללם עם שכבר תגיע זאת ההשגה בקלו' נפלא מה שאין כן בהשגת עץ החיים אשר בו תשלם ההצלחה ופתחה אח"כ אישה שישתמש באלו ההשגות. וכאשר השתמשו בהם והשיגו המגונה והנאה נגלה להם כי היותם ערומים הוא מגונה מאד ותפרו עלה תאנה ועשו להם חגורות לכסות ערותן כי עדיין לא היה נמצא אצלם עור ולא צמר ופשתים וכיוצא בהם שיעשו מהם לבוש או חגורות. והנה היה זה סבה שבעת שהיו נכונים לקבל שפע ה' ית' באמצעות השכל הפועל נפקד מהם זה השפע מפני השתמשותם באלו ההשגות הפחותות ואמר דרך משל שהש' יתע' קרא לאדם לפי שלא מצאו מוכן לקבל השפע האלהי ואמר לו שיגיד באי זה ענין פונה השגתו והשיב לו כי בשמעו קולו התכונן בשגלות הערוה הוא מגונה וזאת היתה סבה בשלא מצאו מוכן לקבל השפע. ר"ל השתמשותו בהשגה הטוב והרע. ואמר ה' לו ומי הודיעך שיהיה בזה מגונה האם השתמשת בהשגת הטו' והרע אשר צויתיך שלא תשתמש בו והשיב כי אשתו הסתה אותו בזה והאשה התנצלה בזה ג"כ ליי' ית' שהנחש השיאה ונתקלל מפני זה הנחש מכל הכחות הנפשיות אשר באדם המשותפות לו ולשאר הב"ח וזה שאין לו מעצמו כלי ההליכה לאשר יצטרך לדרוך אל השגתו כמו הענין בכחות המרגישות שיש להם כלים יובילום אל השגת המוחשים כמו העין אשר יושג בו הראות והאוזן אשר יושגו בו הקולות ואולם הדמיון אין לו כלים להשיג מעצמו דבר אבל ישיג לבד מה שישיגוהו החושים ויגיעוהו אליו באמצעות החוש המשותף כמו שהתבאר בספר הנפש. והנה לזאת הסבה ימצא שיגיע בקושי גדול מה שיגיע לו מהציור אל הדמיון לרב התבודדות הצריך לו בזה הציור מבין שאר כחות הנפש. ואולם הכח הזוכר והשומר והבורר הנה הם משיגים מושגיהם בקלות ואע"פ שהם מגיעים להם מהחושים לפי שלא יצטרכו בהשגתם אל הציור כמו שביאר בספר הנפש. ולכן נזכור דברי' רבים יחד ולא יתכן שנצייר יחד בכח הדמיוני כי אם דבר אחד. ונתקלל שיהיה מאכלו עפר ר"ל שלא תעלה השגתו זולת להשגת הדברים הפרטיי' כמו הענין בשאר כחות החמריות ובהם גם כן יגיע לו מהכזב הרבה כמו שהתבאר בספר הנפש מה שאינו כן בשאר הכחות המשיגות. ר"ל שהשגותם המיוחדות להן לא ימצא בהם הכזב ונתקלל עוד שאפי' בינו ובין האשה ששלמה ההסכמה בזה העניין אשר השיאה בו תהיה האיבה עד שהאחד ינגד לשני לפעולתו. וזה כי היא תשתמש בהשגת החושים אשר יבטלו פעולות הדמיון בעת פעולתם ובין זרעה והן אלו ההשגות החושיות ינגדו לזרע הדמיון והם הצורות הדומיונייות אשר כבר הגיעו הדמיון לא יוכל על ציורם בעת השתמשות הנפש בשאר ההשגות אלא שסדור הענין יהיה כן שהיא וזרעה יבטלו פעולות הדמיון. בראשונה בהרגישם הדברים המוחשים כי אז תבטל פעולתו והוא יבטל פעולתם בסוף כשיקח מהם אלו ההשגות החושיות ויציירם וזה הענין כלו על דרך משל כמו שתראה. ואל האשה אמר כי לחלשת שכלה לא הושגח בריאתה באופן אשר הגיעה ההשגחה בו בבריאת האדם וזה שכבר יקרוה דברים רבים מכאיבים כגון הוסת וההריון והלידה ושתשוקתה אמנם הושמה לעבודת בעלה והוא ימשל בה. ואמנם היה זה כן לפי שכל מה שהיה הדבר יותר נכבד השגיח ה' בבריאתו יותר כמו שהתבאר בב"ח. ולאדם אמר כי לפנותו להשגות האחרות זולת המכונות לו והם המושכלות הנה האדמה שיצמחו ממנה אלו ההשגות במה שיושג בה מהדברים המוחשים כמו שקדם נתקללה שלא יגיעו ממנה כי אם בקושי ובצער גדול המושכלות בסדר המושכל אשר לדברים הטבעיים והוא אשר תהיה בו הצלחת הנפש ויתכן עם זה שתצמיח קוצים כאשר לא הגיע בחוש כל מה שיצטרך לקנות אלו המושכלות כי הטעות יקראה באלו ההשגות הרב מצד החמר כי הוא יטעה ויביא לחשוב במשיגים המקריים שהם עצמיים ולזה ייטעה האדם ויחשוב שהשיג הדברי' הכוללי' המיוחסי' לשכל ולא תעלה השגתו כי אם להשגות הפרטיו' אשר ישותף בהשגתם האדם עם שאר הב"ח ובזה קולל האדם שישיג בקושי גדול מושכל אמתי עד יום מותו. והנה קרא האדם שם אשתו חוה כאשר השיג בחלשת שכלה ר"ל שלא עלתה מדרגתה על שאר הב"ח עלוי רב ואם היא בעלת שכל כי רוב השתמשותה אמנם הוכן לה בדברים הגופיים לחלשת שכלה ולהיותם לעבודת האדם ולזה הוא רחוק שיגיע לה שלמות השכל אלא שעכ"פ היא יותר נכבדת וכלם הם לעבודתה ולזה תארה בשהיא אם כל חי. ולזאת הסבה בא בכאן ספור קריאת זה השם ואפשר שנאמ' שהרצון במה שאמרה התור' אם כל חי מדבר כדרך יבא כל בשר שהו' שב אל האדם לבד ולזה קראה חוה ואולם זכר זה בזה המקום כי הם כשנטו בהשגת הערב נמשכו בפעל המשגל והתבונן האדם בתועלת המגיע מזה הפעל ואז נתבאר לו שממנו יצא הזרע אשר יהיה ממנו המין האנושי. ולפי שכבר זכר האד' ואשתו השיגו בגנות אשר ישיגם מצד היותם ערומים זכר שכבר המציא ה' יתע' להן לבוש נכבד ילבשוהו על עור בשרם והנה המציא ה' יתע' אלו הכתנות בפליאה כמו העניין במה שהמציא בששת ימי בראשית ואולם המציאם להן להיות האדם הכרחיי ללבוש ישמרהו מהיזק האויר המקיף ואלו המתין זה עד שתתבאר להם דרך המלאכה הזאת יארך הזמן וימותו אם מהחום אם מהקור. וספר אחר זה שכבר התרעם ה' על אדם מצר מה שמרה בו ואמר הנה האר היה כאחד ממנו. ר"ל שנתן לו כח וכלי ישתמש בו במושכלו' באופן מתיחס להשגת העליונים וכבר נשתמש בו בהשגת הטוב והרע וכאלו אמ' האם שמתי האדם בזה האופן הנכבד מהבריאה שישתתף בה לעליוני' כדי שישתמש בהשגת הטוב והרע ועתה שמרה והחטיא כונתו האם יש תוחלת שישלח ידו ולקח גם מעץ החיים עם זאת ההשגה אשר ישתמש בה ואכל ממנו וחי לעולם שהוא תכלית המכוון בו זה בלתי אפש' שהשגתו בטוב והרע תמנעהו מהשתדל בזה כל מה שיתמיד להשתמש בה ובהיות הענין כן הנה לשוא ישאר בהשתדלות השלמת השכל אשר הושם בו מתחת העניין כמו שקדם ולזה שלחו ה' יתע' מגן עדן לעבוד את האדמה אשר לוקח משם עד שישתדל שיגיע לו ממנה מן החוש כל המוחשות הצריכות לו בהשגת המושכלות ולפי שכבר גרש האדם שהושם בעדן לעבדו ולשמרו זכר שכבר המציא ה' יתע' כלים ישמור בהם שמירת עץ החיים אשר הוא המכוון מהגן ואלו הכלים הם הצורות הדמיונות ושפע שכל הפועל המגיע לשכל ההיולאני אשר ישלם בהם השגת המושכלות כמו שהתבאר בספר הנפש ובמ"י מה שנראה לנו בזה הספור והוא נפלא מאד ומסכים לאמת וללשון המשל אשר נאמר בו לפי מה שיתבאר לך אם תתבונן בדרך המשלים אשר נהגו להשתמש בהן הנביאים והחכמים. וראוי שתדע שמה שבא הנה מזה הספור הנפלא הוא על דרך משל לבאר שהחסרון שהגיע בבריאת האדם עד שלא יתכן שיגיע אל השלמות המכוון בו כי אם בקושי עצום היה מפני שאי אפשר בו שיקבל באופן יותר שלם עד שהכלים בעצמם שהושמו בו לדרוך על השלמות יהיו כלים לאדם מצד בחירתו לדרוך אל החסרון ומן ההכרח היה שיהיה בעל בחירה להיותו בעל שכל ואולם היו הבעלי שכל העליונים באופן א' מהפועל תמיד עם היותם בעלי בחירה לפי שהם בוחרים תמיד הטוב ואין בהן התחלה הפכית תשים בהן בחירות מקבילות. ואולם האדם להיותו מורכב מחמר והצורה היו בו בהכרח בחירות מקבילות ומי שיאמר שיותר טוב היה שלא תהיה לאדם בחירה יאמר שיותר טוב היה שלא יהיה בעל שכל לפי שהיותו בעל שכל יחייב שיהיה בעל בחירה ועוד שהבחירה היתה הכרחית לו להשגיח בו להצילו מהרבה מהרעות הנכונות לבא עליו מצד הערכת הככבים כמו שביארנו במ"י ובביאורנו לספר איוב. ועוד שאם הודינו שיהיה אפשר שיהיה אדם בעל שכל ולא יהיה בעל בחירה הנה כשהונח העניין כן יתחייב המנע השלמו' מהאדם וזה כי כבר יתחייב מזה שתהיינה פעולותיו כלם מסודרות בחייוב ולא יתחלף בהם קצת אישי בני האדם מקצת להיותם ממין אחד וימשך לזה שיעשה כל אחד מהאנשים כל המלאכות הצריכות לו להעמדת גופו והוא מבואר שלא יספיק לו זמנו לאלו המלאכות וימנע ממנו השלמו' האנושי ובהיות הענין כן הוא מבואר שהבחירה שהונחה באדם הוא כלי להגיעו אל השלמו' ואם כבר יקרה ממנה שתהיה כלי אל החסרון הנה זהו מפני טבע החמר וכן העניין בכחות הנפשיות באדם ר"ל שהם הוכנו באדם להגיעו אל השלמות והם בעינם סבה ג"כ להגיעו אל החסרון מפני טבע החמר' ובהיו' הענין כן ר"ל שהכונה האלהית אשר היתה בריאת האדם להגיעו אל השלמות האמתי והכינה לו מפני זה כלים רבים כמו שקדם כי תמצא הבחירה האנושית חולקת עליהם ומנגדת לה הנה מן ההכרח היה שיונח בכאן נימוס תוריי יכריח הבחירה להכנע אל הכוונה האלהית עד שישלם בזה כמו שכוון בבריאה האנושית ולהיות קניין המושכלות מגיע לאדם בהכרח בק